END_IF;
// >>> BULK_SYNC_ANCHOR: FB_System_Health <<<

L_Zone_Hold_MS := VI_Min_Hold_MS / 2;
IF L_Zone_Hold_MS < 60000 THEN L_Zone_Hold_MS := 60000; END_IF;

IF NOT L_Predictive_Initialized THEN
    L_Last_Room_Avg := VI_Room_Temp_Avg;
    L_Filtered_Trend := 0.0;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
        L_Last_Zone_Temp[L_i] := VI_Room_Temps[L_i];
        L_Zone_Filtered_Trend[L_i] := 0.0;
        L_Zone_Last_Adjust_Accept_MS[L_i] := VI_System_Time_MS;
        L_Zone_Last_Level_Accept_MS[L_i] := VI_System_Time_MS;
        GVL_HEATING_POLICY.G_Zone_Target_Adjustment[L_i] := 0.0;
        GVL_HEATING_POLICY.G_Zone_Thermal_Response[L_i] := 0.0;
        GVL_HEATING_POLICY.G_Zone_Thermal_Demand[L_i] := 0.0;
        GVL_HEATING_POLICY.G_Zone_Time_To_Heat_MS[L_i] := 0;
        GVL_HEATING_POLICY.G_Zone_Preheat_Needed[L_i] := FALSE;
    END_FOR;
    L_Predictive_Initialized := TRUE;
END_IF;

L_Trend := VI_Room_Temp_Avg - L_Last_Room_Avg;
L_Last_Room_Avg := VI_Room_Temp_Avg;
L_Filtered_Trend := (L_Filtered_Trend * 0.8) + (L_Trend * 0.2);

L_Predictive_Adjustment := 0.0;
IF (L_Filtered_Trend < -0.03) AND (VI_Room_Temp_Avg < (VI_Target_Temp + 0.5)) THEN
    L_Predictive_Adjustment := 1.0;
ELSIF L_Filtered_Trend > 0.03 THEN
    L_Predictive_Adjustment := -0.5;
END_IF;
IF L_Predictive_Adjustment > 1.0 THEN L_Predictive_Adjustment := 1.0; END_IF;
IF L_Predictive_Adjustment < -1.0 THEN L_Predictive_Adjustment := -1.0; END_IF;
GVL_HEATING_POLICY.G_Policy_Predictive_Adjustment := L_Predictive_Adjustment;
GVL_HEATING_POLICY.G_Policy_Predictive_Active := ABS(L_Predictive_Adjustment) > 0.001;

L_Room_Error := VI_Target_Temp - VI_Room_Temp_Avg;
L_Supply_Error := VI_Target_Temp - VI_Supply_Temp;
L_DeltaT := VI_Supply_Temp - VI_Return_Temp;
L_Quality := 0.0;
IF L_Room_Error > 1.0 THEN L_Quality := L_Quality + 2.0; END_IF;
IF L_Supply_Error > 1.0 THEN L_Quality := L_Quality + 1.0; END_IF;
IF L_DeltaT < 3.0 THEN L_Quality := L_Quality + 1.0; END_IF;
L_Improving := L_Quality < L_Last_Quality;
L_Stable := L_Quality = 0.0;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
    L_Zone_Error := VI_Target_Temp - VI_Room_Temps[L_i];
    L_Zone_Quality := 0.0;
    IF L_Zone_Error > 1.0 THEN L_Zone_Quality := L_Zone_Quality + 2.0; END_IF;
    IF VI_Floor_Temps[L_i] < (VI_Target_Temp - 2.0) THEN L_Zone_Quality := L_Zone_Quality + 1.0; END_IF;

    L_Zone_Trend := VI_Room_Temps[L_i] - L_Last_Zone_Temp[L_i];
    L_Last_Zone_Temp[L_i] := VI_Room_Temps[L_i];
    L_Zone_Filtered_Trend[L_i] := (L_Zone_Filtered_Trend[L_i] * 0.8) + (L_Zone_Trend * 0.2);

    L_Zone_Inertia := GVL_HEATING_POLICY.G_Zone_Thermal_Inertia[L_i];
    IF L_Zone_Inertia < 0.2 THEN L_Zone_Inertia := 1.0; END_IF;
    IF L_Zone_Inertia > 3.0 THEN L_Zone_Inertia := 3.0; END_IF;

    GVL_HEATING_POLICY.G_Zone_Thermal_Response[L_i] := L_Zone_Filtered_Trend[L_i] / L_Zone_Inertia;
    GVL_HEATING_POLICY.G_Zone_Thermal_Demand[L_i] := L_Zone_Error * L_Zone_Inertia;

    IF (L_Zone_Error > 0.0) AND (GVL_HEATING_POLICY.G_Zone_Thermal_Response[L_i] > 0.001) THEN
        L_Time_To_Heat_MS_REAL := (L_Zone_Error / GVL_HEATING_POLICY.G_Zone_Thermal_Response[L_i]) * 60000.0;
        IF L_Time_To_Heat_MS_REAL > 7200000.0 THEN
            GVL_HEATING_POLICY.G_Zone_Time_To_Heat_MS[L_i] := 7200000;
        ELSIF L_Time_To_Heat_MS_REAL < 0.0 THEN
            GVL_HEATING_POLICY.G_Zone_Time_To_Heat_MS[L_i] := 0;
        ELSE
            GVL_HEATING_POLICY.G_Zone_Time_To_Heat_MS[L_i] := REAL_TO_UDINT(L_Time_To_Heat_MS_REAL);
        END_IF;
    ELSE
        GVL_HEATING_POLICY.G_Zone_Time_To_Heat_MS[L_i] := 0;
    END_IF;

    GVL_HEATING_POLICY.G_Zone_Preheat_Needed[L_i] := (GVL_HEATING_POLICY.G_Zone_Time_To_Heat_MS[L_i] > 1800000) AND (L_Zone_Error > 0.5);

    L_Zone_Thermal_Bias := 0.0;
    IF GVL_HEATING_POLICY.G_Zone_Thermal_Demand[L_i] > 2.0 THEN
        L_Zone_Thermal_Bias := 0.5;
    ELSIF GVL_HEATING_POLICY.G_Zone_Thermal_Demand[L_i] > 1.0 THEN
        L_Zone_Thermal_Bias := 0.25;
    ELSIF GVL_HEATING_POLICY.G_Zone_Thermal_Demand[L_i] < -1.0 THEN
        L_Zone_Thermal_Bias := -0.4;
    END_IF;

    IF GVL_HEATING_POLICY.G_Zone_Preheat_Needed[L_i] THEN
        L_Zone_Thermal_Bias := L_Zone_Thermal_Bias + 0.4;
    END_IF;

    L_Zone_Desired_Adjustment := L_Zone_Thermal_Bias;
    IF (L_Zone_Filtered_Trend[L_i] < -0.03) AND (VI_Room_Temps[L_i] < (VI_Target_Temp + 0.5)) THEN
        L_Zone_Desired_Adjustment := L_Zone_Desired_Adjustment + 0.8;
    ELSIF L_Zone_Filtered_Trend[L_i] > 0.03 THEN
        L_Zone_Desired_Adjustment := L_Zone_Desired_Adjustment - 0.3;
    END_IF;
    IF L_Zone_Desired_Adjustment > 1.0 THEN L_Zone_Desired_Adjustment := 1.0; END_IF;
    IF L_Zone_Desired_Adjustment < -1.0 THEN L_Zone_Desired_Adjustment := -1.0; END_IF;

    IF ABS(L_Zone_Desired_Adjustment - GVL_HEATING_POLICY.G_Zone_Target_Adjustment[L_i]) > 0.001 THEN
        IF (VI_System_Time_MS - L_Zone_Last_Adjust_Accept_MS[L_i]) >= L_Zone_Hold_MS THEN
            GVL_HEATING_POLICY.G_Zone_Target_Adjustment[L_i] := L_Zone_Desired_Adjustment;
            L_Zone_Last_Adjust_Accept_MS[L_i] := VI_System_Time_MS;
        END_IF;
    END_IF;

    GVL_HEATING_POLICY.G_Zone_Improving[L_i] := (L_Zone_Quality < GVL_HEATING_POLICY.G_Zone_Quality[L_i]);
    GVL_HEATING_POLICY.G_Zone_Stable[L_i] := (L_Zone_Quality = 0.0);

    L_Zone_Desired_Level := GVL_HEATING_POLICY.G_Zone_Self_Level[L_i];
    IF GVL_HEATING_POLICY.G_Zone_Stable[L_i] THEN
        L_Zone_Desired_Level := 0;
    ELSIF GVL_HEATING_POLICY.G_Zone_Improving[L_i] THEN
        L_Zone_Desired_Level := GVL_HEATING_POLICY.G_Zone_Self_Level[L_i] - 1;
    ELSIF L_Zone_Quality >= 3.0 THEN
        L_Zone_Desired_Level := GVL_HEATING_POLICY.G_Zone_Self_Level[L_i] + 1;
    END_IF;
    IF L_Zone_Desired_Level > 2 THEN L_Zone_Desired_Level := 2; END_IF;
    IF L_Zone_Desired_Level < 0 THEN L_Zone_Desired_Level := 0; END_IF;
    IF L_Zone_Desired_Level <> GVL_HEATING_POLICY.G_Zone_Self_Level[L_i] THEN
        IF (VI_System_Time_MS - L_Zone_Last_Level_Accept_MS[L_i]) >= L_Zone_Hold_MS THEN
            GVL_HEATING_POLICY.G_Zone_Self_Level[L_i] := L_Zone_Desired_Level;
            L_Zone_Last_Level_Accept_MS[L_i] := VI_System_Time_MS;
        END_IF;
    END_IF;

    GVL_HEATING_POLICY.G_Zone_Quality[L_i] := L_Zone_Quality;
END_FOR;

IF VI_RootCause <> L_Last_Cause THEN
    L_Same_Cause_Since := VI_System_Time_MS;
    L_Self_Level := 0;
END_IF;
L_Last_Cause := VI_RootCause;

IF L_Stable THEN
    L_Self_Level := 0;
ELSIF L_Improving THEN
    L_Self_Level := L_Self_Level - 1;
ELSIF (VI_System_Time_MS - L_Same_Cause_Since) > (VI_Min_Hold_MS * 2) AND (VI_RootConfidence > 0.8) AND (L_Quality >= 3.0) THEN
    L_Self_Level := L_Self_Level + 1;
END_IF;
IF L_Self_Level > 2 THEN L_Self_Level := 2; END_IF;
IF L_Self_Level < 0 THEN L_Self_Level := 0; END_IF;

L_Raw_Mode := E_Heating_Policy_Mode.HPM_NORMAL;
L_Raw_Block := FALSE;
L_Raw_Target_Adjustment := L_Predictive_Adjustment;
L_Raw_Priority_Multiplier := 1.0;
L_Force_Immediate := FALSE;

IF VI_Emergency_Stop OR VI_Gas_Safety THEN
    L_Raw_Mode := E_Heating_Policy_Mode.HPM_SAFETY_BLOCK;
    L_Raw_Block := TRUE;
    L_Raw_Target_Adjustment := 0.0;
    L_Raw_Priority_Multiplier := 1.0;
    L_Force_Immediate := TRUE;
ELSIF VI_RootCause = E_Heating_RootCause.RC_IO_OFFLINE THEN
    L_Raw_Mode := E_Heating_Policy_Mode.HPM_DEGRADED;
    L_Raw_Block := TRUE;
    L_Raw_Target_Adjustment := 0.0;
    L_Raw_Priority_Multiplier := 1.0;
    L_Force_Immediate := TRUE;
ELSIF VI_RootConfidence >= 0.6 THEN
    CASE VI_RootCause OF
        E_Heating_RootCause.RC_NO_HEAT_TRANSFER:
            L_Raw_Mode := E_Heating_Policy_Mode.HPM_DEGRADED;
            L_Raw_Target_Adjustment := L_Raw_Target_Adjustment + 3.0 + TO_REAL(L_Self_Level);
        E_Heating_RootCause.RC_PUMP_FAILURE:
            L_Raw_Mode := E_Heating_Policy_Mode.HPM_FAULT_ISOLATION;
            L_Raw_Priority_Multiplier := 0.5 - (0.1 * TO_REAL(L_Self_Level));
        E_Heating_RootCause.RC_VALVES_CLOSED:
            L_Raw_Mode := E_Heating_Policy_Mode.HPM_FAULT_ISOLATION;
            L_Raw_Target_Adjustment := L_Raw_Target_Adjustment - 2.0;
        E_Heating_RootCause.RC_NO_FLAME,
        E_Heating_RootCause.RC_BOILER_ERROR:
            L_Raw_Mode := E_Heating_Policy_Mode.HPM_DEGRADED;
            L_Raw_Priority_Multiplier := 0.7;
        ELSE
            IF VI_System_Mode = E_System_Operating_Mode.MODE_DEGRADED THEN L_Raw_Mode := E_Heating_Policy_Mode.HPM_DEGRADED; END_IF;
    END_CASE;
ELSE
    IF VI_System_Mode = E_System_Operating_Mode.MODE_DEGRADED THEN L_Raw_Mode := E_Heating_Policy_Mode.HPM_DEGRADED; END_IF;
END_IF;

IF L_Raw_Target_Adjustment > 5.0 THEN L_Raw_Target_Adjustment := 5.0; END_IF;
IF L_Raw_Target_Adjustment < -3.0 THEN L_Raw_Target_Adjustment := -3.0; END_IF;
IF L_Raw_Priority_Multiplier < 0.3 THEN L_Raw_Priority_Multiplier := 0.3; END_IF;
IF L_Raw_Priority_Multiplier > 1.0 THEN L_Raw_Priority_Multiplier := 1.0; END_IF;

L_Effective_Hold_MS := VI_Min_Hold_MS;
IF VI_RootConfidence >= 0.9 THEN L_Effective_Hold_MS := VI_Min_Hold_MS / 2; END_IF;

IF NOT L_Initialized THEN
    L_Held_Mode := L_Raw_Mode;
    L_Held_Block := L_Raw_Block;
    L_Held_Target_Adjustment := L_Raw_Target_Adjustment;
    L_Held_Priority_Multiplier := L_Raw_Priority_Multiplier;
    L_Last_Accept_MS := VI_System_Time_MS;
    L_Initialized := TRUE;
ELSIF L_Force_Immediate THEN
    L_Held_Mode := L_Raw_Mode;
    L_Held_Block := L_Raw_Block;
    L_Held_Target_Adjustment := L_Raw_Target_Adjustment;
    L_Held_Priority_Multiplier := L_Raw_Priority_Multiplier;
    L_Last_Accept_MS := VI_System_Time_MS;
ELSIF (L_Raw_Mode <> L_Held_Mode) OR (ABS(L_Raw_Target_Adjustment - L_Held_Target_Adjustment) > 0.001) OR (ABS(L_Raw_Priority_Multiplier - L_Held_Priority_Multiplier) > 0.001) OR (L_Raw_Block <> L_Held_Block) THEN
    IF (VI_System_Time_MS - L_Last_Accept_MS) >= L_Effective_Hold_MS THEN
        L_Held_Mode := L_Raw_Mode;
        L_Held_Block := L_Raw_Block;
        L_Held_Target_Adjustment := L_Raw_Target_Adjustment;
        L_Held_Priority_Multiplier := L_Raw_Priority_Multiplier;
        L_Last_Accept_MS := VI_System_Time_MS;
    END_IF;
END_IF;

VO_Policy_Mode := L_Held_Mode;
VO_Block_Heating := L_Held_Block;
VO_Target_Adjustment := L_Held_Target_Adjustment;
VO_Priority_Multiplier := L_Held_Priority_Multiplier;
VO_Self_Tune_Active := (L_Self_Level > 0);
VO_Self_Tune_Level := L_Self_Level;
VO_Feedback_Stable := L_Stable;
VO_Feedback_Improving := L_Improving;
VO_Feedback_Quality := L_Quality;
L_Last_Quality := L_Quality;

// Упрощенная модель износа
IF VI_Nominal_Life > 0 THEN
    VO_Remaining_Percent := TO_BYTE(100 - (VI_Runtime_Hours * 100 / VI_Nominal_Life));
ELSE
    VO_Remaining_Percent := 0;
END_IF;

VO_Maintenance_Req := (VO_Remaining_Percent < 10);

// Extracted candidate from PRG_Heating S3.
// Not connected yet.
// Donor logic remains in PRG_Heating until all extracted candidates are prepared.

GVL_STATUS.G_Diagnostics.Backup_Pump_Out_Of_Service := NOT GVL_CONFIG.G_Backup_Circulation_Pump_In_Service;
GVL_STATUS.G_Diagnostics.Electric_Heater_Out_Of_Service := NOT GVL_CONFIG.G_Electric_Heater_In_Service;

fbDiagEventManager(
    VI_Code := GVL_CONFIG.ERR_BACKUP_PUMP_OUT_OF_SERVICE,
    VI_Severity := 2,
    VI_Active := NOT GVL_CONFIG.G_Backup_Circulation_Pump_In_Service,
    VI_Timestamp := VI_System_Time_MS,
    VI_Source := 400,
    VIO_Events := GVL_STATUS.G_Diagnostics_Events,
    VIO_Count := GVL_STATUS.G_Diagnostics_Count
);

fbDiagEventManager(
    VI_Code := GVL_CONFIG.ERR_ELECTRIC_HEATER_OUT_OF_SERVICE,
    VI_Severity := 2,
    VI_Active := NOT GVL_CONFIG.G_Electric_Heater_In_Service,
    VI_Timestamp := VI_System_Time_MS,
    VI_Source := 401,
    VIO_Events := GVL_STATUS.G_Diagnostics_Events,
    VIO_Count := GVL_STATUS.G_Diagnostics_Count
);

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    GVL_STATUS.G_Diagnostics.Manifold_Pump_Out_Of_Service[L_i] := NOT GVL_CONFIG.G_Manifold_Pump_In_Service[L_i];

    fbDiagEventManager(
        VI_Code := GVL_CONFIG.ERR_MANIFOLD_PUMP_OUT_OF_SERVICE,
        VI_Severity := 2,
        VI_Active := NOT GVL_CONFIG.G_Manifold_Pump_In_Service[L_i],
        VI_Timestamp := VI_System_Time_MS,
        VI_Source := 410 + L_i,
        VIO_Events := GVL_STATUS.G_Diagnostics_Events,
        VIO_Count := GVL_STATUS.G_Diagnostics_Count
    );
END_FOR;

GVL_STATUS.G_Diagnostics.DHW_Heating_Pump_Out_Of_Service := NOT GVL_CONFIG.G_DHW_Heating_Pump_In_Service;
GVL_STATUS.G_Diagnostics.DHW_Circ_Pump_Out_Of_Service := NOT GVL_CONFIG.G_DHW_Circ_Pump_In_Service;

fbDiagEventManager(
    VI_Code := GVL_CONFIG.ERR_DHW_HEATING_PUMP_OUT_OF_SERVICE,
    VI_Severity := 2,
    VI_Active := NOT GVL_CONFIG.G_DHW_Heating_Pump_In_Service,
    VI_Timestamp := VI_System_Time_MS,
    VI_Source := 420,
    VIO_Events := GVL_STATUS.G_Diagnostics_Events,
    VIO_Count := GVL_STATUS.G_Diagnostics_Count
);

fbDiagEventManager(
    VI_Code := GVL_CONFIG.ERR_DHW_CIRC_PUMP_OUT_OF_SERVICE,
    VI_Severity := 2,
    VI_Active := NOT GVL_CONFIG.G_DHW_Circ_Pump_In_Service,
    VI_Timestamp := VI_System_Time_MS,
    VI_Source := 421,
    VIO_Events := GVL_STATUS.G_Diagnostics_Events,
    VIO_Count := GVL_STATUS.G_Diagnostics_Count
);

fbDiagEventManager(
    VI_Code := GVL_CONFIG.ERR_FREEZE_HARDWARE_FAILED,
    VI_Severity := 4,
    VI_Active := GVL_STATE.G_Freeze_Hardware_Failed,
    VI_Timestamp := VI_System_Time_MS,
    VI_Source := 430,
    VIO_Events := GVL_STATUS.G_Diagnostics_Events,
    VIO_Count := GVL_STATUS.G_Diagnostics_Count
);

// >>> BULK_SYNC_ANCHOR: FB_Heating_Diagnostics <<<

// === SERIALIZE PERSIST STRUCT → BUFFER ===

// System Mode
VIO_Persist_Buffer[0] := TO_BYTE(TO_INT(VI_PersistStruct.System_Mode));

// Gas
IF VI_PersistStruct.Safety_Gas_Latched THEN
    VIO_Persist_Buffer[1] := BYTE#1;
ELSE
    VIO_Persist_Buffer[1] := BYTE#0;
END_IF;

// Smoke
IF VI_PersistStruct.Safety_Smoke_Latched THEN
    VIO_Persist_Buffer[2] := BYTE#1;
ELSE
    VIO_Persist_Buffer[2] := BYTE#0;
END_IF;

// Leak
IF VI_PersistStruct.Safety_Leak_Latched THEN
    VIO_Persist_Buffer[3] := BYTE#1;
ELSE
    VIO_Persist_Buffer[3] := BYTE#0;
END_IF;

// DHW Pump
IF VI_PersistStruct.DHW_Heating_Pump THEN
    VIO_Persist_Buffer[4] := BYTE#1;
ELSE
    VIO_Persist_Buffer[4] := BYTE#0;
END_IF;

// === END SERIALIZE ===

L_Persist_Buffer_Changed :=
    (VIO_Persist_Buffer[0] <> VIO_Last_Written_Persist_Buffer[0]) OR
    (VIO_Persist_Buffer[1] <> VIO_Last_Written_Persist_Buffer[1]) OR
    (VIO_Persist_Buffer[2] <> VIO_Last_Written_Persist_Buffer[2]) OR
    (VIO_Persist_Buffer[3] <> VIO_Last_Written_Persist_Buffer[3]) OR
    (VIO_Persist_Buffer[4] <> VIO_Last_Written_Persist_Buffer[4]);

VO_NVRAM_Cmd := 0;
VO_NVRAM_Offset := 0;

IF VIO_Apply_Settings THEN
    // explicit config apply requests a controlled write
    // keep flag set until successful write confirmation
    VO_NVRAM_Cmd := 1;

ELSIF L_Persist_Buffer_Changed THEN
    // controlled write: no more often than once per 60 seconds
    IF (VIO_Last_Persist_Write_MS = 0) OR
       ((VI_System_Time_MS - VIO_Last_Persist_Write_MS) >= 60000) THEN
        VO_NVRAM_Cmd := 1;
    END_IF;
END_IF;

fbNVRAMManager(
    VI_Command := VO_NVRAM_Cmd,
    VI_Offset := VO_NVRAM_Offset,
    VI_DataRef := VIO_Persist_Buffer[0],
    VI_DataSize := 5,
    VI_System_Time_MS := VI_System_Time_MS,
    VI_Operator_ID := 'SYSTEM',
    VI_IsActivePLC := VI_IsActivePLC,
    VI_TwoPersonConfirmation := FALSE,
    VO_Done => VO_NVRAM_Done,
    VO_Error => VO_NVRAM_Err,
    VO_ErrorID => VO_NVRAM_ErrID
);

IF (VO_NVRAM_Cmd = 1) AND VO_NVRAM_Done AND NOT VO_NVRAM_Err THEN
    VIO_Last_Written_Persist_Buffer[0] := VIO_Persist_Buffer[0];
    VIO_Last_Written_Persist_Buffer[1] := VIO_Persist_Buffer[1];
    VIO_Last_Written_Persist_Buffer[2] := VIO_Persist_Buffer[2];
    VIO_Last_Written_Persist_Buffer[3] := VIO_Persist_Buffer[3];
    VIO_Last_Written_Persist_Buffer[4] := VIO_Persist_Buffer[4];
    VIO_Last_Persist_Write_MS := VI_System_Time_MS;
    VIO_Apply_Settings := FALSE;
END_IF;

// Normalize count to analyzer bounds
L_Count := UDINT_TO_INT(VI_Data.record_count);
IF L_Count < 0 THEN
    L_Count := 0;
END_IF;
IF L_Count > GVL_CONSTANTS.C_MAX_TREND_DATA_POINTS THEN
    L_Count := GVL_CONSTANTS.C_MAX_TREND_DATA_POINTS;
END_IF;

// Copy source values into analyzer-compatible buffer
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_TREND_DATA_POINTS DO
    L_Data_Copy[L_i] := 0.0;
END_FOR;

IF L_Count > 0 THEN
    FOR L_i := 1 TO L_Count DO
        L_Data_Copy[L_i] := VI_Data.values[L_i];
    END_FOR;
END_IF;

fbAnalyzer(
    VI_Count := L_Count,
    VI_Data := L_Data_Copy,
    VO_Average => VO_Average,
    VO_Max => VO_Max,
    VO_Min => VO_Min,
    VO_Trend_Up => VO_Trend_Up,
    VO_Trend_Down => VO_Trend_Down
);

// ==============================================================================
// System redundancy orchestrator helper
//
// Internal helper for PRG_System.
// Owns PLC role calculation, heartbeat output projection, and synced-state apply.
// ==============================================================================



// Build local state snapshot for replication.
VIO_Local_State.System_Time_MS := GVL_STATUS.G_System_Time_MS;
VIO_Local_State.Current_Scenario := GVL_STATUS.G_Current_Scenario;
VIO_Local_State.Security_Armed := GVL_ALARM.G_Security_Armed;
VIO_Local_State.Active_Alarms := GVL_ALARM.G_Active_Alarm_Count;
VIO_Local_State.Zone_Valves := GVL_STATE.G_Zone_Valves;
VIO_Local_State.Manifold_Pumps := GVL_STATE.G_Manifold_Pumps;
VIO_Local_State.Lighting_States := GVL_STATE.G_Lighting_Levels;
VIO_Local_State.Blinds_Positions := GVL_STATE.G_Blinds_Positions;
VIO_Local_State.Socket_States := GVL_STATE.G_Socket_States;
VIO_Local_State.Gas_Valve_Closed := GVL_COMMAND.G_Gas_Valve_Close;
VIO_Local_State.Water_Valves_Closed := GVL_COMMAND.G_Close_Valve_36;
VIO_Local_State.Version := VIO_Local_State.Version + 1;

fbRedundancy(
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS,
    VI_Local_PLC_ID := GVL_STATUS.G_PLC_ID,
    VI_Remote_Pulse := GVL_IO.DI_Partner_Pulse,
    VI_Remote_Is_Active := GVL_IO.DI_Partner_Active,
    VI_Gateway_Ping_OK := GVL_GATEWAY.G_Gateway_Ping_OK,
    VI_Local_State := VIO_Local_State,
    VI_Remote_State := VIO_Remote_State
);

GVL_STATUS.G_Is_Active_PLC := (fbRedundancy.VO_Local_Role = E_PLC_ROLE.ROLE_ACTIVE);
GVL_IO.DO_Heartbeat_Pulse := fbRedundancy.VO_Local_Pulse;
GVL_IO.DO_Active_Status := GVL_STATUS.G_Is_Active_PLC;

IF fbRedundancy.VO_State_Updated THEN
    GVL_STATUS.G_Current_Scenario := fbRedundancy.VO_Synced_State.Current_Scenario;
    GVL_ALARM.G_Security_Armed := fbRedundancy.VO_Synced_State.Security_Armed;
    GVL_STATE.G_Zone_Valves := fbRedundancy.VO_Synced_State.Zone_Valves;
    GVL_STATE.G_Manifold_Pumps := fbRedundancy.VO_Synced_State.Manifold_Pumps;
    GVL_STATE.G_Lighting_Levels := fbRedundancy.VO_Synced_State.Lighting_States;
    GVL_STATE.G_Blinds_Positions := fbRedundancy.VO_Synced_State.Blinds_Positions;
    GVL_STATE.G_Socket_States := fbRedundancy.VO_Synced_State.Socket_States;
    GVL_COMMAND.G_Gas_Valve_Close := fbRedundancy.VO_Synced_State.Gas_Valve_Closed;
    GVL_COMMAND.G_Close_Valve_36 := fbRedundancy.VO_Synced_State.Water_Valves_Closed;
    VIO_Local_State.Version := fbRedundancy.VO_Synced_State.Version;
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_System_Redundancy_Orchestrator <<<

L_Found_Index := 0;
L_Was_Active := FALSE;

FOR L_i := 1 TO VIO_Count DO
    IF (VIO_Events[L_i].Code = VI_Code) AND (VIO_Events[L_i].Source = VI_Source) THEN
        L_Found_Index := L_i;
        L_Was_Active := VIO_Events[L_i].Active;
    END_IF;
END_FOR;

IF VI_Active THEN
    IF L_Found_Index = 0 THEN
        IF VIO_Count < 50 THEN
            VIO_Count := VIO_Count + 1;
            VIO_Events[VIO_Count].Code := VI_Code;
            VIO_Events[VIO_Count].Severity := VI_Severity;
            VIO_Events[VIO_Count].Active := TRUE;
            VIO_Events[VIO_Count].Timestamp := VI_Timestamp;
            VIO_Events[VIO_Count].Source := VI_Source;
        END_IF;
    ELSE
        VIO_Events[L_Found_Index].Severity := VI_Severity;
        IF NOT L_Was_Active THEN
            VIO_Events[L_Found_Index].Timestamp := VI_Timestamp;
        END_IF;
        VIO_Events[L_Found_Index].Active := TRUE;
    END_IF;
ELSE
    IF L_Found_Index > 0 THEN
        VIO_Events[L_Found_Index].Active := FALSE;
    END_IF;
END_IF;

// Если ПЛК находится в режиме Standby (резерв), он не должен управлять выходами
IF NOT VI_IsActivePLC THEN
    RETURN;
END_IF;

IF VI_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP THEN
    VO_Gate_Open := FALSE;
    VO_Wicket_Open := FALSE;
    VO_Lock_1_Open := FALSE;
    VO_Lock_2_Open := FALSE;
    RETURN;
END_IF;

// 1. Логика автоматического закрытия замков при постановке на охрану (ТЗ 3.0)
// При переходе системы в режим "Охрана" принудительно блокируем все замки
IF VI_Armed AND NOT L_Prev_Armed THEN
    L_Auto_Lock_Req := TRUE;
END_IF;
L_Prev_Armed := VI_Armed;

// Детекторы фронта для команд
R_Trig_Gate(CLK := VI_Gate_Open_Req);
R_Trig_Wicket(CLK := VI_Wicket_Open_Req);
R_Trig_Lock_1_O(CLK := VI_Lock_1_Open_Req);
R_Trig_Lock_1_C(CLK := VI_Lock_1_Close_Req OR L_Auto_Lock_Req);
R_Trig_Lock_2_O(CLK := VI_Lock_2_Open_Req);
R_Trig_Lock_2_C(CLK := VI_Lock_2_Close_Req OR L_Auto_Lock_Req);

// Проверка PIN-кода или RFID-метки через менеджер кодов
fbAccessCode(
    VI_System_Time_MS := VI_System_Time_MS,
    VI_IsActivePLC := VI_IsActivePLC,
    VI_Code_To_Check := VI_PIN_Code,
    VI_RFID_To_Check := VI_RFID_Tag,
    VI_Access_Codes := VI_Access_Codes,
    VI_RFID_Tags := VI_RFID_Tags,
    VO_Code_Valid => L_Valid_PIN
);

// 2. Формирование импульсов управления исполнительными механизмами (Pulse Control)
// Открытие ворот и калитки требует валидного ПИН-кода или RFID-метки, если система под охраной
L_Gate_Timer(IN := R_Trig_Gate.Q AND (NOT VI_Armed OR L_Valid_PIN), PT := TO_TIME(VI_Config.gate_open_pulse_ms));
VO_Gate_Open := L_Gate_Timer.Q;

L_Wicket_Timer(IN := R_Trig_Wicket.Q AND (NOT VI_Armed OR L_Valid_PIN), PT := TO_TIME(VI_Config.wicket_open_pulse_ms));
VO_Wicket_Open := L_Wicket_Timer.Q;

L_Lock_1_Open_T(IN := R_Trig_Lock_1_O.Q AND (NOT VI_Armed OR L_Valid_PIN), PT := TO_TIME(VI_Config.lock_open_pulse_ms));
VO_Lock_1_Open := L_Lock_1_Open_T.Q;

L_Lock_1_Close_T(IN := R_Trig_Lock_1_C.Q, PT := TO_TIME(VI_Config.lock_close_pulse_ms));
VO_Lock_1_Close := L_Lock_1_Close_T.Q;

L_Lock_2_Open_T(IN := R_Trig_Lock_2_O.Q AND (NOT VI_Armed OR L_Valid_PIN), PT := TO_TIME(VI_Config.lock_open_pulse_ms));
VO_Lock_2_Open := L_Lock_2_Open_T.Q;

L_Lock_2_Close_T(IN := R_Trig_Lock_2_C.Q, PT := TO_TIME(VI_Config.lock_close_pulse_ms));
VO_Lock_2_Close := L_Lock_2_Close_T.Q;

// Сброс флага автоматического закрытия
IF L_Auto_Lock_Req THEN
    L_Auto_Lock_Req := FALSE;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_Access_Control <<<

IF NOT VI_Config.enabled THEN
    RETURN;
END_IF;

L_Deviation := ABS(VI_Current_Value - L_Last_Value);
L_Elapsed_Time := SEL(
    VI_System_Time_MS >= L_Last_Log_Time,
    VI_System_Time_MS - L_Last_Log_Time,
    (4294967295 - L_Last_Log_Time) + VI_System_Time_MS + 1
);

IF (L_Deviation >= (ABS(L_Last_Value) * VI_Config.deviation_threshold_percent / REAL#100.0)) OR
   (L_Elapsed_Time >= GVL_CONSTANTS.C_MS_IN_HOUR) THEN

    L_Write_Index := (VO_Data.record_count MOD 100) + 1;
    VO_Data.write_index := L_Write_Index;
    VO_Data.values[L_Write_Index] := VI_Current_Value;
    VO_Data.timestamps[L_Write_Index] := VI_System_Time_MS;
    VO_Data.record_count := VO_Data.record_count + 1;
    VO_Data.sum_values := VO_Data.sum_values + VI_Current_Value;
    VO_Data.config := VI_Config;

    L_Last_Value := VI_Current_Value;
    L_Last_Log_Time := VI_System_Time_MS;
END_IF;

IF (VI_Gas_Alarm <> L_Last_Gas) OR (VI_Leak_Alarm <> L_Last_Leak) THEN
    VO_Last_Change_Time := VI_System_Time;
END_IF;

L_Last_Gas := VI_Gas_Alarm;
L_Last_Leak := VI_Leak_Alarm;

// ==============================================================================
// Блок таймера, привязанный к системному времени (System Timer)
// Назначение:
// - Замена стандартного TON для обеспечения точной выдержки времени,
//   независимой от времени цикла ПЛК, с использованием единого системного времени.
// ==============================================================================



IF IN THEN
    IF NOT L_Running THEN
        L_Start_Time := VI_System_Time_MS;
        L_Running := TRUE;
        ET := T#0s;
        Q := FALSE;
    ELSE
        // Обработка переполнения UDINT (примерно 49 дней)
        ET := TO_TIME((SEL(VI_System_Time_MS >= L_Start_Time, VI_System_Time_MS - L_Start_Time, (4294967295 - L_Start_Time) + VI_System_Time_MS + 1)));

        IF ET >= PT THEN
            Q := TRUE;
            ET := PT;
        ELSE
            Q := FALSE;
        END_IF;
    END_IF;
ELSE
    L_Running := FALSE;
    ET := T#0s;
    Q := FALSE;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_System_Timer <<<

// Детекция фронта команды
L_cmd_rising := (VI_Command <> 0) AND (L_prev_Command = 0);
L_prev_Command := VI_Command;

IF L_cmd_rising THEN
    VO_Done := FALSE;
    VO_Error := FALSE;
    VO_ErrorID := 0;
    VO_HMI_Status_Message := '';

    // Валидация смещения
    IF VI_Offset >= C_MAX_NVRAM_SIZE THEN
        VO_Error := TRUE;
        VO_ErrorID := 16#1501;
        VO_HMI_Status_Message := 'NVRAM: Неверное смещение';
        VO_Done := TRUE;
        RETURN;
    END_IF;

    // Валидация указателя
    IF NOT __ISVALIDREF(VI_DataRef) THEN
        VO_Error := TRUE;
        VO_ErrorID := 16#150A;
        VO_HMI_Status_Message := 'NVRAM: Недействительная ссылка на данные';
        VO_Done := TRUE;
        RETURN;
    END_IF;

    L_pData := ADR(VI_DataRef);

    IF (VI_Offset + VI_DataSize) > C_MAX_NVRAM_SIZE THEN
        VO_Error := TRUE;
        VO_ErrorID := 16#150B;
        VO_HMI_Status_Message := 'NVRAM: Размер данных превышает доступный объем';
        VO_Done := TRUE;
        RETURN;
    END_IF;

    IF VI_Command = 2 THEN
    VO_Error := TRUE;
    VO_ErrorID := 16#150D;
    VO_HMI_Status_Message := 'NVRAM: READ not implemented';
    VO_Done := TRUE;
    RETURN;
END_IF;

IF VI_Command = 1 THEN // ЗАПИСЬ (WRITE)
        IF NOT VI_IsActivePLC THEN
            VO_Error := TRUE;
            VO_ErrorID := 16#1509;
            VO_HMI_Status_Message := 'NVRAM: Запись запрещена (STANDBY)';
        ELSE
            // Проверка на изменение данных перед записью
            L_Data_Changed := FALSE;
            FOR L_i := 0 TO VI_DataSize - 1 DO
                IF GVL_Retain.G_NVRAM_Data[VI_Offset + L_i] <> L_pData[L_i] THEN
                    L_Data_Changed := TRUE;
                    EXIT;
                END_IF;
            END_FOR;

            IF L_Data_Changed THEN
                // Безопасное копирование (WRITE)
                FOR L_i := 0 TO VI_DataSize - 1 DO
                    GVL_Retain.G_NVRAM_Data[VI_Offset + L_i] := L_pData[L_i];
                END_FOR;
                VO_HMI_Status_Message := 'NVRAM: Данные успешно сохранены в RETAIN';
            ELSE
                VO_HMI_Status_Message := 'NVRAM: Данные не изменились, запись пропущена';
            END_IF;
        END_IF;
        VO_Done := TRUE;
    END_IF;
END_IF;

IF VI_Command = 0 THEN
    VO_Done := FALSE;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_NVRAM_Manager <<<

IF VI_Write_Event AND NOT L_Prev_Write_Event THEN
    GVL_Retain.G_History_Buffer[GVL_Retain.G_History_Write_Idx] := VI_Event;
    GVL_Retain.G_History_Buffer[GVL_Retain.G_History_Write_Idx].timestamp_ms := VI_System_Time_MS;

    GVL_Retain.G_History_Write_Idx := (GVL_Retain.G_History_Write_Idx MOD GVL_CONSTANTS.C_MAX_HISTORY_RECORDS) + 1;
    GVL_Retain.G_History_Total_Events := GVL_Retain.G_History_Total_Events + 1;
END_IF;
L_Prev_Write_Event := VI_Write_Event;

VO_Total_Events := GVL_Retain.G_History_Total_Events;
// >>> BULK_SYNC_ANCHOR: FB_History_Manager <<<

L_Total_Demand := 0.0;

// calculate total demand
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
    L_Total_Demand := L_Total_Demand + ABS(GVL_HEATING_POLICY.G_Zone_Thermal_Demand[L_i]);
END_FOR;

GVL_HEATING_POLICY.G_Optimization_Load_Index := L_Total_Demand;

// normalize and optimize
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO

    IF L_Total_Demand > 0.01 THEN
        L_Load := ABS(GVL_HEATING_POLICY.G_Zone_Thermal_Demand[L_i]) / L_Total_Demand;
    ELSE
        L_Load := 0.0;
    END_IF;

    // priority score
    GVL_HEATING_POLICY.G_Zone_Optimization_Score[L_i] :=
        L_Load +
        (1.0 - GVL_HEATING_POLICY.G_Zone_Thermal_Model_Confidence[L_i]) * 0.2;

    // load balancing: reduce low priority zones
    IF GVL_HEATING_POLICY.G_Zone_Optimization_Score[L_i] < 0.2 THEN
        GVL_HEATING_POLICY.G_Zone_Thermal_Demand[L_i] :=
            GVL_HEATING_POLICY.G_Zone_Thermal_Demand[L_i] * 0.5;
    END_IF;

    // peak shaving
    IF L_Total_Demand > 5.0 THEN
        GVL_HEATING_POLICY.G_Zone_Thermal_Demand[L_i] :=
            GVL_HEATING_POLICY.G_Zone_Thermal_Demand[L_i] * 0.7;
        GVL_HEATING_POLICY.G_Optimization_Energy_Saving_Active := TRUE;
    END_IF;

END_FOR;

// ==============================================================================
// Heating manifold control helper
// Internal refactoring helper for FB_Heating_System_Manager.
// Valve test override remains in FB_Heating_System_Manager for now.
// ==============================================================================



FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    L_PID_Timer[L_i](IN := TRUE, PT := T#1s, VI_System_Time_MS := VI_System_Time_MS);
    IF L_PID_Timer[L_i].Q THEN
        L_PID_Timer[L_i](IN := FALSE, PT := T#1s, VI_System_Time_MS := VI_System_Time_MS);
        L_PID_Timer[L_i](IN := TRUE, PT := T#1s, VI_System_Time_MS := VI_System_Time_MS);

        L_PID_Valves[L_i](
            VI_SetPoint := VI_Target_Supply_Temp,
            VI_ProcessValue := VI_Manifold_Temps_Supply[L_i],
            VI_Kp := 2.0,
            VI_Tn := 120.0,
            VI_Tv := 0.0,
            VI_Y_Min := 0.0,
            VI_Y_Max := 100.0,
            VI_Cycle_Time_S := 1.0,
            VO_Output => VO_Manifold_Valves[L_i]
        );
    END_IF;

    L_Pump_Run_Timer[L_i](
        IN := VO_Manifold_Pumps[L_i] AND NOT L_Pump_In_Pause[L_i],
        PT := T#72h,
        VI_System_Time_MS := VI_System_Time_MS
    );
    IF L_Pump_Run_Timer[L_i].Q THEN
        L_Pump_In_Pause[L_i] := TRUE;
    END_IF;

    L_Pump_Pause_Timer[L_i](
        IN := L_Pump_In_Pause[L_i],
        PT := T#1h,
        VI_System_Time_MS := VI_System_Time_MS
    );
    IF L_Pump_Pause_Timer[L_i].Q THEN
        L_Pump_In_Pause[L_i] := FALSE;
    END_IF;

    IF VI_DHW_Heating_Demand THEN
        VO_Manifold_Pumps[L_i] := FALSE;
        VO_Manifold_Valves[L_i] := 0.0;
    ELSE
        VO_Manifold_Pumps[L_i] := VI_IsActivePLC AND VI_Any_Zone_Active[L_i] AND NOT L_Pump_In_Pause[L_i];
    END_IF;

    IF VI_Freeze_Mode_Active THEN
        VO_Manifold_Pumps[L_i] := TRUE;
        IF VO_Manifold_Valves[L_i] < 35.0 THEN
            VO_Manifold_Valves[L_i] := 35.0;
        END_IF;
    END_IF;

    VO_Status[L_i].Pump_On := VO_Manifold_Pumps[L_i];
    VO_Status[L_i].Pump_Current := VI_Manifold_Currents[L_i];
    VO_Status[L_i].Pressure := VI_Manifold_Pressures[L_i];
    VO_Status[L_i].Temp_Supply := VI_Manifold_Temps_Supply[L_i];
    VO_Status[L_i].Temp_Return := VI_Manifold_Temps_Return[L_i];
    VO_Status[L_i].Valve_Pos := VO_Manifold_Valves[L_i];

    L_Pump_Diag[L_i](
        VI_Current_Value := VI_Manifold_Currents[L_i],
        VI_Nominal_Value := 0.55,
        VI_Is_Running := VO_Manifold_Pumps[L_i],
        VI_Reset_Stats := FALSE,
        VI_System_Time_MS := VI_System_Time_MS,
        VIO_Health_Data := VO_Status[L_i].Health
    );

    IF VO_Manifold_Pumps[L_i] THEN
        L_Delta_T := VI_Manifold_Temps_Supply[L_i] - VI_Manifold_Temps_Return[L_i];

        VO_Status[L_i].Error := FALSE;
        VO_Status[L_i].Error_ID := 0;

        IF VI_Manifold_Currents[L_i] <= 0.01 THEN
            VO_Status[L_i].Error := TRUE;
            VO_Status[L_i].Error_ID := TO_WORD(GVL_CONFIG.ERR_PUMP_NO_CURRENT);
        ELSIF VI_Manifold_Currents[L_i] < 0.3 THEN
            VO_Status[L_i].Error := TRUE;
            VO_Status[L_i].Error_ID := TO_WORD(GVL_CONFIG.ERR_PUMP_UNDERCURRENT);
        ELSIF VI_Manifold_Currents[L_i] > 1.5 THEN
            VO_Status[L_i].Error := TRUE;
            VO_Status[L_i].Error_ID := TO_WORD(GVL_CONFIG.ERR_PUMP_OVERCURRENT);
        END_IF;

        IF (NOT VO_Status[L_i].Error) AND ((VI_Manifold_Pressures[L_i] < 1.5) OR (VI_Manifold_Pressures[L_i] > 2.5)) THEN
            VO_Status[L_i].Error := TRUE;
            VO_Status[L_i].Error_ID := TO_WORD(GVL_CONFIG.ERR_PRESSURE_OUT_OF_RANGE);
        END_IF;

        IF NOT VO_Status[L_i].Error THEN
            IF L_Delta_T < 5.0 THEN
                VO_Status[L_i].Error := TRUE;
                VO_Status[L_i].Error_ID := TO_WORD(GVL_CONFIG.ERR_DELTA_T_LOW);
            ELSIF L_Delta_T > 10.0 THEN
                VO_Status[L_i].Error := TRUE;
                VO_Status[L_i].Error_ID := TO_WORD(GVL_CONFIG.ERR_DELTA_T_HIGH);
            END_IF;
        END_IF;
    END_IF;
END_FOR;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Manifold_Control <<<

// Менеджер управления розетками.
// Обеспечивает работу по сценариям, правилам и аварийное отключение (без локальных выключателей розеток).


IF NOT VI_IsActivePLC THEN RETURN; END_IF;


// Проверка связи с модулями ввода-вывода
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MODULES DO
    IF NOT VI_IO_Modules_Online[L_i] THEN
        // Переход в безопасное состояние при потере связи (отключение всех розеток)
        FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_SOCKETS DO
            VO_Socket_States[L_j] := FALSE;
        END_FOR;
        RETURN;
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SOCKETS DO
    L_Rule_Active := FALSE;
    L_Rule_State := FALSE;

    L_Manual_Trig[L_i](CLK := VI_Manual_Override[L_i]);

    // Ручное переключение
    IF L_Manual_Trig[L_i].Q THEN
        L_Internal_State[L_i] := NOT L_Internal_State[L_i];
    END_IF;

    // Проверка правил для текущей розетки
    FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_RULES DO
        IF VI_Rule_Actions[L_j].Active AND VI_Rule_Actions[L_j].Target_ID = L_i THEN
            IF VI_Rule_Actions[L_j].Action_Type = E_Rule_Action_Type.ACTION_SET_SOCKET THEN
                L_Rule_Active := TRUE;
                L_Rule_State := (VI_Rule_Actions[L_j].Value > 0.5);
                L_Internal_State[L_i] := L_Rule_State; // Синхронизация внутреннего состояния
            ELSIF VI_Rule_Actions[L_j].Action_Type = E_Rule_Action_Type.ACTION_TOGGLE_SOCKET AND VI_Rule_Actions[L_j].Triggered THEN
                L_Internal_State[L_i] := NOT L_Internal_State[L_i]; // Toggle
            END_IF;
        END_IF;
    END_FOR;

    // Аварийное отключение
    IF VI_Fire_Alarm OR VI_Flood_Alarm THEN
        // Розетки 1-4 неотключаемые (холодильник, сервер и т.д.)
        IF L_i > 4 THEN
            VO_Socket_States[L_i] := FALSE;
        ELSE
            // Критические розетки сохраняют свое текущее внутреннее состояние, а не форсируются в TRUE
            VO_Socket_States[L_i] := L_Internal_State[L_i];
        END_IF;
    ELSIF VI_Scenario = E_SCENARIO_TYPE.SCENARIO_AWAY OR VI_Security_Armed THEN
        // Master Off
        IF L_i > 4 THEN
            VO_Socket_States[L_i] := FALSE;
        ELSE
            // Неотключаемые розетки могут управляться вручную
            VO_Socket_States[L_i] := L_Internal_State[L_i];
        END_IF;
    ELSE
        // Нормальный режим: состояние определяется внутренним состоянием (ручным или правилом)
        IF L_Rule_Active THEN
            VO_Socket_States[L_i] := L_Rule_State;
        ELSE
            VO_Socket_States[L_i] := L_Internal_State[L_i];
        END_IF;
    END_IF;
END_FOR;

VO_Internal_States := L_Internal_State;

// >>> BULK_SYNC_ANCHOR: FB_Socket_Manager <<<

IF NOT VI_IsActivePLC THEN RETURN; END_IF;

// Reset outputs
VO_Smoke_Detected := FALSE;
VO_Gas_Detected := FALSE;
VO_CO_Warning_Level := FALSE;
VO_CO_Alarm_Level := FALSE;
VO_Status_Msg := 'ОК';

// --- Methane ---
L_Methane_Max := 0.0;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_METHANE_SENSORS DO
    IF VI_Methane_LEL[L_i] > L_Methane_Max THEN
        L_Methane_Max := VI_Methane_LEL[L_i];
    END_IF;
END_FOR;

IF L_Methane_Max >= 20.0 THEN
    VO_Gas_Detected := TRUE;
END_IF;

// --- CO ---
L_CO_Max := 0.0;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_CO_SENSORS DO
    IF VI_CO_PPM[L_i] > L_CO_Max THEN
        L_CO_Max := VI_CO_PPM[L_i];
    END_IF;
END_FOR;

L_CO_Level_30 := (L_CO_Max >= 30.0);
L_CO_Level_70 := (L_CO_Max >= 70.0);
L_CO_Level_400 := (L_CO_Max >= 400.0);

L_CO_Timer_30ppm(IN := L_CO_Level_30, PT := T#8h, VI_System_Time_MS := VI_System_Time_MS);
L_CO_Timer_70ppm(IN := L_CO_Level_70, PT := T#1h, VI_System_Time_MS := VI_System_Time_MS);
L_CO_Timer_400ppm(IN := L_CO_Level_400, PT := T#15m, VI_System_Time_MS := VI_System_Time_MS);

IF L_CO_Timer_30ppm.Q THEN
    VO_CO_Warning_Level := TRUE;
END_IF;

IF L_CO_Timer_70ppm.Q OR L_CO_Timer_400ppm.Q THEN
    VO_CO_Alarm_Level := TRUE;
END_IF;

// --- Smoke ---
L_Smoke_Count := 0;
L_Smoke_Active := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SMOKE_SENSORS DO
    L_Smoke_Timer[L_i](IN := VI_Smoke_Sensors[L_i], PT := T#30s, VI_System_Time_MS := VI_System_Time_MS);

    IF VI_Smoke_Sensors[L_i] THEN
        L_Smoke_Count := L_Smoke_Count + 1;
    END_IF;

    IF L_Smoke_Timer[L_i].Q OR (L_Smoke_Count >= 2) THEN
        L_Smoke_Active := TRUE;
    END_IF;
END_FOR;

IF L_Smoke_Active THEN
    VO_Smoke_Detected := TRUE;
END_IF;

// Status
IF VO_Smoke_Detected THEN
    VO_Status_Msg := 'ПОЖАР';
ELSIF VO_Gas_Detected THEN
    VO_Status_Msg := 'УТЕЧКА ГАЗА';
ELSIF VO_CO_Alarm_Level THEN
    VO_Status_Msg := 'КРИТИЧЕСКИЙ CO';
ELSIF VO_CO_Warning_Level THEN
    VO_Status_Msg := 'ПОВЫШЕННЫЙ CO';
ELSE
    VO_Status_Msg := 'ОК';
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_Gas_Smoke_Manager <<<

// 1. Error checking and scaling based on sensor type
VO_Error := FALSE;
VO_Diag_Code := 0;

CASE VI_Sensor_Type OF
    0: // 4-20mA (NAMUR NE43: < 3.6mA or > 21mA)
        IF VI_Raw_Value < GVL_CONSTANTS.C_ANALOG_3_6MA_RAW THEN // < 3.6mA (Open circuit)
            VO_Error := TRUE;
            VO_Diag_Code := 1;
        ELSIF VI_Raw_Value > GVL_CONSTANTS.C_ANALOG_21MA_RAW THEN // > 21mA (Short circuit)
            VO_Error := TRUE;
            VO_Diag_Code := 2;
        ELSE
            // 4mA = 5529, 20mA = 27648
            L_Scaled := VI_Min_Scale + (TO_REAL(VI_Raw_Value - GVL_CONSTANTS.C_ANALOG_4MA_RAW) / TO_REAL(GVL_CONSTANTS.C_ANALOG_RAW_MAX - GVL_CONSTANTS.C_ANALOG_4MA_RAW)) * (VI_Max_Scale - VI_Min_Scale);
        END_IF;

    1: // 0-10V (0-27648)
        IF VI_Raw_Value > GVL_CONSTANTS.C_ANALOG_10V_MAX_RAW THEN // Out of range
            VO_Error := TRUE;
            VO_Diag_Code := 3;
        ELSE
            L_Scaled := VI_Min_Scale + (TO_REAL(VI_Raw_Value) / TO_REAL(GVL_CONSTANTS.C_ANALOG_RAW_MAX)) * (VI_Max_Scale - VI_Min_Scale);
        END_IF;

    2: // PT100/1000 (Direct temperature * 10, e.g., 255 = 25.5C)
        // Typically, 16-bit signed integer for temperature
        IF VI_Raw_Value = 16#7FFF OR VI_Raw_Value = 16#8000 THEN // Sensor error codes
            VO_Error := TRUE;
            VO_Diag_Code := 1;
        ELSE
            L_Scaled := TO_REAL(TO_INT(VI_Raw_Value)) / 10.0;
            IF L_Scaled < VI_Min_Scale OR L_Scaled > VI_Max_Scale THEN
                VO_Error := TRUE;
                VO_Diag_Code := 3;
            END_IF;
        END_IF;

    ELSE
        VO_Error := TRUE;
        VO_Diag_Code := 16#FFFF; // Unknown sensor type
END_CASE;

// 2. Fallback handling
IF VO_Error THEN
    IF VI_Fallback_Mode = 1 THEN
        VO_Value := VI_Default_Value;
    END_IF;
    // If VI_Fallback_Mode = 0, VO_Value retains its last good value (L_Filtered)
    RETURN;
END_IF;

// 3. Calibration
L_Scaled := (L_Scaled * VI_Multiplier) + VI_Offset;

// 4. Moving Average Filter (ТЗ 1.2)
IF L_First_Scan THEN
    L_Filtered := L_Scaled;
    L_First_Scan := FALSE;
    L_Last_Time := VI_System_Time_MS;

    // Инициализация массива истории
    FOR L_i := 0 TO 9 DO
        L_History[L_i] := L_Scaled;
    END_FOR;
    L_History_Sum := L_Scaled * 10.0;
    L_History_Count := 10;
    L_History_Idx := 0;
END_IF;

L_DT := (SEL(VI_System_Time_MS >= L_Last_Time, VI_System_Time_MS - L_Last_Time, (4294967295 - L_Last_Time) + VI_System_Time_MS + 1));
IF VI_Filter_Time_MS = 0 THEN
    L_Filtered := L_Scaled;
    L_Last_Time := VI_System_Time_MS;
ELSIF L_DT >= (VI_Filter_Time_MS / 10) THEN // Обновляем 10 раз за время фильтрации
    // Вычитаем старое значение
    L_History_Sum := L_History_Sum - L_History[L_History_Idx];

    // Добавляем новое значение
    L_History[L_History_Idx] := L_Scaled;
    L_History_Sum := L_History_Sum + L_Scaled;

    // Сдвигаем индекс
    L_History_Idx := (L_History_Idx + 1) MOD 10;

    // Вычисляем среднее
    L_Filtered := L_History_Sum / 10.0;

    L_Last_Time := VI_System_Time_MS;
END_IF;

VO_Value := L_Filtered;

// Вспомогательная функция для безопасного вычисления разницы времени
L_Elapsed_Time := (VI_System_Time - L_Last_Pulse_Time);

// 1. Мониторинг "сердцебиения" и расчет сетевых задержек (ТЗ 8.4)
IF VI_Remote_Pulse <> L_Last_Pulse THEN
    // Вычисляем время между изменениями сигнала
    VO_RTT_MS := L_Elapsed_Time;
    // Фиксируем пиковые задержки для диагностики сети
    IF VO_RTT_MS > VO_Max_RTT THEN VO_Max_RTT := VO_RTT_MS; END_IF;
    L_Last_Pulse := VI_Remote_Pulse;
    L_Last_Pulse_Time := VI_System_Time;
    L_Elapsed_Time := 0; // Сбрасываем после обновления
END_IF;

// Подсчет статистики потерь связи (ТЗ 8.4)
IF L_Elapsed_Time > L_Timeout THEN
    IF (VI_System_Time - L_Last_Loss_Time) >= 1000 THEN
        VO_Loss_Count := VO_Loss_Count + 1;
        L_Last_Loss_Time := VI_System_Time;
    END_IF;
ELSE
    L_Last_Loss_Time := VI_System_Time;
END_IF;

// 2. Логика определения роли (Active/Standby) и предотвращение Split-Brain (ТЗ 8.3)
// Уровень 1: Проверка наличия связи с партнером
IF L_Elapsed_Time < L_Timeout THEN
    // Связь есть: Договариваемся о ролях на основе приоритета ID
    IF VI_Local_ID = 1 THEN
        VO_Is_Active := TRUE; // ПЛК А всегда активен при наличии связи
    ELSE
        VO_Is_Active := NOT VI_Remote_Is_Active; // ПЛК B активен только если А не активен
    END_IF;
ELSE
    // Связи нет: Пытаемся определить, кто из нас "живее"
    // Уровень 3: Если связи с партнером нет, проверяем доступность внешнего шлюза
    IF VI_Local_ID = 1 THEN
        // ПЛК А становится активным всегда при потере связи с партнером (fallback)
        VO_Is_Active := TRUE;
    ELSE
        // ПЛК B ждет таймаут удержания роли (2 секунды), прежде чем стать активным
        IF L_Elapsed_Time >= 2000 THEN
            // ПЛК B берет управление если он видит шлюз, а связи с А нет.
            // Если шлюз недоступен, B ждет дольше (fallback).
            IF VI_Gateway_Ping_OK THEN
                VO_Is_Active := TRUE;
            ELSIF L_Elapsed_Time >= 5000 THEN
                VO_Is_Active := TRUE; // Fallback: ПЛК А мертв и шлюз мертв
            ELSE
                VO_Is_Active := FALSE;
            END_IF;
        ELSE
            VO_Is_Active := FALSE;
        END_IF;
    END_IF;
END_IF;

L_Now_TOD := GVL_TIME_SERVICE.G_Time_Of_Day_MS;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO

    L_Time_To_Heat := GVL_HEATING_POLICY.G_Zone_Time_To_Heat_MS[L_i];
    L_Time_To_Comfort := GVL_HEATING_POLICY.G_Zone_Comfort_Time_MS[L_i];

    // predictive preheat decision
    IF GVL_HEATING_POLICY.G_Zone_Schedule_Enabled[L_i] THEN

        IF L_Time_To_Comfort > L_Now_TOD THEN
            IF (L_Time_To_Comfort - L_Now_TOD) <= L_Time_To_Heat THEN
                GVL_HEATING_POLICY.G_Zone_Preheat_Needed[L_i] := TRUE;
            ELSE
                GVL_HEATING_POLICY.G_Zone_Preheat_Needed[L_i] := FALSE;
            END_IF;
        END_IF;

    END_IF;

    // overshoot prevention
    IF GVL_HEATING_POLICY.G_Zone_Predicted_Temp_30m[L_i] > GVL_STATE.G_Target_Temperature THEN
        GVL_HEATING_POLICY.G_Zone_Thermal_Demand[L_i] := 
            GVL_HEATING_POLICY.G_Zone_Thermal_Demand[L_i] * 0.5;
    END_IF;

    // confidence gating
    IF GVL_HEATING_POLICY.G_Zone_Thermal_Model_Confidence[L_i] < 0.1 THEN
        GVL_HEATING_POLICY.G_Zone_Preheat_Needed[L_i] := FALSE;
    END_IF;

END_FOR;

// Converts STATE-level outputs into IO-ready projection (no commands applied here).

FOR L_i := 1 TO 8 DO
    GVL_HEATING_OUTPUT.DO_Zone_Valves[L_i] := VI_Zone_Valves[L_i];
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    GVL_HEATING_OUTPUT.DO_Manifold_Pumps[L_i] := VI_Manifold_Pumps[L_i];
    GVL_HEATING_OUTPUT.AO_Manifold_Valves[L_i] := REAL_TO_UINT(VI_Manifold_Valves[L_i] * 1000.0);
END_FOR;

GVL_HEATING_OUTPUT.DO_DHW_Heating_Pump := VI_DHW_Heating_Pump;
GVL_HEATING_OUTPUT.DO_DHW_Circ_Pump := VI_DHW_Circ_Pump;
GVL_HEATING_OUTPUT.DO_Backup_Circulation_Pump := VI_Backup_Circulation_Pump;
GVL_HEATING_OUTPUT.DO_Electric_Heater_Enable := VI_Electric_Heater_Enable;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Output_Projection <<<

IF (NOT VI_IsActivePLC) THEN
    VO_Sim_Active := FALSE;
    FOR L_i := 1 TO 32 DO
        VO_Sim_Lights[L_i] := FALSE;
    END_FOR;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO
        VO_Sim_Water_Leak[L_i] := FALSE;
    END_FOR;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_METHANE_SENSORS DO
        VO_Sim_Gas_Leak[L_i] := REAL#0.0;
    END_FOR;
    RETURN;
END_IF;

IF (VI_Scenario = E_SCENARIO_TYPE.SCENARIO_AWAY) AND VI_Config.Presence_Simulation_Enabled THEN
    VO_Sim_Active := TRUE;

    IF (VI_System_Time_MS - L_Last_Toggle) >= (GVL_CONSTANTS.C_MS_IN_MINUTE * 30) THEN
        L_Last_Toggle := VI_System_Time_MS;
        L_Slot := (VI_System_Time_MS / GVL_CONSTANTS.C_MS_IN_MINUTE) MOD 32;

        FOR L_i := 1 TO 32 DO
            VO_Sim_Lights[L_i] := ((TO_UDINT(L_i) + L_Slot) MOD 5) = 0;
        END_FOR;
    END_IF;
ELSE
    VO_Sim_Active := FALSE;
    FOR L_i := 1 TO 32 DO
        VO_Sim_Lights[L_i] := FALSE;
    END_FOR;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO
    VO_Sim_Water_Leak[L_i] := FALSE;
END_FOR;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_METHANE_SENSORS DO
    VO_Sim_Gas_Leak[L_i] := REAL#0.0;
END_FOR;

// >>> BULK_SYNC_ANCHOR: FB_Simulation_Manager <<<

// Extracted candidate from PRG_Heating S1.5
// Not connected yet.

// Base copy
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    VO_Manifold_Adjusted_Priority[L_i] := VI_Manifold_Base_Priority[L_i];
END_FOR;

// Adjustment loop
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO

    L_j := TO_INT(VI_Zone_Configs[L_i].manifold_id);
    L_Zone_ID := VI_Circuit_To_Zone[L_i];

    IF (L_j >= 1) AND (L_j <= GVL_CONSTANTS.C_MAX_MANIFOLDS) AND
       (L_Zone_ID >= 1) AND (L_Zone_ID <= GVL_CONSTANTS.C_MAX_ZONES) THEN

        VO_Manifold_Adjusted_Priority[L_j] := VO_Manifold_Adjusted_Priority[L_j]
            + TO_INT(VI_Zone_Priority_Bias[L_Zone_ID]);

        IF VI_Guest_Preheat_Enabled AND VI_Zone_Guest_Preheat_Request[L_Zone_ID] THEN
            VO_Manifold_Adjusted_Priority[L_j] := VO_Manifold_Adjusted_Priority[L_j]
                + VI_Guest_Preheat_Priority_Boost;
        END_IF;

        IF VI_Zone_Target_Adjustment[L_Zone_ID] > 0.1 THEN
            VO_Manifold_Adjusted_Priority[L_j] := VO_Manifold_Adjusted_Priority[L_j] + 1;
        ELSIF VI_Zone_Target_Adjustment[L_Zone_ID] < -0.1 THEN
            VO_Manifold_Adjusted_Priority[L_j] := VO_Manifold_Adjusted_Priority[L_j] - 1;
        END_IF;

        VO_Manifold_Adjusted_Priority[L_j] := VO_Manifold_Adjusted_Priority[L_j]
            + VI_Zone_Self_Level[L_Zone_ID];

        VO_Manifold_Adjusted_Priority[L_j] := TO_INT(
            TO_REAL(VO_Manifold_Adjusted_Priority[L_j])
            * VI_Policy_Priority_Multiplier
        );

        IF VO_Manifold_Adjusted_Priority[L_j] < 1 THEN
            VO_Manifold_Adjusted_Priority[L_j] := 1;
        END_IF;

    END_IF;

END_FOR;

// Decision context call
fbDecision(
    VI_Manifold_Pump_In_Service := VI_Manifold_Pump_In_Service,
    VI_Manifold_Pressure_Fault := VI_Manifold_Pressure_Fault,
    VI_Manifold_Current_Fault := VI_Manifold_Current_Fault,
    VI_Manifold_Thermal_Weight := VI_Manifold_Thermal_Weight,
    VI_Manifold_Priority := VO_Manifold_Adjusted_Priority,
    VI_Max_Thermal_Budget := VI_Max_Thermal_Budget
);

VO_Manifold_Allowed := fbDecision.VO_Manifold_Allowed;
VO_Manifold_Enabled := fbDecision.VO_Manifold_Enabled;
VO_Heating_Degraded := fbDecision.VO_Heating_Degraded;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Thermal_Allocation <<<

// ==============================================================================
// System health orchestrator helper
//
// Internal helper for PRG_System.
// Owns safety latch update, watchdog, system health aggregation,
// system mode calculation, HMI/fault publication, diagnostic exports,
// and human-readable mode/cause text projection.
// ==============================================================================



fbSafety(
    VI_Gas_Alarm := GVL_STATE.G_Safety_Gas_Alarm,
    VI_Leak_Alarm := GVL_STATE.G_Safety_Leak_Alarm,
    VI_Smoke_Alarm := GVL_STATE.G_Safety_Smoke_Alarm,
    VI_Reset := GVL_COMMAND.G_Reset_Errors,
    VO_Gas_Latched => GVL_STATE.G_Safety_Gas_Latched,
    VO_Leak_Latched => GVL_STATE.G_Safety_Leak_Latched,
    VO_Smoke_Latched => GVL_STATE.G_Safety_Smoke_Latched,
    VO_Emergency_Stop => GVL_STATE.G_Safety_Emergency_Stop
);

GVL_STATE.G_Freeze_Hardware_Degraded := GVL_STATUS.G_Diagnostics.Backup_Pump_Fault OR GVL_STATUS.G_Diagnostics.Electric_Heater_Fault;
GVL_STATE.G_Freeze_Hardware_Failed := GVL_STATUS.G_Diagnostics.Backup_Pump_Fault AND GVL_STATUS.G_Diagnostics.Electric_Heater_Fault;

fbWatchdog(
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

fbSystemHealth(
    VI_Smoke_Detected := GVL_HEALTH_BRIDGE.G_Smoke_Detected OR GVL_STATE.G_Safety_Smoke_Latched,
    VI_Gas_Detected := GVL_HEALTH_BRIDGE.G_Gas_Detected OR GVL_STATE.G_Safety_Gas_Latched,
    VI_CO_Warning_Level := GVL_HEALTH_BRIDGE.G_CO_Warning_Level,
    VI_CO_Alarm_Level := GVL_HEALTH_BRIDGE.G_CO_Alarm_Level,
    VI_Leak_Detected := GVL_HEALTH_BRIDGE.G_Leak_Detected OR GVL_STATE.G_Safety_Leak_Latched,
    VI_Sensor_Fault := GVL_STATE.G_Heating_Sensor_Fault OR GVL_STATE.G_DHW_Sensor_Fault OR GVL_STATUS.G_Diagnostics.Manifold_Pressure_Fault_Active OR GVL_STATUS.G_Diagnostics.Manifold_Current_Fault_Active OR GVL_STATUS.G_Diagnostics.Manifold_Return_Temp_Fault_Active,
    VI_IO_Offline := GVL_STATE.G_Heating_IO_Fault OR GVL_STATE.G_DHW_IO_Fault OR GVL_STATE.G_Ventilation_IO_Fault OR GVL_STATE.G_Lighting_IO_Fault,
    VI_Comm_Fault := GVL_STATE.G_Access_Comm_Fault,
    VI_Watchdog_Fault := fbWatchdog.VO_Watchdog_Fault,
    VI_Subsystem_Fault := GVL_STATE.G_Heating_Subsystem_Degraded OR GVL_STATE.G_DHW_Subsystem_Degraded OR GVL_STATE.G_Ventilation_Subsystem_Degraded OR GVL_STATUS.G_Diagnostics.Manifold_Pressure_Fault_Active OR GVL_STATUS.G_Diagnostics.Manifold_Current_Fault_Active OR GVL_STATUS.G_Diagnostics.Manifold_Return_Temp_Fault_Active
);

fbStateManager(
    VI_System_Severity := fbSystemHealth.VO_System_Severity,
    VI_Root_Cause := fbSystemHealth.VO_Root_Cause,
    VI_Freeze_Risk := GVL_STATE.G_Safety_Freeze_Risk
);

fbHMIInterface(
    VI_Severity := fbSystemHealth.VO_System_Severity,
    VI_RootCause := fbSystemHealth.VO_Root_Cause,
    VI_Status_Msg := fbStateManager.VO_Status_Msg
);

fbFaultLogger(
    VI_Severity := fbSystemHealth.VO_System_Severity,
    VI_RootCause := fbSystemHealth.VO_Root_Cause,
    VI_Time_MS := GVL_STATUS.G_System_Time_MS
);

GVL_STATUS.G_System_Mode_Msg := fbStateManager.VO_Status_Msg;

GVL_STATUS.G_Diagnostics.Sensor_Fault :=
    GVL_STATE.G_Heating_Sensor_Fault OR
    GVL_STATE.G_DHW_Sensor_Fault OR
    GVL_STATUS.G_Diagnostics.Manifold_Pressure_Fault_Active OR
    GVL_STATUS.G_Diagnostics.Manifold_Current_Fault_Active OR
    GVL_STATUS.G_Diagnostics.Manifold_Return_Temp_Fault_Active;

GVL_STATUS.G_Diagnostics.IO_Offline :=
    GVL_STATE.G_Heating_IO_Fault OR
    GVL_STATE.G_DHW_IO_Fault OR
    GVL_STATE.G_Ventilation_IO_Fault OR
    GVL_STATE.G_Lighting_IO_Fault;

GVL_STATUS.G_Diagnostics.Subsystem_Degraded :=
    GVL_STATE.G_Heating_Subsystem_Degraded OR
    GVL_STATE.G_DHW_Subsystem_Degraded OR
    GVL_STATE.G_Ventilation_Subsystem_Degraded OR
    GVL_STATUS.G_Diagnostics.Manifold_Pressure_Fault_Active OR
    GVL_STATUS.G_Diagnostics.Manifold_Current_Fault_Active OR
    GVL_STATUS.G_Diagnostics.Manifold_Return_Temp_Fault_Active;

GVL_GATEWAY.G_Gateway_HMI_Status_Message := fbHMIInterface.VO_HMI_Status_Text;
IF fbFaultLogger.VO_Last_Event_Text <> '' THEN
    GVL_HEALTH_BRIDGE.G_Last_Fault_Event_Text := fbFaultLogger.VO_Last_Event_Text;
END_IF;

GVL_STATE.G_System_Mode := fbStateManager.VO_System_Mode;

CASE GVL_STATE.G_System_Mode OF
    E_System_Operating_Mode.MODE_SAFE_STOP:
        GVL_STATE.G_System_Mode_Text := 'SAFE_STOP';

    E_System_Operating_Mode.MODE_FREEZE_PROTECTION:
        GVL_STATE.G_System_Mode_Text := 'FREEZE_PROTECTION';

    E_System_Operating_Mode.MODE_DEGRADED:
        GVL_STATE.G_System_Mode_Text := 'DEGRADED';

    ELSE
        GVL_STATE.G_System_Mode_Text := 'NORMAL';
END_CASE;

CASE fbSystemHealth.VO_Root_Cause OF
    E_System_Root_Cause.ROOT_FIRE:
        GVL_STATUS.G_System_Mode_Cause := 'Пожар/дым';
    E_System_Root_Cause.ROOT_GAS_LEAK:
        GVL_STATUS.G_System_Mode_Cause := 'Утечка газа';
    E_System_Root_Cause.ROOT_CO_CRITICAL:
        GVL_STATUS.G_System_Mode_Cause := 'Критический CO';
    E_System_Root_Cause.ROOT_CO_WARNING:
        GVL_STATUS.G_System_Mode_Cause := 'Повышенный CO';
    E_System_Root_Cause.ROOT_WATER_LEAK:
        GVL_STATUS.G_System_Mode_Cause := 'Протечка воды';
    E_System_Root_Cause.ROOT_WATCHDOG_FAULT:
        GVL_STATUS.G_System_Mode_Cause := 'Ошибка watchdog';
    E_System_Root_Cause.ROOT_IO_OFFLINE:
        GVL_STATUS.G_System_Mode_Cause := 'Недоступен модуль IO';
    E_System_Root_Cause.ROOT_COMM_FAULT:
        GVL_STATUS.G_System_Mode_Cause := 'Ошибка связи';
    E_System_Root_Cause.ROOT_SENSOR_FAULT:
        GVL_STATUS.G_System_Mode_Cause := 'Ошибка датчика';
    E_System_Root_Cause.ROOT_SUBSYSTEM_FAULT:
        GVL_STATUS.G_System_Mode_Cause := 'Ошибка подсистемы';
    ELSE
        GVL_STATUS.G_System_Mode_Cause := 'Аварийные режимы отсутствуют';
END_CASE;

VO_First_Fault_Active := fbSystemHealth.VO_First_Fault_Active;
VO_First_Fault_Type := fbSystemHealth.VO_First_Fault_Type;
VO_First_Fault_Source := fbSystemHealth.VO_First_Fault_Source;
VO_System_Severity := fbSystemHealth.VO_System_Severity;
VO_Root_Cause := fbSystemHealth.VO_Root_Cause;
VO_Watchdog_Fault := fbWatchdog.VO_Watchdog_Fault;

GVL_STATUS.G_System_Mode_Msg := fbStateManager.VO_Status_Msg;

// >>> BULK_SYNC_ANCHOR: FB_System_Health_Orchestrator <<<

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    VO_OT_Enable[L_i] := FALSE;
    VO_OT_Setpoint[L_i] := 0.0;
    VO_OT_Command_Valid[L_i] := FALSE;

    IF VI_Enable[L_i] AND VI_OT_Online[L_i] AND NOT VI_OT_Error[L_i] THEN
        VO_OT_Enable[L_i] := TRUE;
        VO_OT_Setpoint[L_i] := LIMIT(20.0, VI_Setpoint[L_i], 80.0);
        VO_OT_Command_Valid[L_i] := TRUE;
    END_IF;
END_FOR;

// Расчет ошибки
VO_Error := VI_SetPoint - VI_ProcessValue;

// Проверка мертвой зоны
IF ABS(VO_Error) < VI_Deadband THEN
    VO_Error := 0.0;
END_IF;

IF VI_Reset THEN
    L_Integral_Sum := 0.0;
    L_Prev_Error := 0.0;
    VO_Output := 0.0;
    RETURN;
END_IF;

IF VI_Manual_Mode THEN
    VO_Output := VI_Manual_Value;
    // Безударный переход: при выходе из ручного режима выход должен остаться прежним.
    // Так как Выход = P + I + D, то I = Выход - P - D.
    // Для простоты D при переходе обнуляем (или игнорируем), тогда I = Выход - P.
    L_Integral_Sum := VO_Output - (VI_Kp * VO_Error);
    L_Prev_Error := VO_Error;
    RETURN;
END_IF;

// Пропорциональная составляющая
L_Output_Raw := VI_Kp * VO_Error;

// Интегральная составляющая (Метод трапеций)
IF VI_Tn > 0.0 THEN
    // Anti-windup: не накапливаем интеграл, если выход уже на пределе и ошибка того же знака
    IF NOT VO_Limiting OR (VO_Error > 0.0 AND L_Output_Raw < VI_Y_Max) OR (VO_Error < 0.0 AND L_Output_Raw > VI_Y_Min) THEN
        L_Integral_Sum := L_Integral_Sum + (VI_Kp / VI_Tn) * VO_Error * VI_Cycle_Time_S;
    END_IF;
    L_Output_Raw := L_Output_Raw + L_Integral_Sum;
END_IF;

// Дифференциальная составляющая
IF VI_Tv > 0.0 THEN
    L_Derivative := (VO_Error - L_Prev_Error) / VI_Cycle_Time_S;
    L_Output_Raw := L_Output_Raw + VI_Kp * VI_Tv * L_Derivative;
END_IF;

L_Prev_Error := VO_Error;

// Ограничение выхода
IF L_Output_Raw > VI_Y_Max THEN
    VO_Output := VI_Y_Max;
    VO_Limiting := TRUE;
ELSIF L_Output_Raw < VI_Y_Min THEN
    VO_Output := VI_Y_Min;
    VO_Limiting := TRUE;
ELSE
    VO_Output := L_Output_Raw;
    VO_Limiting := FALSE;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_PID_Controller <<<

// Сброс выходов по умолчанию
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    VO_Boiler_Enable[L_i] := FALSE;
    VO_Boiler_Setpoint[L_i] := 0.0;
END_FOR;

// Инициализация ротации
IF NOT L_Rotation_Initialized THEN
    L_Last_Rotation_MS := VI_System_Time_MS;
    L_Rotation_Initialized := TRUE;
END_IF;

// Принудительная остановка
IF VI_Boiler_Stop THEN
    VO_Lead_Boiler := L_Lead_Boiler;
    RETURN;
END_IF;

// Ротация строго каждые 168 часов
IF (VI_System_Time_MS - L_Last_Rotation_MS) >= L_Rotation_Period_MS THEN
    IF GVL_CONSTANTS.C_MAX_BOILERS > 1 THEN
        L_Lead_Boiler := 3 - L_Lead_Boiler;
    END_IF;
    L_Last_Rotation_MS := VI_System_Time_MS;
END_IF;

L_Reserve_Boiler := SEL(L_Lead_Boiler = 1, 1, 2);

L_Lead_Available :=
    VI_Boiler_OT_Online[L_Lead_Boiler] AND
    NOT VI_Boiler_Error_Status[L_Lead_Boiler];

L_Reserve_Available :=
    (GVL_CONSTANTS.C_MAX_BOILERS > 1) AND
    VI_Boiler_OT_Online[L_Reserve_Boiler] AND
    NOT VI_Boiler_Error_Status[L_Reserve_Boiler];

// Контроль "команда есть, пламени нет" для ведущего котла
L_Flame_Miss_Timer[L_Lead_Boiler](
    IN := VI_Enable AND L_Lead_Available AND NOT VI_DHW_Heating_Demand AND NOT VI_Boiler_Flame_Status[L_Lead_Boiler],
    PT := T#120s
);

IF L_Flame_Miss_Timer[L_Lead_Boiler].Q AND L_Reserve_Available THEN
    L_Lead_Boiler := L_Reserve_Boiler;
    L_Last_Rotation_MS := VI_System_Time_MS;
    L_Lead_Available :=
        VI_Boiler_OT_Online[L_Lead_Boiler] AND
        NOT VI_Boiler_Error_Status[L_Lead_Boiler];
    L_Reserve_Boiler := SEL(L_Lead_Boiler = 1, 1, 2);
    L_Reserve_Available :=
        (GVL_CONSTANTS.C_MAX_BOILERS > 1) AND
        VI_Boiler_OT_Online[L_Reserve_Boiler] AND
        NOT VI_Boiler_Error_Status[L_Reserve_Boiler];
END_IF;

// Нет запроса тепла
IF NOT VI_Enable THEN
    VO_Lead_Boiler := L_Lead_Boiler;
    RETURN;
END_IF;

// Целевая уставка
IF VI_DHW_Heating_Demand THEN
    L_Target_Setpoint := LIMIT(20.0, VI_DHW_Target_Temp + 15.0, 85.0);
ELSE
    L_Target_Setpoint := LIMIT(20.0, VI_Target_Supply_Temp + 5.0, 80.0);
END_IF;

// Выбор ведущего по доступности
IF NOT L_Lead_Available AND L_Reserve_Available THEN
    L_Lead_Boiler := L_Reserve_Boiler;
    L_Lead_Available := TRUE;
    L_Reserve_Boiler := SEL(L_Lead_Boiler = 1, 1, 2);
    L_Reserve_Available :=
        (GVL_CONSTANTS.C_MAX_BOILERS > 1) AND
        VI_Boiler_OT_Online[L_Reserve_Boiler] AND
        NOT VI_Boiler_Error_Status[L_Reserve_Boiler];
END_IF;

// Основной котёл
IF L_Lead_Available THEN
    VO_Boiler_Enable[L_Lead_Boiler] := TRUE;
    VO_Boiler_Setpoint[L_Lead_Boiler] := L_Target_Setpoint;
END_IF;

// Резервный котёл: >80% или отказ основного
L_Start_Reserve :=
    L_Reserve_Available AND
    (
        (VI_Demand_Power > 80.0) OR
        (NOT L_Lead_Available)
    );

IF L_Start_Reserve THEN
    VO_Boiler_Enable[L_Reserve_Boiler] := TRUE;
    VO_Boiler_Setpoint[L_Reserve_Boiler] := L_Target_Setpoint;
END_IF;

VO_Lead_Boiler := L_Lead_Boiler;

VO_Ownership_Violation := FALSE;

// Gas: signal present, alarm disappeared
IF (VI_Gas_Level > 20.0) AND L_Last_Gas_Alarm AND (NOT VI_Gas_Alarm) THEN
    VO_Ownership_Violation := TRUE;
END_IF;

// Leak: once latched should not drop instantly
IF L_Last_Leak_Alarm AND (NOT VI_Leak_Alarm) THEN
    VO_Ownership_Violation := TRUE;
END_IF;

// Smoke: same rule
IF L_Last_Smoke_Alarm AND (NOT VI_Smoke_Alarm) THEN
    VO_Ownership_Violation := TRUE;
END_IF;

L_Last_Gas_Alarm := VI_Gas_Alarm;
L_Last_Leak_Alarm := VI_Leak_Alarm;
L_Last_Smoke_Alarm := VI_Smoke_Alarm;

// ==============================================================================
// System scenario arbitration helper
//
// Internal helper for PRG_System.
// Owns scenario request validation, priority resolution, fail-safe clamp,
// degraded-mode adaptation, policy logging, and FB_Scenario_Manager call.
// ==============================================================================



// === SCENARIO REQUEST VALIDATION ===
// Normalize invalid values to NONE to avoid corrupt inputs.
// Actual enum range in E_SCENARIO_TYPE is 0..7.
IF TO_USINT(VIO_Scenario_Req_Operator) > 7 THEN
    VIO_Scenario_Req_Operator := E_SCENARIO_TYPE.SCENARIO_NONE;
END_IF;

IF TO_USINT(VIO_Scenario_Req_Gateway) > 7 THEN
    VIO_Scenario_Req_Gateway := E_SCENARIO_TYPE.SCENARIO_NONE;
END_IF;

IF TO_USINT(VIO_Scenario_Req_Rule) > 7 THEN
    VIO_Scenario_Req_Rule := E_SCENARIO_TYPE.SCENARIO_NONE;
END_IF;

// === SCENARIO PRIORITY RESOLUTION ===
// Produces VIO_Scenario_Req_Final (TRACE ONLY, not executed directly)
IF VI_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP THEN
    VIO_Scenario_Req_Final := 0;
    VIO_Scenario_Source := SRC_SAFETY;
ELSIF VIO_Scenario_Req_Operator <> 0 THEN
    VIO_Scenario_Req_Final := VIO_Scenario_Req_Operator;
    VIO_Scenario_Source := SRC_OPERATOR;
ELSIF VIO_Scenario_Req_Gateway <> 0 THEN
    VIO_Scenario_Req_Final := VIO_Scenario_Req_Gateway;
    VIO_Scenario_Source := SRC_GATEWAY;
ELSIF VIO_Scenario_Req_Rule <> 0 THEN
    VIO_Scenario_Req_Final := VIO_Scenario_Req_Rule;
    VIO_Scenario_Source := SRC_RULE;
ELSE
    VIO_Scenario_Req_Final := GVL_STATUS.G_Current_Scenario;
    VIO_Scenario_Source := SRC_NONE;
END_IF;

VIO_Scenario_Intent := VIO_Scenario_Req_Final;

// === FAIL-SAFE SCENARIO CLAMP ===
CASE VI_System_Mode OF
    E_System_Operating_Mode.MODE_SAFE_STOP:
        VIO_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_NONE;

    E_System_Operating_Mode.MODE_FREEZE_PROTECTION:
        VIO_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_NONE;

    E_System_Operating_Mode.MODE_DEGRADED:
        CASE VIO_Scenario_Intent OF
            E_SCENARIO_TYPE.SCENARIO_NONE,
            E_SCENARIO_TYPE.SCENARIO_PRESENCE,
            E_SCENARIO_TYPE.SCENARIO_AWAY,
            E_SCENARIO_TYPE.SCENARIO_SLEEP:
                ; // allowed in degraded
        ELSE
            VIO_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_NONE;
        END_CASE;
END_CASE;

// === CONTEXT FAIL-SAFE AUTOMATION ===
// If security is armed and no explicit source is requesting another scenario,
// force safe occupancy context to AWAY while system remains in MODE_NORMAL.
IF VI_System_Mode = E_System_Operating_Mode.MODE_NORMAL THEN
    IF VI_Security_Armed AND
       (VIO_Scenario_Req_Operator = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (VIO_Scenario_Req_Gateway = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (VIO_Scenario_Req_Rule = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (VIO_Scenario_Intent <> E_SCENARIO_TYPE.SCENARIO_AWAY) THEN

        IF VIO_Scenario_Intent <> E_SCENARIO_TYPE.SCENARIO_AWAY THEN
            VIO_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_AWAY;
            VIO_Scenario_Source := SRC_POLICY;

            fbLogEvent(
                VI_Event_Type := 5,
                VI_Timestamp := VI_System_Time_MS,
                VI_Param1 := TO_UDINT(VIO_Scenario_Source),
                VI_Param2 := TO_UDINT(E_SCENARIO_TYPE.SCENARIO_AWAY)
            );
        END_IF;
    END_IF;
END_IF;

// === DEGRADED-AWARE SCENARIO ADAPTATION ===
// Soft adaptation in degraded mode: keep explicit requests intact,
// but if no source is requesting a scenario, move behavior to a safer baseline.
IF VI_System_Mode = E_System_Operating_Mode.MODE_DEGRADED THEN
    IF (VIO_Scenario_Req_Operator = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (VIO_Scenario_Req_Gateway = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (VIO_Scenario_Req_Rule = E_SCENARIO_TYPE.SCENARIO_NONE) THEN

        IF VI_Security_Armed THEN
            IF VIO_Scenario_Intent <> E_SCENARIO_TYPE.SCENARIO_AWAY THEN
                VIO_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_AWAY;
                VIO_Scenario_Source := SRC_POLICY;

                fbLogEvent(
                    VI_Event_Type := 6,
                    VI_Timestamp := VI_System_Time_MS,
                    VI_Param1 := TO_UDINT(VIO_Scenario_Source),
                    VI_Param2 := TO_UDINT(E_SCENARIO_TYPE.SCENARIO_AWAY)
                );
            END_IF;

        ELSIF VIO_Scenario_Intent = E_SCENARIO_TYPE.SCENARIO_PRESENCE THEN
            IF VIO_Scenario_Intent <> E_SCENARIO_TYPE.SCENARIO_SLEEP THEN
                VIO_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_SLEEP;
                VIO_Scenario_Source := SRC_POLICY;

                fbLogEvent(
                    VI_Event_Type := 7,
                    VI_Timestamp := VI_System_Time_MS,
                    VI_Param1 := TO_UDINT(VIO_Scenario_Source),
                    VI_Param2 := TO_UDINT(E_SCENARIO_TYPE.SCENARIO_SLEEP)
                );
            END_IF;
        END_IF;
    END_IF;
END_IF;

fbScenarioManager(
    VI_System_Time_MS := VI_System_Time_MS,
    VI_Activate_Request := VIO_Scenario_Intent,
    VI_IsActivePLC := VI_IsActivePLC,
    VI_System_Mode := VI_System_Mode,
    VO_Current_Scenario => GVL_STATUS.G_Current_Scenario
);

// >>> BULK_SYNC_ANCHOR: FB_System_Scenario_Arbitration <<<

// 1. Генерация собственного пульса (меандр 100 мс)
L_Pulse_Timer(IN := NOT L_Pulse_Timer.Q, PT := T#100ms, VI_System_Time_MS := VI_System_Time_MS);
IF L_Pulse_Timer.Q THEN
    L_Pulse_State := NOT L_Pulse_State;
END_IF;
VO_Local_Pulse := L_Pulse_State;

// 2. Определение роли через Heartbeat
L_Heartbeat(
    VI_Local_ID := VI_Local_PLC_ID,
    VI_System_Time := VI_System_Time_MS,
    VI_Remote_Pulse := VI_Remote_Pulse,
    VI_Remote_Is_Active := VI_Remote_Is_Active,
    VI_Gateway_Ping_OK := VI_Gateway_Ping_OK
);

IF L_Heartbeat.VO_Is_Active THEN
    VO_Local_Role := E_PLC_ROLE.ROLE_ACTIVE;
    VO_Status_Msg := 'ПЛК АКТИВЕН (ВЕДУЩИЙ)';
ELSE
    VO_Local_Role := E_PLC_ROLE.ROLE_STANDBY;
    VO_Status_Msg := 'ПЛК В РЕЗЕРВЕ (ВЕДОМЫЙ)';
END_IF;

// 3. Запрос на синхронизацию при переходе в ACTIVE
IF VO_Local_Role = E_PLC_ROLE.ROLE_ACTIVE AND L_Prev_Role = E_PLC_ROLE.ROLE_STANDBY THEN
    VO_Sync_Data_Req := TRUE;
ELSE
    VO_Sync_Data_Req := FALSE;
END_IF;

L_State_Replicator(
    VI_Local_Role := VO_Local_Role,
    VI_Sync_Req := VO_Sync_Data_Req,
    VI_Local_State := VI_Local_State,
    VI_Remote_State := VI_Remote_State,
    VI_System_Time_MS := VI_System_Time_MS
);
VO_Synced_State := L_State_Replicator.VO_Synced_State;
VO_State_Updated := L_State_Replicator.VO_State_Updated;

L_Prev_Role := VO_Local_Role;
// >>> BULK_SYNC_ANCHOR: FB_Redundancy_Manager <<<

// Отслеживание изменения сигнала
IF VI_Heartbeat_Signal <> L_Last_Heartbeat_State THEN
    L_Last_Heartbeat_Time := VI_System_Time_MS;
    L_Last_Heartbeat_State := VI_Heartbeat_Signal;
END_IF;

// Проверка таймаута
L_Elapsed_Time := (SEL(VI_System_Time_MS >= L_Last_Heartbeat_Time, VI_System_Time_MS - L_Last_Heartbeat_Time, (4294967295 - L_Last_Heartbeat_Time) + VI_System_Time_MS + 1));

IF L_Elapsed_Time > VI_Timeout_MS THEN
    VO_Module_Online := FALSE;
    VO_Error_Active := TRUE;
ELSE
    VO_Module_Online := TRUE;
    VO_Error_Active := FALSE;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_IO_Module_Watchdog <<<

// ==============================================================================
// System evacuation helper
//
// Internal helper for PRG_System.
// Owns evacuation guidance, target/hazard zone name projection,
// and evacuation lighting activation.
// ==============================================================================



FOR L_i := 1 TO 32 DO
    GVL_STATE.G_Evac_Guidance[L_i] := 0;

    IF GVL_STATE.G_Evac_Hazard_Zone[L_i] THEN
        GVL_STATE.G_Evac_Guidance[L_i] := -1;
    END_IF;

    IF GVL_CONFIG.G_Evac_Exit_Zones[L_i] AND NOT GVL_STATE.G_Evac_Hazard_Zone[L_i] THEN
        GVL_STATE.G_Evac_Guidance[L_i] := 1;
    END_IF;
END_FOR;

GVL_STATUS.G_Evac_Target_Zone_Name := '';
GVL_STATUS.G_Evac_Hazard_Zone_Name := '';

FOR L_i := 1 TO 32 DO
    IF (GVL_STATUS.G_Evac_Hazard_Zone_Name = '') AND GVL_STATE.G_Evac_Hazard_Zone[L_i] THEN
        GVL_STATUS.G_Evac_Hazard_Zone_Name := GVL_CONFIG.G_Evac_Zone_Names[L_i];
        IF GVL_STATUS.G_Evac_Hazard_Zone_Name = '' THEN
            GVL_STATUS.G_Evac_Hazard_Zone_Name := CONCAT('Zone ', INT_TO_STRING(L_i));
        END_IF;
    END_IF;

    IF (GVL_STATUS.G_Evac_Target_Zone_Name = '') AND (GVL_STATE.G_Evac_Guidance[L_i] = 1) THEN
        GVL_STATUS.G_Evac_Target_Zone_Name := GVL_CONFIG.G_Evac_Zone_Names[L_i];
        IF GVL_STATUS.G_Evac_Target_Zone_Name = '' THEN
            GVL_STATUS.G_Evac_Target_Zone_Name := CONCAT('Zone ', INT_TO_STRING(L_i));
        END_IF;
    END_IF;
END_FOR;

IF GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP AND GVL_STATE.G_Safety_Smoke_Latched THEN
    GVL_STATE.G_Evacuation_Lighting_Active := TRUE;
ELSE
    GVL_STATE.G_Evacuation_Lighting_Active := FALSE;
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_System_Evacuation <<<

// Applies command + allocation overrides to execution outputs.

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    IF VI_Block_Heating OR (NOT VI_Manifold_Enabled[L_i]) THEN
        VIO_Manifold_Pumps[L_i] := FALSE;
        VIO_Manifold_Valves[L_i] := 0.0;

        FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
            IF VI_Zone_Configs[L_j].manifold_id = L_i THEN
                VIO_Zone_Valves[L_j] := FALSE;
            END_IF;
        END_FOR;
    END_IF;
END_FOR;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Override_Layer <<<

R_Trig_Start(CLK := VI_Start_Auth);

IF VI_Reset_Success THEN
    VO_State.Is_Success := FALSE;
END_IF;

IF R_Trig_Start.Q AND NOT VO_State.is_pending AND NOT VO_State.Is_Locked THEN
    VO_State.is_pending := TRUE;
    VO_State.Auth_Method := VI_Method;
    L_Start_Time := VI_System_Time_MS;
    VO_State.Attempts_Left := 3;
    VO_State.Is_Success := FALSE;
    VO_State.Is_Locked := FALSE;
    L_Prev_User_Code := '';

    IF VI_Method <> E_TwoFactor_Method.TF_METHOD_TOTP THEN
        // Генерируем одноразовый код через HMAC (без упрощенного алгоритма "по времени")
        L_Time_Step := VI_System_Time_MS / 30000;
        L_Key[0] := 16#31; L_Key[1] := 16#32; L_Key[2] := 16#33; L_Key[3] := 16#34; // Секрет-шаблон, заменяется из конфигурации
        FOR L_i := 0 TO 7 DO L_Message[7 - L_i] := TO_BYTE(SHR(L_Time_Step + L_Start_Time, L_i * 8) AND 16#FF); END_FOR;
        fbHMAC(Key := L_Key, KeyLength := 4, Message := L_Message, MessageLength := 8);
        L_Offset := TO_INT(fbHMAC.Hash[19] AND 16#0F);
        L_Truncated_Hash := (SHL(TO_UDINT(fbHMAC.Hash[L_Offset] AND 16#7F), 24) OR SHL(TO_UDINT(fbHMAC.Hash[L_Offset+1] AND 16#FF), 16) OR SHL(TO_UDINT(fbHMAC.Hash[L_Offset+2] AND 16#FF), 8) OR TO_UDINT(fbHMAC.Hash[L_Offset+3] AND 16#FF));
        L_Generated_Code := UDINT_TO_STRING(L_Truncated_Hash MOD 1000000);
        WHILE LEN(L_Generated_Code) < 6 DO
            L_Generated_Code := CONCAT('0', L_Generated_Code);
        END_WHILE;

        VO_Code_To_Send := L_Generated_Code;
        VO_Send_Code_Req := TRUE;
    ELSE
        // Для TOTP код не отправляем
        VO_Code_To_Send := '';
        VO_Send_Code_Req := FALSE;
    END_IF;
ELSE
    VO_Send_Code_Req := FALSE;
END_IF;

IF VO_State.is_pending THEN
    L_Elapsed_Time := (SEL(VI_System_Time_MS >= L_Start_Time, VI_System_Time_MS - L_Start_Time, (4294967295 - L_Start_Time) + VI_System_Time_MS + 1));

    IF L_Elapsed_Time < (GVL_CONSTANTS.C_MS_IN_MINUTE * 5) THEN
        VO_State.Time_Left_S := TO_UINT(((GVL_CONSTANTS.C_MS_IN_MINUTE * 5) - L_Elapsed_Time) / 1000);
    ELSE
        VO_State.Time_Left_S := 0;
    END_IF;

    IF VI_User_Code <> '' AND VI_User_Code <> L_Prev_User_Code THEN
        L_Code_Valid := FALSE;

        IF VI_Method = E_TwoFactor_Method.TF_METHOD_TOTP THEN
            // Вычисляем TOTP для текущего шага времени (30 секунд)
            L_Time_Step := VI_System_Time_MS / 30000; 

            // Подготовка ключа (в реальном проекте берется из GVL_CONFIG)
            L_Key[0] := 16#31; L_Key[1] := 16#32; L_Key[2] := 16#33; L_Key[3] := 16#34; // '1234'

            // Проверка текущего шага
            FOR L_i := 0 TO 7 DO L_Message[7 - L_i] := TO_BYTE(SHR(L_Time_Step, L_i * 8) AND 16#FF); END_FOR;
            fbHMAC(Key := L_Key, KeyLength := 4, Message := L_Message, MessageLength := 8);
            L_Offset := TO_INT(fbHMAC.Hash[19] AND 16#0F);
            L_Truncated_Hash := (SHL(TO_UDINT(fbHMAC.Hash[L_Offset] AND 16#7F), 24) OR SHL(TO_UDINT(fbHMAC.Hash[L_Offset+1] AND 16#FF), 16) OR SHL(TO_UDINT(fbHMAC.Hash[L_Offset+2] AND 16#FF), 8) OR TO_UDINT(fbHMAC.Hash[L_Offset+3] AND 16#FF));
            L_Current_TOTP := UDINT_TO_STRING(L_Truncated_Hash MOD 1000000);
            WHILE LEN(L_Current_TOTP) < 6 DO L_Current_TOTP := CONCAT('0', L_Current_TOTP); END_WHILE;

            // Проверка предыдущего шага (для компенсации рассинхронизации)
            FOR L_i := 0 TO 7 DO L_Message[7 - L_i] := TO_BYTE(SHR(L_Time_Step - 1, L_i * 8) AND 16#FF); END_FOR;
            fbHMAC(Key := L_Key, KeyLength := 4, Message := L_Message, MessageLength := 8);
            L_Offset := TO_INT(fbHMAC.Hash[19] AND 16#0F);
            L_Truncated_Hash := (SHL(TO_UDINT(fbHMAC.Hash[L_Offset] AND 16#7F), 24) OR SHL(TO_UDINT(fbHMAC.Hash[L_Offset+1] AND 16#FF), 16) OR SHL(TO_UDINT(fbHMAC.Hash[L_Offset+2] AND 16#FF), 8) OR TO_UDINT(fbHMAC.Hash[L_Offset+3] AND 16#FF));
            L_Prev_TOTP := UDINT_TO_STRING(L_Truncated_Hash MOD 1000000);
            WHILE LEN(L_Prev_TOTP) < 6 DO L_Prev_TOTP := CONCAT('0', L_Prev_TOTP); END_WHILE;

            IF VI_User_Code = L_Current_TOTP OR VI_User_Code = L_Prev_TOTP THEN
                L_Code_Valid := TRUE;
            END_IF;
        ELSE
            IF VI_User_Code = L_Generated_Code THEN
                L_Code_Valid := TRUE;
            END_IF;
        END_IF;

        IF L_Code_Valid THEN
            VO_State.Is_Success := TRUE;
            VO_State.is_pending := FALSE;
        ELSE
            IF VO_State.Attempts_Left > 0 THEN
                VO_State.Attempts_Left := VO_State.Attempts_Left - 1;
            END_IF;

            IF VO_State.Attempts_Left = 0 THEN
                VO_State.Is_Locked := TRUE;
                VO_State.is_pending := FALSE;
                L_Lockout_Start_Time := VI_System_Time_MS; // Блокировка на 5 минут
            END_IF;
        END_IF;
    END_IF;
    L_Prev_User_Code := VI_User_Code;

    IF L_Elapsed_Time > (GVL_CONSTANTS.C_MS_IN_MINUTE * 5) THEN
        VO_State.is_pending := FALSE; // Таймаут
    END_IF;
END_IF;

IF VO_State.Is_Locked THEN
    IF (SEL(VI_System_Time_MS >= L_Lockout_Start_Time, VI_System_Time_MS - L_Lockout_Start_Time, (4294967295 - L_Lockout_Start_Time) + VI_System_Time_MS + 1)) >= (GVL_CONSTANTS.C_MS_IN_MINUTE * 5) THEN
        VO_State.Is_Locked := FALSE;
    END_IF;
END_IF;

// 1. Расчет калиброванного значения
CASE VI_Type OF
    1: VO_Calibrated_Value := VI_Raw_Value + VI_Calib_Record.offset;
    2, 3: VO_Calibrated_Value := (VI_Raw_Value * VI_Calib_Record.multiplier) + VI_Calib_Record.offset;
END_CASE;

// 2. Верификация через 1 час (ТЗ 9.5)
IF VI_Start_Verification AND NOT VO_Verification_Active THEN
    VO_Verification_Active := TRUE;
    L_Initial_Value := VO_Calibrated_Value;
END_IF;

L_Verification_Timer(IN := VO_Verification_Active, PT := T#1h, VI_System_Time_MS := VI_System_Time_MS);

IF L_Verification_Timer.Q THEN
    VO_Verification_Active := FALSE;

    // ТЗ 9.5: Отклонение ≤2.0% (норма) / >5.0% (ошибка)
    IF L_Initial_Value <> 0 THEN
        VO_Deviation_Percent := ABS(VO_Calibrated_Value - L_Initial_Value) / L_Initial_Value * 100.0;
    ELSE
        VO_Deviation_Percent := 0.0;
    END_IF;

    VO_Verification_Failed := (VO_Deviation_Percent > 5.0);
END_IF;

// ==============================================================================
// System gateway intent helper
//
// Internal helper for PRG_System / extracted system gateway contour.
// Owns gateway FB call, user intent publication, gateway command gates,
// and allowed configuration/time/scenario writes.
// ==============================================================================



fbGateway(
    VI_System_Time_MS := VI_System_Time_MS,
    VI_Local_PLC_Role := SEL(VI_IsActivePLC, E_PLC_ROLE.ROLE_STANDBY, E_PLC_ROLE.ROLE_ACTIVE),
    VI_Incoming_Command := GVL_GATEWAY.G_Gateway_Command,
    VI_Command_Received := GVL_GATEWAY.G_Gateway_Command_Received,
    VI_FloorHeating_Temps := VIO_FloorHeating_Temps,
    VI_Room_Temps := GVL_STATE.G_Room_Temps,
    VI_Zone_Valve_States := VIO_Zone_Valve_States,
    VI_Manifold_Pressures := GVL_STATE.G_Manifold_Pressures,
    VI_Manifold_Pump_States := GVL_STATE.G_Manifold_Pumps,
    VI_Outdoor_Temp := GVL_STATE.G_Outdoor_Temp,
    VI_Security_Armed := GVL_ALARM.G_Security_Armed,
    VI_Flood_Alarm_Active := GVL_ALARM.G_Flood_Alarm_Active,
    VI_Gas_Alarm_Active := GVL_ALARM.G_Gas_Alarm_Active,
    VI_Fire_Alarm_Active := GVL_ALARM.G_Fire_Alarm_Active,
    VI_Methane_Concentration := GVL_STATE.G_Methane_Sensors[1],
    VI_Lighting_Base_Levels := VIO_Lighting_Base_Levels,
    VI_Socket_States := GVL_STATE.G_Socket_States,
    VI_Blinds_Positions := GVL_STATE.G_Blinds_Positions,
    VI_Active_Scenario := GVL_STATUS.G_Current_Scenario,
    VI_Send_2FA_Req := GVL_COMMAND.G_Send_2FA_Req,
    VI_2FA_Code := GVL_COMMAND.G_2FA_Code_Out,
    VI_Allowed_IPs := GVL_CONFIG.G_Allowed_IPs,
    VO_Telegram_Msg => GVL_GATEWAY.G_Gateway_Telegram_Msg,
    VO_Send_Telegram => GVL_GATEWAY.G_Gateway_Send_Telegram,
    VO_HMI_Status_Message => GVL_GATEWAY.G_Gateway_HMI_Status_Message,

    VO_Data_Ready => GVL_GATEWAY.G_Gateway_Data_Ready,
    VO_Modbus_Registers => GVL_GATEWAY.G_Gateway_Modbus_Registers,
