// ============================================================================== // System alarm orchestrator helper // // Internal helper for PRG_System. // Owns FB_Alarm_Manager call and alarm output projection. // ==============================================================================
fbAlarmManager( VI_System_Time_MS := GVL_STATUS.G_System_Time_MS, VI_IsActivePLC := GVL_STATUS.G_Is_Active_PLC, VI_Gas_Alarm := GVL_ALARM.G_Gas_Alarm_Active, VI_Fire_Alarm := GVL_ALARM.G_Fire_Alarm_Active, VI_Flood_Alarm := GVL_ALARM.G_Flood_Alarm_Active, VI_Security_Alarm := GVL_ALARM.G_Security_Alarm, VI_First_Fault_Active := VI_First_Fault_Active, VI_First_Fault_Type := VI_First_Fault_Type, VI_First_Fault_Source := VI_First_Fault_Source, VI_Boiler_Errors := GVL_STATE.G_Boiler_Error, VI_Security_Msg := GVL_STATUS.G_Security_Status_Msg, VI_Acknowledge_All := GVL_CONFIG.G_HMI_Ack_Alarms OR GVL_COMMAND.G_Reset_Errors, VI_Mute_Siren := GVL_CONFIG.G_HMI_Mute_Alarm, VIO_Next_Alarm_ID := GVL_ALARM.G_Next_Alarm_ID, VO_Global_Critical => GVL_ALARM.G_Global_Critical, VO_Global_Warning => GVL_ALARM.G_Global_Warning, VO_Siren_Active => GVL_ALARM.G_Global_Siren, VO_Active_Count => GVL_ALARM.G_Active_Alarm_Count, VO_Unacked_Count => GVL_ALARM.G_Unacked_Alarm_Count, VO_Event_Pulse => GVL_STATUS.G_Diagnostics.Alarm_Event_Pulse, VO_Event_Code => GVL_STATUS.G_Diagnostics.Alarm_Event_Code, VO_Event_Value => GVL_STATUS.G_Diagnostics.Alarm_Event_Value, VO_Alarm_List => GVL_ALARM.G_Alarm_List );
// >>> BULK_SYNC_ANCHOR: FB_System_Alarm_Orchestrator <<<

IF NOT VI_IsActivePLC THEN
    RETURN;
END_IF;

CASE VI_System_Mode OF
    E_System_Operating_Mode.MODE_SAFE_STOP,
    E_System_Operating_Mode.MODE_FREEZE_PROTECTION:
        IF VO_Current_Scenario <> E_SCENARIO_TYPE.SCENARIO_NONE THEN
            VO_Current_Scenario := E_SCENARIO_TYPE.SCENARIO_NONE;
            VO_Status_Msg := 'Сценарии принудительно отключены режимом безопасности';
        END_IF;
        RETURN;

    E_System_Operating_Mode.MODE_DEGRADED:
        VO_Status_Msg := 'Смена сценариев заблокирована: деградированный режим';
        RETURN;
END_CASE;

IF VI_Activate_Request <> VO_Current_Scenario THEN
    // Проверка минимального времени работы сценария
    IF (VI_System_Time_MS - L_Last_Scenario_Time) >= 60000 OR VO_Current_Scenario = E_SCENARIO_TYPE.SCENARIO_NONE THEN
        // Логика переключения сценариев
        VO_Current_Scenario := VI_Activate_Request;
        L_Last_Scenario_Time := VI_System_Time_MS;

        CASE VO_Current_Scenario OF
        E_SCENARIO_TYPE.SCENARIO_NONE:
            VO_Status_Msg := 'Сценарии отключены';
        E_SCENARIO_TYPE.SCENARIO_AWAY:
            VO_Status_Msg := 'Активирован сценарий: Вне дома (Охрана + Энергосбережение)';
        E_SCENARIO_TYPE.SCENARIO_SLEEP:
            VO_Status_Msg := 'Активирован сценарий: Сон (Ночное освещение + Климат)';
        E_SCENARIO_TYPE.SCENARIO_PRESENCE:
            VO_Status_Msg := 'Активирован сценарий: Имитация присутствия';
        END_CASE;
    END_IF;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_Scenario_Manager <<<


// --- PREHEAT SCENARIO INSERT ---
IF VI_Preheat_Request THEN
    // removed: direct heating write (moved to Heating Manager)
END_IF;

// ==============================================================================
// Adaptive target calculation for heating supply temperature
//
// Internal refactoring helper for FB_Heating_System_Manager.
// The manager remains the public facade; this block only extracts the adaptive
// target calculation section to reduce large-file edit risk.
// ==============================================================================



VO_Target_Supply_Temp := VI_Base_Target_Supply_Temp;
VO_Adaptive_Max_Delta := 0.0;
L_Adaptive_Weighted_Sum := 0.0;
L_Adaptive_Weight_Total := 0.0;
VO_Adaptive_Effective_Delta := 0.0;
VO_Adaptive_Correction := 0.0;

// Global arbitration target is applied before adaptive correction.
IF VI_Global_Target_Temperature > 0.0 THEN
    VO_Target_Supply_Temp := VI_Global_Target_Temperature;
END_IF;

// Final adaptive refinement layer.
FOR L_Adaptive_Zone_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    IF VI_Zone_Configs[L_Adaptive_Zone_i].zone >= 1 AND VI_Zone_Configs[L_Adaptive_Zone_i].zone <= 8 THEN
        CASE VI_Zone_Configs[L_Adaptive_Zone_i].control_type OF
            0:
                L_Adaptive_Delta :=
                    VI_Zone_Configs[L_Adaptive_Zone_i].design_temp -
                    VI_Floor_Temps[L_Adaptive_Zone_i];
                L_Adaptive_Weight := 0.6;
            1, 2:
                L_Adaptive_Delta :=
                    VI_Zone_Configs[L_Adaptive_Zone_i].design_temp -
                    VI_Room_Temps[VI_Zone_Configs[L_Adaptive_Zone_i].zone];
                L_Adaptive_Weight := 1.0;
            ELSE
                L_Adaptive_Delta :=
                    VI_Zone_Configs[L_Adaptive_Zone_i].design_temp -
                    VI_Room_Temps[VI_Zone_Configs[L_Adaptive_Zone_i].zone];
                L_Adaptive_Weight := 0.8;
        END_CASE;

        IF VI_Zone_Configs[L_Adaptive_Zone_i].zone >= 1 AND VI_Zone_Configs[L_Adaptive_Zone_i].zone <= 4 THEN
            L_Adaptive_Weight := L_Adaptive_Weight * 1.2;
        ELSIF VI_Zone_Configs[L_Adaptive_Zone_i].zone >= 9 THEN
            L_Adaptive_Weight := L_Adaptive_Weight * 0.7;
        END_IF;

        IF L_Adaptive_Weight > 2.0 THEN
            L_Adaptive_Weight := 2.0;
        ELSIF L_Adaptive_Weight < 0.2 THEN
            L_Adaptive_Weight := 0.2;
        END_IF;

        IF L_Adaptive_Delta > VO_Adaptive_Max_Delta THEN
            VO_Adaptive_Max_Delta := L_Adaptive_Delta;
        END_IF;

        L_Adaptive_Weighted_Sum := L_Adaptive_Weighted_Sum + (L_Adaptive_Delta * L_Adaptive_Weight);
        L_Adaptive_Weight_Total := L_Adaptive_Weight_Total + L_Adaptive_Weight;
    END_IF;
END_FOR;

IF L_Adaptive_Weight_Total > 0.0 THEN
    VO_Adaptive_Effective_Delta := L_Adaptive_Weighted_Sum / L_Adaptive_Weight_Total;
END_IF;

IF VO_Adaptive_Effective_Delta > 1.5 THEN
    VO_Adaptive_Correction := 2.0;
ELSIF VO_Adaptive_Effective_Delta > 0.7 THEN
    VO_Adaptive_Correction := 1.0;
ELSIF VO_Adaptive_Effective_Delta < -1.5 THEN
    VO_Adaptive_Correction := -2.0;
ELSIF VO_Adaptive_Effective_Delta < -0.7 THEN
    VO_Adaptive_Correction := -1.0;
ELSE
    VO_Adaptive_Correction := 0.0;
END_IF;

IF VO_Adaptive_Max_Delta > 2.5 AND VO_Adaptive_Correction < 2.0 THEN
    VO_Adaptive_Correction := 2.0;
END_IF;

VO_Target_Supply_Temp := VO_Target_Supply_Temp + VO_Adaptive_Correction;

IF VO_Target_Supply_Temp < 20.0 THEN
    VO_Target_Supply_Temp := 20.0;
ELSIF VO_Target_Supply_Temp > 45.0 THEN
    VO_Target_Supply_Temp := 45.0;
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Adaptive_Target <<<

// ==============================================================================
// Heating circuit control helper
//
// Internal refactoring helper for FB_Heating_System_Manager.
// Owns per-circuit sensor validation, temperature source fallback,
// floor-heating controller call, overheat shutdown, and rule action projection.
// ==============================================================================



VO_Heating_Sensor_Fault := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    fbFloorTempValidator[L_i](
        VI_Value := VI_Floor_Temps[L_i],
        VI_Min_Valid := -40.0,
        VI_Max_Valid := 120.0,
        VI_Fallback_Mode := 0
    );

    L_Climate_Zone_ID := VI_Zone_Configs[L_i].zone;
    IF L_Climate_Zone_ID >= 1 AND L_Climate_Zone_ID <= 16 THEN
        fbRoomTempValidator[L_Climate_Zone_ID](
            VI_Value := VI_Room_Temps[L_Climate_Zone_ID],
            VI_Min_Valid := -40.0,
            VI_Max_Valid := 120.0,
            VI_Fallback_Mode := 0
        );
    END_IF;

    // Floor overheat protection
    L_Overheat_Timer[L_i](
        IN := fbFloorTempValidator[L_i].VO_Value > VI_Config.Overheat_Threshold,
        PT := T#60s,
        VI_System_Time_MS := VI_System_Time_MS
    );

    L_Current_Temp := 0.0;
    L_Sensor_Error := FALSE;

    IF VI_Zone_Configs[L_i].control_type = 1 OR VI_Zone_Configs[L_i].control_type = 2 THEN
        // Primary: room air temperature
        IF (L_Climate_Zone_ID >= 1) AND (L_Climate_Zone_ID <= 16) AND (NOT fbRoomTempValidator[L_Climate_Zone_ID].VO_Error) THEN
            L_Current_Temp := fbRoomTempValidator[L_Climate_Zone_ID].VO_Value;
        ELSIF NOT fbFloorTempValidator[L_i].VO_Error THEN
            L_Current_Temp := fbFloorTempValidator[L_i].VO_Value;
        ELSE
            L_Sensor_Error := TRUE;
        END_IF;
    ELSE
        // Primary: floor temperature
        IF NOT fbFloorTempValidator[L_i].VO_Error THEN
            L_Current_Temp := fbFloorTempValidator[L_i].VO_Value;
        ELSIF (L_Climate_Zone_ID >= 1) AND (L_Climate_Zone_ID <= 16) AND (NOT fbRoomTempValidator[L_Climate_Zone_ID].VO_Error) THEN
            L_Current_Temp := fbRoomTempValidator[L_Climate_Zone_ID].VO_Value;
        ELSE
            L_Sensor_Error := TRUE;
        END_IF;
    END_IF;

    IF L_Sensor_Error THEN
        VO_Heating_Sensor_Fault := TRUE;
        VO_Zone_Valves[L_i] := FALSE;
    ELSE
        L_Zone_Config := VI_Zone_Configs[L_i];
        L_Zone_Config.design_temp := L_Zone_Config.design_temp + VI_Scenario_Adjust;

        L_Floor_Controllers[L_i](
            VI_Current_Temp := L_Current_Temp,
            VI_Config := L_Zone_Config,
            VI_Tariff := VI_Tariff,
            VI_Current_Hour := VI_Current_Hour,
            VI_IsActivePLC := VI_IsActivePLC,
            VI_System_Time_MS := VI_System_Time_MS,
            VO_Valve_Bool => VO_Zone_Valves[L_i]
        );
    END_IF;

    IF L_Overheat_Timer[L_i].Q THEN
        VO_Zone_Valves[L_i] := FALSE;
    END_IF;

    FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_RULES DO
        IF VI_Rule_Actions[L_j].Active AND VI_Rule_Actions[L_j].Target_ID = L_i THEN
            IF VI_Rule_Actions[L_j].Action_Type = E_Rule_Action_Type.ACTION_SET_FLOOR_HEATING THEN
                VO_Zone_Valves[L_i] := (VI_Rule_Actions[L_j].Value > 0.5);
            END_IF;
        END_IF;
    END_FOR;
END_FOR;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Circuit_Control <<<

IF NOT VI_IsActivePLC THEN RETURN; END_IF;

VO_Preheat_Request := FALSE;

L_Elapsed_Time := SEL(VI_System_Time_MS >= L_Last_Reset_Time, VI_System_Time_MS - L_Last_Reset_Time, (4294967295 - L_Last_Reset_Time) + VI_System_Time_MS + 1);

IF L_Elapsed_Time >= GVL_CONSTANTS.C_MS_IN_MINUTE THEN
    L_Last_Reset_Time := VI_System_Time_MS;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_RULES DO
        L_Trigger_Count[L_i] := 0;
    END_FOR;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_RULES DO

    VO_Actions[L_i].Active := FALSE;
    IF VI_Rules[L_i].Enabled THEN
        L_Condition_Met := FALSE;
        L_Current_Value := 0.0;

        IF VI_Rules[L_i].Condition_Target_ID > 0 THEN
            CASE VI_Rules[L_i].Condition_Type OF
                E_Rule_Condition_Type.COND_AIR_TEMP: IF VI_Rules[L_i].Condition_Target_ID <= 16 THEN L_Current_Value := VI_Indoor_Temps[VI_Rules[L_i].Condition_Target_ID]; END_IF;
                E_Rule_Condition_Type.COND_FLOOR_TEMP: IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS THEN L_Current_Value := VI_Floor_Temps[VI_Rules[L_i].Condition_Target_ID]; END_IF;
                E_Rule_Condition_Type.COND_HUMIDITY: IF VI_Rules[L_i].Condition_Target_ID <= 16 THEN L_Current_Value := VI_Humidities[VI_Rules[L_i].Condition_Target_ID]; END_IF;
                E_Rule_Condition_Type.COND_CO2: IF VI_Rules[L_i].Condition_Target_ID <= 16 THEN L_Current_Value := VI_CO2_Levels[VI_Rules[L_i].Condition_Target_ID]; END_IF;
                E_Rule_Condition_Type.COND_MOTION: IF VI_Rules[L_i].Condition_Target_ID <= 16 THEN L_Current_Value := SEL(VI_Motion_Sensors[VI_Rules[L_i].Condition_Target_ID], 0.0, 1.0); END_IF;
                E_Rule_Condition_Type.COND_DOOR_WINDOW: 
                    IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_DOOR_SENSORS THEN
                        L_Current_Value := SEL(VI_Door_Sensors[VI_Rules[L_i].Condition_Target_ID] OR VI_Window_Sensors[VI_Rules[L_i].Condition_Target_ID], 0.0, 1.0);
                    ELSIF VI_Rules[L_i].Condition_Target_ID <= 16 THEN
                        L_Current_Value := SEL(VI_Window_Sensors[VI_Rules[L_i].Condition_Target_ID], 0.0, 1.0);
                    END_IF;
                E_Rule_Condition_Type.COND_FLOOD: IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_FLOOD_SENSORS THEN L_Current_Value := SEL(VI_Water_Sensors[VI_Rules[L_i].Condition_Target_ID], 0.0, 1.0); END_IF;
                E_Rule_Condition_Type.COND_SMOKE: IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_SMOKE_SENSORS THEN L_Current_Value := SEL(VI_Smoke_Sensors[VI_Rules[L_i].Condition_Target_ID], 0.0, 1.0); END_IF;
                E_Rule_Condition_Type.COND_METHANE: IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_METHANE_SENSORS THEN L_Current_Value := VI_Methane_Sensors[VI_Rules[L_i].Condition_Target_ID]; END_IF;
                E_Rule_Condition_Type.COND_CO: IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_CO_SENSORS THEN L_Current_Value := VI_CO_Sensors[VI_Rules[L_i].Condition_Target_ID]; END_IF;
                E_Rule_Condition_Type.COND_TIME_OF_DAY: L_Current_Value := TO_REAL(TOD_TO_UDINT(VI_Current_Time) / GVL_CONSTANTS.C_MS_IN_MINUTE);
                E_Rule_Condition_Type.COND_DAY_OF_WEEK: L_Current_Value := TO_REAL(VI_Day_Of_Week);
            END_CASE;
        ELSE
            IF VI_Rules[L_i].Condition_Type = E_Rule_Condition_Type.COND_TIME_OF_DAY THEN
                L_Current_Value := TO_REAL(TOD_TO_UDINT(VI_Current_Time) / GVL_CONSTANTS.C_MS_IN_MINUTE);
            ELSIF VI_Rules[L_i].Condition_Type = E_Rule_Condition_Type.COND_DAY_OF_WEEK THEN
                L_Current_Value := TO_REAL(VI_Day_Of_Week);
            END_IF;
        END_IF;

        CASE VI_Rules[L_i].Condition_Op OF
            E_Rule_Comparison.COMP_GT: L_Condition_Met := (L_Current_Value > VI_Rules[L_i].Condition_Value);
            E_Rule_Comparison.COMP_LT: L_Condition_Met := (L_Current_Value < VI_Rules[L_i].Condition_Value);
            E_Rule_Comparison.COMP_EQ: L_Condition_Met := (ABS(L_Current_Value - VI_Rules[L_i].Condition_Value) < 0.1);
            E_Rule_Comparison.COMP_GE: L_Condition_Met := (L_Current_Value >= VI_Rules[L_i].Condition_Value);
            E_Rule_Comparison.COMP_LE: L_Condition_Met := (L_Current_Value <= VI_Rules[L_i].Condition_Value);
            E_Rule_Comparison.COMP_IN_RANGE: L_Condition_Met := (L_Current_Value >= VI_Rules[L_i].Condition_Value) AND (L_Current_Value <= VI_Rules[L_i].Condition_Value_Max);
            E_Rule_Comparison.COMP_TRUE: L_Condition_Met := (L_Current_Value > 0.5);
            E_Rule_Comparison.COMP_FALSE: L_Condition_Met := (L_Current_Value < 0.5);
        END_CASE;

        L_Triggers[L_i](CLK := L_Condition_Met);

        IF L_Triggers[L_i].Q THEN
            L_Trigger_Count[L_i] := L_Trigger_Count[L_i] + 1;
            IF L_Trigger_Count[L_i] > 10 THEN
                VO_Actions[L_i].Active := FALSE;
                VO_Actions[L_i].Triggered := FALSE;
                CONTINUE;
            END_IF;
        END_IF;

        IF L_Condition_Met AND (L_Trigger_Count[L_i] <= 10) THEN
            VO_Actions[L_i].Active := TRUE;
            VO_Actions[L_i].Triggered := L_Triggers[L_i].Q;
            VO_Actions[L_i].Action_Type := VI_Rules[L_i].Action_Type;
            VO_Actions[L_i].Target_ID := VI_Rules[L_i].Action_Target_ID;
            VO_Actions[L_i].Value := VI_Rules[L_i].Action_Value;
        END_IF;
    END_IF;
END_FOR;

// >>> BULK_SYNC_ANCHOR: FB_Rule_Engine <<<

IF VI_Count > 0 AND VI_Count <= GVL_CONSTANTS.C_MAX_TREND_DATA_POINTS THEN
    VO_Max := VI_Data[1];
    VO_Min := VI_Data[1];
    L_Sum := 0.0;

    FOR L_i := 1 TO VI_Count DO
        IF VI_Data[L_i] > VO_Max THEN VO_Max := VI_Data[L_i]; END_IF;
        IF VI_Data[L_i] < VO_Min THEN VO_Min := VI_Data[L_i]; END_IF;
        L_Sum := L_Sum + VI_Data[L_i];
    END_FOR;

    VO_Average := L_Sum / INT_TO_REAL(VI_Count);

    IF VI_Count >= 2 THEN
        VO_Trend_Up := (VI_Data[VI_Count] > VI_Data[1]);
        VO_Trend_Down := (VI_Data[VI_Count] < VI_Data[1]);
    END_IF;
END_IF;

L_Outdoor := GVL_STATE.G_Outdoor_Temp;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO

    L_DeltaT := GVL_STATE.G_Room_Temps[L_i] - L_Outdoor;

    L_Loss := L_DeltaT * REAL#0.01 * GVL_HEATING_POLICY.G_Zone_Thermal_Inertia[L_i];

    L_Gain := (GVL_STATE.G_Floor_Temps[L_i] - GVL_STATE.G_Room_Temps[L_i]) * REAL#0.05;

    GVL_HEATING_POLICY.G_Zone_Heat_Loss_Rate[L_i] := L_Loss;
    GVL_HEATING_POLICY.G_Zone_Heat_Gain_Rate[L_i] := L_Gain;

    GVL_HEATING_POLICY.G_Zone_Thermal_Response[L_i] := L_Gain - L_Loss;

    GVL_HEATING_POLICY.G_Zone_Thermal_Demand[L_i] := 
        GVL_STATE.G_Target_Temperature - GVL_STATE.G_Room_Temps[L_i];

    IF ABS(GVL_HEATING_POLICY.G_Zone_Thermal_Response[L_i]) > REAL#0.01 THEN
        GVL_HEATING_POLICY.G_Zone_Time_To_Heat_MS[L_i] := 
            REAL_TO_UDINT(ABS(GVL_HEATING_POLICY.G_Zone_Thermal_Demand[L_i] /
                  GVL_HEATING_POLICY.G_Zone_Thermal_Response[L_i]) * REAL#60000.0);
    ELSE
        GVL_HEATING_POLICY.G_Zone_Time_To_Heat_MS[L_i] := 0;
    END_IF;

    GVL_HEATING_POLICY.G_Zone_Predicted_Temp_30m[L_i] :=
        GVL_STATE.G_Room_Temps[L_i] + 
        GVL_HEATING_POLICY.G_Zone_Thermal_Response[L_i] * REAL#30.0;

    GVL_HEATING_POLICY.G_Zone_Thermal_Model_Confidence[L_i] :=
        LIMIT(REAL#0.0, REAL#1.0, ABS(GVL_HEATING_POLICY.G_Zone_Thermal_Response[L_i]));

END_FOR;

// --- Safety ---
IF VI_Emergency_Stop THEN
    VO_RootCause := E_Heating_RootCause.RC_EMERGENCY_STOP;
    VO_Confidence := 1.0;
    RETURN;
END_IF;

IF VI_Gas_Safety THEN
    VO_RootCause := E_Heating_RootCause.RC_GAS_SAFETY;
    VO_Confidence := 1.0;
    RETURN;
END_IF;

IF VI_IO_Failsafe THEN
    VO_RootCause := E_Heating_RootCause.RC_IO_OFFLINE;
    VO_Confidence := 1.0;
    RETURN;
END_IF;

// --- Aggregate flags ---
L_AnyBoilerOnline := FALSE;
L_AnyBoilerError := FALSE;
L_AnyFlame := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    IF VI_Boiler_OT_Online[L_i] THEN L_AnyBoilerOnline := TRUE; END_IF;
    IF VI_Boiler_Error[L_i] THEN L_AnyBoilerError := TRUE; END_IF;
    IF VI_Boiler_Flame[L_i] THEN L_AnyFlame := TRUE; END_IF;
END_FOR;

L_AnyDemand := FALSE;
L_AnyPumpOn := FALSE;
L_AnyValveOpen := FALSE;
L_LowSupply := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    IF VI_Demand_Map[L_i] THEN L_AnyDemand := TRUE; END_IF;
    IF VI_Manifold_Pumps[L_i] THEN L_AnyPumpOn := TRUE; END_IF;
    IF VI_Manifold_Valves[L_i] > 5.0 THEN L_AnyValveOpen := TRUE; END_IF;
    IF VI_Supply_Temps[L_i] < (VI_Target_Supply - 2.0) THEN L_LowSupply := TRUE; END_IF;
END_FOR;

// --- Boiler ---
IF NOT L_AnyBoilerOnline THEN
    VO_RootCause := E_Heating_RootCause.RC_BOILER_OFFLINE;
    VO_Confidence := 0.9;
    RETURN;
END_IF;

IF L_AnyBoilerError THEN
    VO_RootCause := E_Heating_RootCause.RC_BOILER_ERROR;
    VO_Confidence := 0.9;
    RETURN;
END_IF;

IF NOT L_AnyFlame THEN
    VO_RootCause := E_Heating_RootCause.RC_NO_FLAME;
    VO_Confidence := 0.8;
    RETURN;
END_IF;

// --- Hydraulics ---
IF L_AnyDemand THEN
    IF NOT L_AnyPumpOn THEN
        VO_RootCause := E_Heating_RootCause.RC_PUMP_FAILURE;
        VO_Confidence := 0.8;
        RETURN;
    END_IF;

    IF NOT L_AnyValveOpen THEN
        VO_RootCause := E_Heating_RootCause.RC_VALVES_CLOSED;
        VO_Confidence := 0.8;
        RETURN;
    END_IF;
END_IF;

// --- Thermal ---
IF L_AnyDemand AND L_LowSupply THEN
    VO_RootCause := E_Heating_RootCause.RC_NO_HEAT_TRANSFER;
    VO_Confidence := 0.7;
    RETURN;
END_IF;

// --- Sensors ---
IF VI_Sensor_Error THEN
    VO_RootCause := E_Heating_RootCause.RC_SENSOR_ERROR;
    VO_Confidence := 0.7;
    RETURN;
END_IF;

VO_RootCause := E_Heating_RootCause.RC_NONE;
VO_Confidence := 0.0;

IF NOT L_Initialized THEN
    L_Write_Index := GVL_Retain.G_BlackBox_LastIndex;
    IF L_Write_Index < 0 OR L_Write_Index >= GVL_CONSTANTS.C_MAX_BLACKBOX_RECORDS THEN
        L_Write_Index := 0;
        GVL_Retain.G_BlackBox_LastIndex := 0;
    END_IF;
    L_Initialized := TRUE;
END_IF;

IF VI_Freeze THEN
    GVL_Retain.G_BlackBox_Frozen := TRUE;
END_IF;

VO_Frozen := GVL_Retain.G_BlackBox_Frozen;

IF NOT GVL_Retain.G_BlackBox_Frozen THEN
    GVL_Retain.G_BlackBox_Buffer[L_Write_Index] := VI_Current_Data;
    GVL_Retain.G_BlackBox_LastIndex := L_Write_Index;

    L_Write_Index := L_Write_Index + 1;
    IF L_Write_Index >= GVL_CONSTANTS.C_MAX_BLACKBOX_RECORDS THEN
        L_Write_Index := 0;
    END_IF;
END_IF;

VO_Records_Count := GVL_CONSTANTS.C_MAX_BLACKBOX_RECORDS; // Размер кольцевого буфера
// >>> BULK_SYNC_ANCHOR: FB_BlackBox_Recorder <<<

// ==============================================================================
// System init helper
//
// Internal helper for PRG_System.
// Owns first-boot initialization of RETAIN runtime state.
// ==============================================================================



IF NOT GVL_Retain.G_Initialized THEN
    FOR L_i := 0 TO GVL_CONSTANTS.C_MAX_PRESENCE_HISTORY - 1 DO
        GVL_Retain.G_Presence_History[L_i] := 0;
    END_FOR;

    GVL_Retain.G_History_Write_Idx := 1;
    GVL_Retain.G_History_Total_Events := 0;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
        GVL_Retain.G_Boiler_Accumulated_MS[L_i] := 0;
        GVL_Retain.G_Boiler_Work_Seconds[L_i] := 0;
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
        GVL_Retain.G_Valve_Test_Results[L_i] := FALSE;
    END_FOR;

    VIO_Local_State.Version := 0;
    VIO_Remote_State.Version := 0;

    GVL_Retain.G_Initialized := TRUE;
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_System_Init <<<

// Защёлкиваем аварии независимо друг от друга
IF VI_Gas_Alarm THEN
    VO_Gas_Latched := TRUE;
END_IF;

IF VI_Leak_Alarm THEN
    VO_Leak_Latched := TRUE;
END_IF;

IF VI_Smoke_Alarm THEN
    VO_Smoke_Latched := TRUE;
END_IF;

L_Any_Active := VI_Gas_Alarm OR VI_Leak_Alarm OR VI_Smoke_Alarm;

// Ручной сброс допустим только когда все входные аварийные сигналы уже исчезли
IF VI_Reset AND NOT L_Any_Active THEN
    VO_Gas_Latched := FALSE;
    VO_Leak_Latched := FALSE;
    VO_Smoke_Latched := FALSE;
END_IF;

// Агрегированный аварийный стоп = любая защёлкнутая safety-авария
VO_Emergency_Stop := VO_Gas_Latched OR VO_Leak_Latched OR VO_Smoke_Latched;

// >>> BULK_SYNC_ANCHOR: FB_Safety_Manager <<<

// Extracted candidate from PRG_Heating S6.
// Not connected yet.
// No global switching yet.

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    VIO_Zone_Valves_State[L_i] := VI_Zone_Valves[L_i];
END_FOR;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Adapter_CopyOut <<<

// ==============================================================================
// System recovery helper
//
// Internal helper for PRG_System.
// Owns one-shot recovery of persistent safety/system state after boot.
// ==============================================================================



IF NOT VIO_Recovery_Done THEN
    IF GVL_PERSISTENT.P_Valid THEN
        GVL_STATE.G_Safety_Gas_Latched := GVL_PERSISTENT.P_Safety_Gas_Latched;
        GVL_STATE.G_Safety_Smoke_Latched := GVL_PERSISTENT.P_Safety_Smoke_Latched;
        GVL_STATE.G_Safety_Leak_Latched := GVL_PERSISTENT.P_Safety_Leak_Latched;
        GVL_STATE.G_System_Mode := GVL_PERSISTENT.P_System_Mode;
    END_IF;

    VIO_Recovery_Done := TRUE;
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_System_Recovery <<<

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    VO_Boiler_Modulation_REAL[L_i] := TO_REAL(VI_Boiler_Modulation_Raw[L_i]);
END_FOR;

VO_Heating_Emergency_Stop := VI_Heating_Emergency_Stop;
VO_Heating_Gas_Safety_Stop := VI_Heating_Gas_Safety_Stop;
VO_Heating_DHW_Demand := VI_DHW_Heating_Pump_Feedback;

IF VO_Heating_Emergency_Stop THEN
    VO_Heating_Gas_Safety_Stop := FALSE;
    VO_Heating_DHW_Demand := FALSE;
ELSIF VO_Heating_Gas_Safety_Stop THEN
    VO_Heating_DHW_Demand := FALSE;
ELSIF VI_DHW_Block THEN
    VO_Heating_DHW_Demand := FALSE;
END_IF;

L_Mode_Hold_Timer(IN := TRUE, PT := T#30s, VI_System_Time_MS := VI_System_Time_MS);

IF L_Mode_Hold_Timer.Q THEN
    IF VI_Freeze_Request THEN L_Last_Mode := 2;
    ELSIF VI_Preheat_Request THEN L_Last_Mode := 1;
    ELSE L_Last_Mode := 0;
    END_IF;
END_IF;

CASE L_Last_Mode OF
    2: VO_Target_Temperature := 5.0;
    1: VO_Target_Temperature := 22.0;
    ELSE VO_Target_Temperature := 20.0;
END_CASE;

VO_Target_Temperature := VO_Target_Temperature + VI_Policy_Target_Adjustment;
IF VO_Target_Temperature < 5.0 THEN VO_Target_Temperature := 5.0;
ELSIF VO_Target_Temperature > 26.0 THEN VO_Target_Temperature := 26.0;
END_IF;

VO_Local_Mode := L_Last_Mode;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Local_Context <<<

// reset
VO_Block_Heating := FALSE;
VO_Block_Ventilation := FALSE;
VO_Block_Lighting := FALSE;
VO_Block_Sockets := FALSE;
VO_System_Degraded := FALSE;
VO_Code := 0;

// FIRE has highest priority. Safety-stop ownership remains in PRG_Safety.
IF VI_Fire_Latched THEN
    VO_Block_Heating := TRUE;
    VO_Block_Ventilation := TRUE;
    VO_Block_Sockets := TRUE;
    VO_Code := 100;
    RETURN;
END_IF;

// GAS has higher priority than behavior mode.
IF VI_Gas_Latched THEN
    VO_Block_Heating := TRUE;
    VO_Block_Lighting := TRUE;
    VO_Block_Sockets := TRUE;
    VO_Code := 200;
    RETURN;
END_IF;

// LEAK blocks heating but does not suppress later degradation/mode overlays.
IF VI_Leak_Latched THEN
    VO_Block_Heating := TRUE;
    VO_Code := 300;
END_IF;

// IO degraded blocks heating and marks system degraded.
IF VI_IO_Degraded THEN
    VO_System_Degraded := TRUE;
    VO_Block_Heating := TRUE;
    IF VO_Code = 0 THEN
        VO_Code := 400;
    END_IF;
END_IF;

// Ownership violation marks system degraded. Test/result handler owns any safe-stop reaction.
IF VI_Ownership_Violation THEN
    VO_System_Degraded := TRUE;
    IF VO_Code = 0 THEN
        VO_Code := 500;
    END_IF;
END_IF;

// Behavior mode overlays. These are lower priority than safety/system faults.
CASE VI_Behavior_Mode OF
    BEHAVIOR_AWAY:
        VO_Block_Lighting := TRUE;
        VO_Block_Sockets := TRUE;
        IF VO_Code = 0 THEN
            VO_Code := 600;
        END_IF;

    BEHAVIOR_NIGHT:
        VO_Block_Lighting := TRUE;
        IF VO_Code = 0 THEN
            VO_Code := 700;
        END_IF;

    BEHAVIOR_MAINTENANCE:
        VO_Block_Heating := TRUE;
        VO_Block_Ventilation := TRUE;
        IF VO_Code = 0 THEN
            VO_Code := 800;
        END_IF;
END_CASE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    VO_Manifold_Demand_Map[L_i] := FALSE;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    IF VI_Zone_Valves[L_i] THEN
        L_Manifold_ID := VI_Zone_Configs[L_i].manifold_id;
        IF L_Manifold_ID >= 1 AND L_Manifold_ID <= GVL_CONSTANTS.C_MAX_MANIFOLDS THEN
            VO_Manifold_Demand_Map[L_Manifold_ID] := TRUE;
        END_IF;
    END_IF;
END_FOR;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Demand_Map <<<

// ==============================================================================
// System diagnostics helper
//
// Internal helper for PRG_System.
// Owns diagnostic flag export into GVL_STATUS.G_Diagnostics.
// ==============================================================================


GVL_STATUS.G_Diagnostics.Sensor_Fault :=
    GVL_STATE.G_Heating_Sensor_Fault OR
    GVL_STATE.G_DHW_Sensor_Fault OR
    GVL_STATUS.G_Diagnostics.Manifold_Pressure_Fault_Active OR
    GVL_STATUS.G_Diagnostics.Manifold_Current_Fault_Active OR
    GVL_STATUS.G_Diagnostics.Manifold_Return_Temp_Fault_Active;

GVL_STATUS.G_Diagnostics.IO_Offline :=
    GVL_STATE.G_Heating_IO_Fault OR
    GVL_STATE.G_DHW_IO_Fault OR
    GVL_STATE.G_Ventilation_IO_Fault OR
    GVL_STATE.G_Lighting_IO_Fault;

GVL_STATUS.G_Diagnostics.Subsystem_Degraded :=
    GVL_STATE.G_Heating_Subsystem_Degraded OR
    GVL_STATE.G_DHW_Subsystem_Degraded OR
    GVL_STATE.G_Ventilation_Subsystem_Degraded OR
    GVL_STATUS.G_Diagnostics.Manifold_Pressure_Fault_Active OR
    GVL_STATUS.G_Diagnostics.Manifold_Current_Fault_Active OR
    GVL_STATUS.G_Diagnostics.Manifold_Return_Temp_Fault_Active;

// >>> BULK_SYNC_ANCHOR: FB_System_Diagnostics <<<

L_Policy_Degraded := (VI_System_Mode = E_System_Operating_Mode.MODE_DEGRADED);

GVL_STATE.G_Heating_IO_Fault := FALSE;
GVL_STATE.G_Heating_Sensor_Fault := FALSE;
GVL_STATE.G_Heating_Subsystem_Degraded := FALSE;
L_Sensor_Error := FALSE;
L_Subsys_Degraded := FALSE;

L_IO_Failsafe_Active := FALSE;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MODULES DO
    IF NOT VI_IO_Modules_Online[L_i] THEN
        L_IO_Failsafe_Active := TRUE;
        GVL_STATE.G_Heating_IO_Fault := TRUE;
        GVL_STATE.G_Heating_Subsystem_Degraded := TRUE;
        EXIT;
    END_IF;
END_FOR;

fbSafetyGate(
    VI_System_Mode := VI_System_Mode,
    VI_Emergency_Stop := VI_Emergency_Stop,
    VI_Gas_Safety_Stop := VI_Gas_Safety_Stop,
    VI_IO_Failsafe_Active := L_IO_Failsafe_Active,
    VI_Outdoor_Temp := VI_Outdoor_Temp,
    VI_Freeze_Threshold := VI_Config.Freeze_Threshold,
    VI_Floor_Temps := VI_Floor_Temps,
    VO_Freeze_Mode_Active => L_Freeze_Active,
    VO_Freeze_Target_Supply => L_Freeze_Target_Supply
);

fbSafeState(
    VI_Block_Normal_Heating := fbSafetyGate.VO_Block_Normal_Heating,
    VI_IO_Failsafe_Active := fbSafetyGate.VO_IO_Failsafe_Active,
    VI_Gas_Safety_Active := fbSafetyGate.VO_Gas_Safety_Active,
    VI_Freeze_Active := L_Freeze_Active,
    VI_Freeze_Target_Supply := L_Freeze_Target_Supply,
    VI_Manifold_Temps_Supply := VI_Manifold_Temps_Supply,
    VI_Boiler_Error_Status := VI_Boiler_Error_Status,
    VI_Boiler_OT_Online := VI_Boiler_OT_Online
);

IF fbSafeState.VO_Applied THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
        VO_Zone_Valves[L_i] := fbSafeState.VO_Zone_Valves[L_i];
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
        VO_Manifold_Pumps[L_i] := fbSafeState.VO_Manifold_Pumps[L_i];
        VO_Manifold_Valves[L_i] := fbSafeState.VO_Manifold_Valves[L_i];
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
        VO_Boiler_OT_Enable[L_i] := fbSafeState.VO_Boiler_OT_Enable[L_i];
        VO_Boiler_OT_Setpoint[L_i] := fbSafeState.VO_Boiler_OT_Setpoint[L_i];
        VO_Boiler_Status[L_i] := fbSafeState.VO_Boiler_Status[L_i];
    END_FOR;

    VO_Backup_Circulation_Pump := fbSafeState.VO_Backup_Circulation_Pump;
    VO_Electric_Heater_Enable := fbSafeState.VO_Electric_Heater_Enable;
    VO_Freeze_Risk_Status := fbSafeState.VO_Freeze_Risk_Status;
    RETURN;
END_IF;

VO_Backup_Circulation_Pump := FALSE;
VO_Electric_Heater_Enable := FALSE;
VO_Freeze_Risk_Status := FALSE;

IF L_Freeze_Active THEN
    L_Target_Supply_Temp := L_Freeze_Target_Supply;
ELSE
    L_Target_Supply_Temp := VI_Config.Target_Floor_Temp;
END_IF;

fbAdaptiveTarget(
    VI_Base_Target_Supply_Temp := L_Target_Supply_Temp,
    VI_Global_Target_Temperature := GVL_STATE.G_Target_Temperature,
    VI_Zone_Configs := VI_Zone_Configs,
    VI_Floor_Temps := VI_Floor_Temps,
    VI_Room_Temps := VI_Room_Temps,
    VO_Target_Supply_Temp => L_Target_Supply_Temp
);

fbCircuitControl(
    VI_System_Time_MS := VI_System_Time_MS,
    VI_Current_Hour := VI_Current_Hour,
    VI_IsActivePLC := VI_IsActivePLC,
    VI_Config := VI_Config,
    VI_Tariff := VI_Tariff,
    VI_Scenario_Adjust := 0.0,
    VI_Zone_Configs := VI_Zone_Configs,
    VI_Floor_Temps := VI_Floor_Temps,
    VI_Room_Temps := VI_Room_Temps,
    VI_Rule_Actions := VI_Rule_Actions,
    VO_Zone_Valves => VO_Zone_Valves,
    VO_Heating_Sensor_Fault => L_Sensor_Error
);

GVL_STATE.G_Heating_Sensor_Fault := L_Sensor_Error;

fbDemandMap(
    VI_Zone_Valves := VO_Zone_Valves,
    VI_Zone_Configs := VI_Zone_Configs,
    VO_Manifold_Demand_Map => L_Manifold_Demand_Map
);

fbManifoldControl(
    VI_System_Time_MS := VI_System_Time_MS,
    VI_IsActivePLC := VI_IsActivePLC,
    VI_DHW_Heating_Demand := VI_DHW_Heating_Demand,
    VI_Freeze_Mode_Active := L_Freeze_Active,
    VI_Target_Supply_Temp := L_Target_Supply_Temp,
    VI_Any_Zone_Active := L_Manifold_Demand_Map,
    VI_Manifold_Pressures := VI_Manifold_Pressures,
    VI_Manifold_Currents := VI_Manifold_Currents,
    VI_Manifold_Temps_Supply := VI_Manifold_Temps_Supply,
    VI_Manifold_Temps_Return := VI_Manifold_Temps_Return,
    VO_Manifold_Pumps => VO_Manifold_Pumps,
    VO_Manifold_Valves => VO_Manifold_Valves,
    VO_Status => VO_Status
);

fbValveTestManager(
    VI_System_Time_MS := VI_System_Time_MS,
    VI_IsActivePLC := VI_IsActivePLC,
    VI_Valve_Currents := VI_Manifold_Currents,
    VI_Valve_End_Switches := VI_Manifold_End_Switches,
    VI_Config := VI_Valve_Test_Config
);

IF fbValveTestManager.VO_Test_Active THEN
    L_i := fbValveTestManager.VO_Current_Valve;
    IF L_i >= 1 AND L_i <= GVL_CONSTANTS.C_MAX_MANIFOLDS THEN
        IF fbValveTestManager.VO_Valve_Cmd[L_i] THEN
            VO_Manifold_Valves[L_i] := 100.0;
        ELSE
            VO_Manifold_Valves[L_i] := 0.0;
        END_IF;
        VO_Manifold_Pumps[L_i] := FALSE;
    END_IF;
END_IF;

fbBoilerControl(
    VI_System_Time_MS := VI_System_Time_MS,
    VI_IsActivePLC := VI_IsActivePLC,
    VI_DHW_Heating_Demand := VI_DHW_Heating_Demand,
    VI_DHW_Target_Temp := VI_DHW_Target_Temp,
    VI_Target_Supply_Temp := L_Target_Supply_Temp,
    VI_Freeze_Mode_Active := L_Freeze_Active,
    VI_Policy_Degraded := L_Policy_Degraded,
    VI_Manifold_Pumps := VO_Manifold_Pumps,
    VI_Manifold_Valves := VO_Manifold_Valves,
    VI_Boiler_Flame_Status := VI_Boiler_Flame_Status,
    VI_Boiler_Error_Status := VI_Boiler_Error_Status,
    VI_Boiler_OT_Online := VI_Boiler_OT_Online,
    VI_Boiler_Modulation := VI_Boiler_Modulation,
    VO_Boiler_OT_Enable => VO_Boiler_OT_Enable,
    VO_Boiler_OT_Setpoint => VO_Boiler_OT_Setpoint,
    VO_Boiler_Status => VO_Boiler_Status,
    VO_Any_Subsystem_Degraded => L_Subsys_Degraded
);

GVL_STATE.G_Heating_Subsystem_Degraded := L_Subsys_Degraded;

// >>> BULK_SYNC_ANCHOR: FB_Heating_System_Manager <<<

// default
VO_Mode := BEHAVIOR_HOME;
VO_Mode_Code := 0;

// priority-based transitions
IF VI_Maintenance_Request THEN
    VO_Mode := BEHAVIOR_MAINTENANCE;
    VO_Mode_Code := 300;
ELSIF VI_Away_Request THEN
    VO_Mode := BEHAVIOR_AWAY;
    VO_Mode_Code := 200;
ELSIF VI_Is_Night THEN
    VO_Mode := BEHAVIOR_NIGHT;
    VO_Mode_Code := 100;
END_IF;

VO_System_OK := FALSE;
VO_System_Warning := FALSE;
VO_System_Critical := FALSE;
VO_Status_Msg := '';
VO_System_Mode := E_System_Operating_Mode.MODE_NORMAL;

CASE VI_System_Severity OF
    E_System_Severity.SEV_NORMAL:
        VO_System_OK := TRUE;
        VO_Status_Msg := 'Система в норме';
        VO_System_Mode := E_System_Operating_Mode.MODE_NORMAL;

    E_System_Severity.SEV_WARNING:
        VO_System_Warning := TRUE;
        VO_System_Mode := E_System_Operating_Mode.MODE_DEGRADED;
        CASE VI_Root_Cause OF
            E_System_Root_Cause.ROOT_WATER_LEAK:
                VO_Status_Msg := 'Предупреждение: протечка воды';
            E_System_Root_Cause.ROOT_CO_WARNING:
                VO_Status_Msg := 'Предупреждение: повышенный CO';
            ELSE
                VO_Status_Msg := 'Предупреждение системы';
        END_CASE;

    E_System_Severity.SEV_DEGRADED:
        VO_System_Warning := TRUE;
        VO_System_Mode := E_System_Operating_Mode.MODE_DEGRADED;
        CASE VI_Root_Cause OF
            E_System_Root_Cause.ROOT_SENSOR_FAULT:
                VO_Status_Msg := 'Деградация: ошибка датчика';
            E_System_Root_Cause.ROOT_IO_OFFLINE:
                VO_Status_Msg := 'Деградация: модуль IO недоступен';
            E_System_Root_Cause.ROOT_COMM_FAULT:
                VO_Status_Msg := 'Деградация: ошибка связи';
            E_System_Root_Cause.ROOT_WATCHDOG_FAULT:
                VO_Status_Msg := 'Деградация: watchdog fault';
            E_System_Root_Cause.ROOT_SUBSYSTEM_FAULT:
                VO_Status_Msg := 'Деградация: ошибка подсистемы';
            ELSE
                VO_Status_Msg := 'Деградация системы';
        END_CASE;

    E_System_Severity.SEV_CRITICAL:
        VO_System_Critical := TRUE;

        IF (VI_Root_Cause = E_System_Root_Cause.ROOT_GAS_LEAK OR
            VI_Root_Cause = E_System_Root_Cause.ROOT_CO_CRITICAL) AND
            VI_Freeze_Risk THEN
            VO_System_Mode := E_System_Operating_Mode.MODE_FREEZE_PROTECTION;
        ELSE
            VO_System_Mode := E_System_Operating_Mode.MODE_SAFE_STOP;
        END_IF;

        CASE VI_Root_Cause OF
            E_System_Root_Cause.ROOT_FIRE:
                VO_Status_Msg := 'АВАРИЯ: ПОЖАР';
            E_System_Root_Cause.ROOT_GAS_LEAK:
                VO_Status_Msg := 'АВАРИЯ: УТЕЧКА ГАЗА';
            E_System_Root_Cause.ROOT_CO_CRITICAL:
                VO_Status_Msg := 'АВАРИЯ: КРИТИЧЕСКИЙ CO';
            E_System_Root_Cause.ROOT_WATCHDOG_FAULT:
                VO_Status_Msg := 'АВАРИЯ: WATCHDOG';
            ELSE
                VO_Status_Msg := 'АВАРИЯ СИСТЕМЫ';
        END_CASE;
END_CASE;
// >>> BULK_SYNC_ANCHOR: FB_State_Manager <<<

// ==============================================================================
// Heating safety gate helper
//
// Internal helper for FB_Heating_System_Manager.
// Owns common safety/freeze decision calculation. The manager remains the public
// facade and still projects physical safe-state outputs.
// ==============================================================================



VO_Gas_Safety_Active := VI_Gas_Safety_Stop;
VO_Emergency_Safe_Stop_Active := VI_Emergency_Stop OR (VI_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP);
VO_IO_Failsafe_Active := VI_IO_Failsafe_Active;

VO_Block_Normal_Heating := VO_Gas_Safety_Active OR VO_Emergency_Safe_Stop_Active OR VO_IO_Failsafe_Active;
VO_Freeze_Mode_Active := (VI_System_Mode = E_System_Operating_Mode.MODE_FREEZE_PROTECTION) OR (VI_Outdoor_Temp < -5.0);

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    IF VI_Floor_Temps[L_i] < 7.0 THEN
        VO_Freeze_Mode_Active := TRUE;
    END_IF;
END_FOR;

IF VO_Freeze_Mode_Active THEN
    VO_Freeze_Target_Supply := LIMIT(20.0, VI_Freeze_Threshold + 2.0, 35.0);
ELSE
    VO_Freeze_Target_Supply := 0.0;
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Safety_Gate <<<

// Extracted candidate from PRG_Heating S5.
// Not connected yet.
// Donor logic remains in PRG_Heating until all extracted candidates are prepared.

GVL_STATE.G_Freeze_Hardware_Degraded := GVL_STATUS.G_Diagnostics.Backup_Pump_Fault OR GVL_STATUS.G_Diagnostics.Electric_Heater_Fault;
GVL_STATE.G_Freeze_Hardware_Failed := GVL_STATUS.G_Diagnostics.Backup_Pump_Fault AND GVL_STATUS.G_Diagnostics.Electric_Heater_Fault;

IF GVL_STATE.G_Freeze_Hardware_Failed THEN
    GVL_STATE.G_Backup_Circulation_Pump := FALSE;
    GVL_STATE.G_Electric_Heater_Enable := FALSE;
    GVL_STATE.G_Safety_Freeze_Risk := TRUE;
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Freeze_Hardware <<<

VO_Transition_Allowed := TRUE;
VO_Reason := 'OK';

// no-op transition is always allowed
IF VI_Current_Scenario = VI_Target_Scenario THEN
    RETURN;
END_IF;

// emergency can always be entered
IF VI_Target_Scenario = E_SCENARIO_TYPE.SCENARIO_EMERGENCY THEN
    RETURN;
END_IF;

// from NONE, any target is allowed
IF VI_Current_Scenario = E_SCENARIO_TYPE.SCENARIO_NONE THEN
    RETURN;
END_IF;

// emergency exit is restricted
IF VI_Current_Scenario = E_SCENARIO_TYPE.SCENARIO_EMERGENCY THEN
    CASE VI_Target_Scenario OF
        E_SCENARIO_TYPE.SCENARIO_NONE,
        E_SCENARIO_TYPE.SCENARIO_AWAY,
        E_SCENARIO_TYPE.SCENARIO_SLEEP,
        E_SCENARIO_TYPE.SCENARIO_PRESENCE:
            RETURN;
    ELSE
        VO_Transition_Allowed := FALSE;
        VO_Reason := 'Переход из EMERGENCY в данный сценарий запрещён';
        RETURN;
    END_CASE;
END_IF;

// away exit is restricted to safe occupancy contexts
IF VI_Current_Scenario = E_SCENARIO_TYPE.SCENARIO_AWAY THEN
    CASE VI_Target_Scenario OF
        E_SCENARIO_TYPE.SCENARIO_NONE,
        E_SCENARIO_TYPE.SCENARIO_SLEEP,
        E_SCENARIO_TYPE.SCENARIO_PRESENCE,
        E_SCENARIO_TYPE.SCENARIO_EMERGENCY:
            RETURN;
    ELSE
        VO_Transition_Allowed := FALSE;
        VO_Reason := 'Переход из AWAY в данный сценарий запрещён';
        RETURN;
    END_CASE;
END_IF;

// default: allow
RETURN;
// >>> BULK_SYNC_ANCHOR: FB_Scenario_Transition_Guard <<<

VO_Event_Pulse := FALSE;
VO_Event_Code := 0;
VO_Event_Value := 0.0;

// 1. Детекция новых тревог (антидребезг + передний фронт)
T_Debounce_Gas(IN := VI_Gas_Alarm, PT := T#100ms, VI_System_Time_MS := VI_System_Time_MS);
T_Debounce_Fire(IN := VI_Fire_Alarm, PT := T#100ms, VI_System_Time_MS := VI_System_Time_MS);
T_Debounce_Flood(IN := VI_Flood_Alarm, PT := T#500ms, VI_System_Time_MS := VI_System_Time_MS);
T_Debounce_Security(IN := VI_Security_Alarm, PT := T#100ms, VI_System_Time_MS := VI_System_Time_MS);

R_Trig_Gas(CLK := T_Debounce_Gas.Q);
R_Trig_Fire(CLK := T_Debounce_Fire.Q);
R_Trig_Flood(CLK := T_Debounce_Flood.Q);
R_Trig_Security(CLK := T_Debounce_Security.Q);
R_Trig_First_Fault(CLK := VI_First_Fault_Active);
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    R_Trig_Boiler[L_i](CLK := VI_Boiler_Errors[L_i]);
END_FOR;

// 2. Добавление новых тревог в список (Кольцевой буфер)
L_Pending_Count := 0;
L_Event_Pulse_Latched := FALSE;

IF R_Trig_Gas.Q AND L_Pending_Count < 10 THEN
    L_Pending_Count := L_Pending_Count + 1;
    L_Pending_Alarms[L_Pending_Count].Timestamp_MS := VI_System_Time_MS;
    L_Pending_Alarms[L_Pending_Count].Source := 'Gas';
    L_Pending_Alarms[L_Pending_Count].Source_ID := 0;
    L_Pending_Alarms[L_Pending_Count].Message := 'Критическая концентрация газа!';
    L_Pending_Alarms[L_Pending_Count].Severity := E_ALERT_PRIORITY.ALERT_PRIORITY_CRITICAL;
    L_Pending_Alarms[L_Pending_Count].Is_Active := TRUE;
    L_Pending_Alarms[L_Pending_Count].Is_Acknowledged := FALSE;
END_IF;

IF R_Trig_Fire.Q AND L_Pending_Count < 10 THEN
    L_Pending_Count := L_Pending_Count + 1;
    L_Pending_Alarms[L_Pending_Count].Timestamp_MS := VI_System_Time_MS;
    L_Pending_Alarms[L_Pending_Count].Source := 'Fire';
    L_Pending_Alarms[L_Pending_Count].Source_ID := 0;
    L_Pending_Alarms[L_Pending_Count].Message := 'Обнаружено задымление!';
    L_Pending_Alarms[L_Pending_Count].Severity := E_ALERT_PRIORITY.ALERT_PRIORITY_CRITICAL;
    L_Pending_Alarms[L_Pending_Count].Is_Active := TRUE;
    L_Pending_Alarms[L_Pending_Count].Is_Acknowledged := FALSE;
END_IF;

IF R_Trig_Flood.Q AND L_Pending_Count < 10 THEN
    L_Pending_Count := L_Pending_Count + 1;
    L_Pending_Alarms[L_Pending_Count].Timestamp_MS := VI_System_Time_MS;
    L_Pending_Alarms[L_Pending_Count].Source := 'Flood';
    L_Pending_Alarms[L_Pending_Count].Source_ID := 0;
    L_Pending_Alarms[L_Pending_Count].Message := 'Обнаружена протечка воды!';
    L_Pending_Alarms[L_Pending_Count].Severity := E_ALERT_PRIORITY.ALERT_PRIORITY_CRITICAL;
    L_Pending_Alarms[L_Pending_Count].Is_Active := TRUE;
    L_Pending_Alarms[L_Pending_Count].Is_Acknowledged := FALSE;
END_IF;

IF R_Trig_Security.Q AND L_Pending_Count < 10 THEN
    L_Pending_Count := L_Pending_Count + 1;
    L_Pending_Alarms[L_Pending_Count].Timestamp_MS := VI_System_Time_MS;
    L_Pending_Alarms[L_Pending_Count].Source := 'Security';
    L_Pending_Alarms[L_Pending_Count].Source_ID := 0;
    L_Pending_Alarms[L_Pending_Count].Message := VI_Security_Msg;
    L_Pending_Alarms[L_Pending_Count].Severity := E_ALERT_PRIORITY.ALERT_PRIORITY_CRITICAL;
    L_Pending_Alarms[L_Pending_Count].Is_Active := TRUE;
    L_Pending_Alarms[L_Pending_Count].Is_Acknowledged := FALSE;
END_IF;

IF R_Trig_First_Fault.Q AND L_Pending_Count < 10 THEN
    L_Pending_Count := L_Pending_Count + 1;
    L_Pending_Alarms[L_Pending_Count].Timestamp_MS := VI_System_Time_MS;
    L_Pending_Alarms[L_Pending_Count].Source := 'Diagnostics';
    L_Pending_Alarms[L_Pending_Count].Source_ID := TO_BYTE(VI_First_Fault_Source);

    CASE VI_First_Fault_Type OF
        1: L_First_Fault_Type_Text := 'IO';
        2: L_First_Fault_Type_Text := 'Sensor';
        3: L_First_Fault_Type_Text := 'Comm';
        4: L_First_Fault_Type_Text := 'Subsystem';
        ELSE L_First_Fault_Type_Text := 'Unknown';
    END_CASE;

    CASE VI_First_Fault_Source OF
        1: L_First_Fault_Source_Text := 'Heating';
        2: L_First_Fault_Source_Text := 'DHW';
        3: L_First_Fault_Source_Text := 'Ventilation';
        4: L_First_Fault_Source_Text := 'Lighting';
        5: L_First_Fault_Source_Text := 'Access';
        ELSE L_First_Fault_Source_Text := 'Unknown';
    END_CASE;

    L_Pending_Alarms[L_Pending_Count].Message := CONCAT('Diagnostics root cause: ', CONCAT(L_First_Fault_Source_Text, CONCAT(' / ', L_First_Fault_Type_Text)));
    L_Pending_Alarms[L_Pending_Count].Severity := E_ALERT_PRIORITY.ALERT_PRIORITY_HIGH;
    L_Pending_Alarms[L_Pending_Count].Is_Active := TRUE;
    L_Pending_Alarms[L_Pending_Count].Is_Acknowledged := FALSE;
END_IF;

FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    IF R_Trig_Boiler[L_j].Q AND L_Pending_Count < 10 THEN
        L_Pending_Count := L_Pending_Count + 1;
        L_Pending_Alarms[L_Pending_Count].Timestamp_MS := VI_System_Time_MS;
        L_Pending_Alarms[L_Pending_Count].Source := 'Boiler';
        L_Pending_Alarms[L_Pending_Count].Source_ID := TO_BYTE(L_j);
        L_Pending_Alarms[L_Pending_Count].Message := CONCAT('Авария котла №', INT_TO_STRING(L_j));
        L_Pending_Alarms[L_Pending_Count].Severity := E_ALERT_PRIORITY.ALERT_PRIORITY_HIGH;
        L_Pending_Alarms[L_Pending_Count].Is_Active := TRUE;
        L_Pending_Alarms[L_Pending_Count].Is_Acknowledged := FALSE;
    END_IF;
END_FOR;



// Обработка очереди новых тревог с учетом приоритетов
FOR L_i := 1 TO L_Pending_Count DO

    L_Target_Slot := 0;

    // 1. Ищем пустой слот
    FOR L_k := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
        IF VO_Alarm_List[L_k].ID = 0 THEN
            L_Target_Slot := L_k;
            EXIT;
        END_IF;
    END_FOR;

    // 2. Ищем квитированную тревогу с наименьшим приоритетом
    IF L_Target_Slot = 0 THEN
        L_Min_Pri := 999;
        FOR L_k := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
            IF VO_Alarm_List[L_k].Is_Acknowledged AND TO_INT(VO_Alarm_List[L_k].Severity) < L_Min_Pri THEN
                L_Min_Pri := TO_INT(VO_Alarm_List[L_k].Severity);
                L_Target_Slot := L_k;
            END_IF;
        END_FOR;
    END_IF;

    // 3. Ищем неквитированную тревогу с наименьшим приоритетом (если он ниже добавляемой)
    IF L_Target_Slot = 0 THEN
        L_Min_Pri := 999;
        FOR L_k := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
            IF TO_INT(VO_Alarm_List[L_k].Severity) < L_Min_Pri AND TO_INT(VO_Alarm_List[L_k].Severity) < TO_INT(L_Pending_Alarms[L_i].Severity) THEN
                L_Min_Pri := TO_INT(VO_Alarm_List[L_k].Severity);
                L_Target_Slot := L_k;
            END_IF;
        END_FOR;
    END_IF;

    IF L_Target_Slot = 0 THEN 
        // Буфер полон критических неквитированных тревог. Не затираем!
        CONTINUE; 
    END_IF;

    VO_Alarm_List[L_Target_Slot] := L_Pending_Alarms[L_i];
    VO_Alarm_List[L_Target_Slot].ID := VIO_Next_Alarm_ID;
    VIO_Next_Alarm_ID := VIO_Next_Alarm_ID + 1;
    IF VIO_Next_Alarm_ID = 0 THEN VIO_Next_Alarm_ID := 1; END_IF;
    IF NOT L_Event_Pulse_Latched THEN
        VO_Event_Pulse := TRUE;
        VO_Event_Code := 1203;
        VO_Event_Value := TO_REAL(VO_Alarm_List[L_Target_Slot].Severity);
        L_Event_Pulse_Latched := TRUE;
    END_IF;
END_FOR;

// 3. Обновление статуса существующих тревог (ушли ли они?)
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
    IF VO_Alarm_List[L_i].ID <> 0 THEN
        IF VO_Alarm_List[L_i].Source = 'Gas' THEN VO_Alarm_List[L_i].Is_Active := VI_Gas_Alarm;
        ELSIF VO_Alarm_List[L_i].Source = 'Fire' THEN VO_Alarm_List[L_i].Is_Active := VI_Fire_Alarm;
        ELSIF VO_Alarm_List[L_i].Source = 'Flood' THEN VO_Alarm_List[L_i].Is_Active := VI_Flood_Alarm;
        ELSIF VO_Alarm_List[L_i].Source = 'Security' THEN VO_Alarm_List[L_i].Is_Active := VI_Security_Alarm;
        ELSIF VO_Alarm_List[L_i].Source = 'Diagnostics' THEN VO_Alarm_List[L_i].Is_Active := VI_First_Fault_Active;
        ELSIF VO_Alarm_List[L_i].Source = 'Boiler' THEN 
            IF TO_INT(VO_Alarm_List[L_i].Source_ID) >= 1 AND TO_INT(VO_Alarm_List[L_i].Source_ID) <= GVL_CONSTANTS.C_MAX_BOILERS THEN
                VO_Alarm_List[L_i].Is_Active := VI_Boiler_Errors[TO_INT(VO_Alarm_List[L_i].Source_ID)];
            END_IF;
        END_IF;
    END_IF;
END_FOR;

// 4. Квитирование тревог
IF VI_Acknowledge_All THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
        IF VO_Alarm_List[L_i].ID <> 0 THEN
            VO_Alarm_List[L_i].Is_Acknowledged := TRUE;
        END_IF;
    END_FOR;

    IF NOT L_Event_Pulse_Latched THEN
        VO_Event_Pulse := TRUE;
        VO_Event_Code := 1201;
        VO_Event_Value := TO_REAL(VO_Unacked_Count);
        L_Event_Pulse_Latched := TRUE;
    END_IF;
END_IF;

// 4.5 Автоквитирование некритичных тревог, если они больше не активны
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
    IF VO_Alarm_List[L_i].ID <> 0 AND NOT VO_Alarm_List[L_i].Is_Active AND NOT VO_Alarm_List[L_i].Is_Acknowledged THEN
        IF VO_Alarm_List[L_i].Severity <> E_ALERT_PRIORITY.ALERT_PRIORITY_CRITICAL THEN
            VO_Alarm_List[L_i].Is_Acknowledged := TRUE;
        END_IF;
    END_IF;
END_FOR;

// 5. Очистка списка (удаление неактивных И квитированных тревог)
// В кольцевом буфере мы просто помечаем слот как пустой (ID = 0), без сдвига массива
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
    IF VO_Alarm_List[L_i].ID <> 0 AND NOT VO_Alarm_List[L_i].Is_Active AND VO_Alarm_List[L_i].Is_Acknowledged THEN
        // Удаляем тревогу
        VO_Alarm_List[L_i].ID := 0;
        IF NOT L_Event_Pulse_Latched THEN
            VO_Event_Pulse := TRUE;
            VO_Event_Code := 1202;
            VO_Event_Value := 0.0;
            L_Event_Pulse_Latched := TRUE;
        END_IF;
    END_IF;
END_FOR;


// 6. Подсчет статистики и формирование глобальных флагов
VO_Global_Critical := FALSE;
VO_Global_Warning := FALSE;
VO_Siren_Active := FALSE;
VO_Active_Count := 0;
VO_Unacked_Count := 0;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
    IF VO_Alarm_List[L_i].ID <> 0 THEN
        IF VO_Alarm_List[L_i].Is_Active THEN
            VO_Active_Count := VO_Active_Count + 1;
        END_IF;

        IF NOT VO_Alarm_List[L_i].Is_Acknowledged THEN
            VO_Unacked_Count := VO_Unacked_Count + 1;

            IF VO_Alarm_List[L_i].Severity = E_ALERT_PRIORITY.ALERT_PRIORITY_CRITICAL THEN
                VO_Global_Critical := TRUE;
                // Сирена работает только для неквитированных критических тревог, если не включен Mute
                IF NOT VI_Mute_Siren THEN
                    VO_Siren_Active := TRUE;
                END_IF;
            ELSIF VO_Alarm_List[L_i].Severity = E_ALERT_PRIORITY.ALERT_PRIORITY_HIGH THEN
                VO_Global_Warning := TRUE;
            END_IF;
        END_IF;
    END_IF;
END_FOR;
// >>> BULK_SYNC_ANCHOR: FB_Alarm_Manager <<<

L_Current_Slot := (VI_Time_Index / (GVL_CONSTANTS.C_MS_IN_MINUTE * 10)) MOD TO_UDINT(GVL_CONSTANTS.C_MAX_PRESENCE_HISTORY);

IF VI_Mode_Record THEN
    GVL_Retain.G_Presence_History[L_Current_Slot] := 0;
    FOR L_i := 1 TO 32 DO
        IF VI_Light_Inputs[L_i] THEN
            GVL_Retain.G_Presence_History[L_Current_Slot] := GVL_Retain.G_Presence_History[L_Current_Slot] OR SHL(WORD#1, L_i-1);
        END_IF;
    END_FOR;
ELSE
    FOR L_i := 1 TO 32 DO
        VO_Light_Outputs[L_i] := (GVL_Retain.G_Presence_History[L_Current_Slot] AND SHL(WORD#1, L_i-1)) <> 0;
    END_FOR;
END_IF;

METHOD Seed : BOOL

L_seed := VI_Seed_Value;
L_Is_Seeded := TRUE;
Seed := TRUE;
END_METHOD

METHOD Random_Int_Range : UDINT


IF NOT L_Is_Seeded AND VI_System_Time_MS > 0 THEN
    L_seed := VI_System_Time_MS;
    L_Is_Seeded := TRUE;
END_IF;

L_seed := (C_LCG_MULTIPLIER * L_seed) + C_LCG_INCREMENT;

IF VI_max > VI_min THEN
        L_range := VI_max - VI_min;
        // Используем LREAL для точности и исключения выхода за границу
        L_rand_factor := TO_LREAL(L_seed) / C_LCG_MODULUS;
        Random_Int_Range := VI_min + TO_UDINT(L_rand_factor * TO_LREAL(L_range + 1));

        // Финальная защита от переполнения
        IF Random_Int_Range > VI_max THEN
            Random_Int_Range := VI_max;
        END_IF;
    ELSE
        Random_Int_Range := VI_min;
    END_IF;

// ========================================
// Ventilation policy layer
// ========================================
VO_Ventilation_IO_Fault := FALSE;
VO_Ventilation_Subsystem_Degraded := FALSE;
L_Policy_Normal := (VI_System_Mode = E_System_Operating_Mode.MODE_NORMAL);
L_Policy_Safe_Stop := (VI_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP);
L_Policy_Degraded := (VI_System_Mode = E_System_Operating_Mode.MODE_DEGRADED);
L_Policy_Freeze_Protection := (VI_System_Mode = E_System_Operating_Mode.MODE_FREEZE_PROTECTION);

IF NOT VI_IsActivePLC THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
        VO_Supply_Fans[L_i] := 0;
        IF L_i <= GVL_CONSTANTS.C_MAX_SUPPLY_TEMPS THEN
            VO_Heater_Power[L_i] := 0.0;
        END_IF;
    END_FOR;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
        VO_Exhaust_Fans[L_i] := 0;
    END_FOR;
    VO_Status_Msg := 'ВЕНТИЛЯЦИЯ: РЕЗЕРВНЫЙ ПЛК';
    RETURN;
END_IF;

// Проверка связи с модулями ввода-вывода
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MODULES DO
    IF NOT VI_IO_Modules_Online[L_i] THEN
        VO_Ventilation_IO_Fault := TRUE;
        // Переход в безопасное состояние при потере связи (отключение вентиляции)
        FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
            VO_Supply_Fans[L_j] := 0;
        END_FOR;
        FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
            VO_Exhaust_Fans[L_j] := 0;
        END_FOR;
        FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
            VO_Heater_Power[L_j] := 0.0;
        END_FOR;
        VO_Status_Msg := 'ОШИБКА: Потеря связи с модулями ввода-вывода';
        RETURN;
    END_IF;
END_FOR;

// =========================
// SYSTEM MODE OVERRIDE
// =========================
// VENT_POLICY_ROUTING_PHASE3_V2
IF L_Policy_Safe_Stop THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
        VO_Supply_Fans[L_i] := 0;
    END_FOR;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
        VO_Exhaust_Fans[L_i] := 0;
    END_FOR;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
        VO_Heater_Power[L_i] := 0.0;
    END_FOR;
    VO_Status_Msg := 'ВЕНТИЛЯЦИЯ: ОСТАНОВЛЕНА POLICY SAFE_STOP';
    RETURN;
END_IF;

IF L_Policy_Degraded THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
        VO_Supply_Fans[L_i] := 0;
    END_FOR;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
        VO_Heater_Power[L_i] := 0.0;
    END_FOR;
    VO_Ventilation_Subsystem_Degraded := TRUE;
    VO_Status_Msg := 'ВЕНТИЛЯЦИЯ: DEGRADED POLICY';
END_IF;

IF L_Policy_Freeze_Protection THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
        VO_Supply_Fans[L_i] := 0;
    END_FOR;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
        VO_Exhaust_Fans[L_i] := 0;
    END_FOR;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
        VO_Heater_Power[L_i] := 0.0;
    END_FOR;
    VO_Status_Msg := 'ВЕНТИЛЯЦИЯ: FREEZE_PROTECTION POLICY (stop)';
    RETURN;
END_IF;

// MODE_FREEZE_PROTECTION пока оставляем на текущей штатной логике

// 1. Определение базовой скорости и целевой температуры по сценарию (ТЗ 7.1)
CASE VI_Current_Scenario OF
    E_SCENARIO_TYPE.SCENARIO_AWAY:
        L_Base_Speed := VI_Config.Scenario_Modes[3].Base_Fan_Speed;
        L_Target_Temp := VI_Config.Scenario_Modes[3].Target_Temp;
    E_SCENARIO_TYPE.SCENARIO_SLEEP:
        L_Base_Speed := VI_Config.Scenario_Modes[2].Base_Fan_Speed;
        L_Target_Temp := VI_Config.Scenario_Modes[2].Target_Temp;
    ELSE // PRESENCE, MORNING, EVENING
        L_Base_Speed := VI_Config.Scenario_Modes[1].Base_Fan_Speed;
        L_Target_Temp := VI_Config.Scenario_Modes[1].Target_Temp;
END_CASE;

// 2. Логика управления приточными установками (П-1, П-2, П-3)
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
    // ПИД-регулирование мощности электрического калорифера
    IF L_i <= GVL_CONSTANTS.C_MAX_SUPPLY_TEMPS THEN
        L_PID_Heaters[L_i](
            VI_SetPoint := L_Target_Temp,
            VI_ProcessValue := VI_Supply_Temps[L_i], // Используем датчик температуры после калорифера
            VI_Kp := 4.0, VI_Tn := 120.0, VI_Tv := 0.0,
            VI_Y_Min := 0.0, VI_Y_Max := 100.0, VI_Cycle_Time_S := 1.0,
            VO_Output => VO_Heater_Power[L_i]
        );
    END_IF;

    // Определение скорости приточного вентилятора
    VO_Supply_Fans[L_i] := L_Base_Speed;

    // Обработка действий от Rule Engine
    FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_RULES DO
        IF VI_Rule_Actions[L_j].Active AND VI_Rule_Actions[L_j].Target_ID = L_i THEN
            IF VI_Rule_Actions[L_j].Action_Type = E_Rule_Action_Type.ACTION_SET_VENTILATION THEN
                VO_Supply_Fans[L_i] := REAL_TO_BYTE(VI_Rule_Actions[L_j].Value);
            END_IF;
        END_IF;
    END_FOR;

    // Requests are operational requests and must not be reported as subsystem degradation.
END_FOR;

// 3. Логика управления вытяжными установками (В-1 .. В-5)
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
    VO_Exhaust_Fans[L_i] := L_Base_Speed;

    // ТЗ 4.0: Логика вытяжки в санузлах
    FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_WET_ZONES DO
        IF VI_Config.wet_zone_to_exhaust_map[L_j] = L_i THEN
            // Включение по свету, выключение с задержкой 5 минут (используем TOF)
            L_Wet_Zone_Timers[L_j](IN := VI_Wet_Zone_Active[L_j], PT := T#5m, VI_System_Time_MS := VI_System_Time_MS);
            IF VI_Wet_Zone_Active[L_j] THEN
                VO_Exhaust_Fans[L_i] := 80; // Повышенная скорость при присутствии
            ELSIF L_Wet_Zone_Timers[L_j].Q THEN
                VO_Exhaust_Fans[L_i] := 50; // Скорость выбега (пока таймер TOF активен)
            END_IF;
        END_IF;
    END_FOR;

    // Requests are operational requests and must not be reported as subsystem degradation.
END_FOR;








// ========================================
// VENT_FINAL_CLAMP
// ========================================
IF L_Policy_Degraded THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
        VO_Exhaust_Fans[L_i] := MIN(VO_Exhaust_Fans[L_i], VI_Config.Degraded_Exhaust_Limit);
    END_FOR;
END_IF;

// 4. Формирование статусного сообщения
IF L_Policy_Safe_Stop THEN
    VO_Status_Msg := 'ВЕНТИЛЯЦИЯ: ОСТАНОВЛЕНА POLICY SAFE_STOP';
ELSIF L_Policy_Freeze_Protection THEN
    VO_Status_Msg := 'ВЕНТИЛЯЦИЯ: FREEZE_PROTECTION POLICY (stop)';
ELSIF L_Policy_Degraded THEN
    VO_Status_Msg := 'ВЕНТИЛЯЦИЯ: DEGRADED POLICY';
ELSE
    VO_Status_Msg := 'Вентиляция работает в штатном режиме';
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_Ventilation_System_Manager <<<

// 0. Сброс статистики
IF VI_Reset_Stats THEN
    VIO_Health_Data.Starts_Count := 0;
    VIO_Health_Data.Sample_Count := 0;
    VIO_Health_Data.Current_Sum := 0.0;
    VIO_Health_Data.Avg_Start_Current := 0.0;
    VIO_Health_Data.Health_Score := 100;
    VIO_Health_Data.Maintenance_Required := FALSE;
    VIO_Health_Data.Warning_Message := '';
    VIO_Health_Data.Last_Start_Current := 0.0;
    VIO_Health_Data.Total_Runtime_Hours := 0;
    L_Accumulated_MS := 0;
END_IF;

// 1. Счётчик пусков и замер пускового тока
IF VI_Is_Running AND NOT L_Prev_Running THEN
    VIO_Health_Data.Starts_Count := VIO_Health_Data.Starts_Count + 1;
    VIO_Health_Data.Last_Start_Current := VI_Current_Value;
    L_Start_Time := VI_System_Time_MS;
    L_Last_Calc_Time := VI_System_Time_MS;

    // Обновление среднего пускового тока
    VIO_Health_Data.Sample_Count := VIO_Health_Data.Sample_Count + 1;
    VIO_Health_Data.Current_Sum := VIO_Health_Data.Current_Sum + VI_Current_Value;
    VIO_Health_Data.Avg_Start_Current := VIO_Health_Data.Current_Sum / UDINT_TO_REAL(VIO_Health_Data.Sample_Count);

    // 2. Анализ отклонения пускового тока (п. 12.1 ТЗ)
    IF VI_Current_Value > (VI_Nominal_Value * 1.5) THEN
        VIO_Health_Data.Health_Score := TO_BYTE(LIMIT(0, TO_INT(VIO_Health_Data.Health_Score) - 5, 100));
    ELSIF VI_Current_Value > (VI_Nominal_Value * 1.2) THEN
        VIO_Health_Data.Health_Score := TO_BYTE(LIMIT(0, TO_INT(VIO_Health_Data.Health_Score) - 1, 100));
    ELSIF VI_Current_Value < (VI_Nominal_Value * 0.5) THEN
        VIO_Health_Data.Health_Score := TO_BYTE(LIMIT(0, TO_INT(VIO_Health_Data.Health_Score) - 2, 100));
    END_IF;
END_IF;

// 3. Анализ рабочего тока и наработки
IF VI_Is_Running THEN
    L_Elapsed_MS := (VI_System_Time_MS - L_Last_Calc_Time);
    L_Accumulated_MS := L_Accumulated_MS + L_Elapsed_MS;
    L_Last_Calc_Time := VI_System_Time_MS;

    // Обновляем наработку каждый час (3600000 мс)
    IF L_Accumulated_MS >= 3600000 THEN
        VIO_Health_Data.Total_Runtime_Hours := VIO_Health_Data.Total_Runtime_Hours + 1;
        L_Accumulated_MS := L_Accumulated_MS - 3600000;

        // Естественный износ: -1% здоровья каждые 1000 часов
        IF (VIO_Health_Data.Total_Runtime_Hours MOD 1000) = 0 THEN
            VIO_Health_Data.Health_Score := TO_BYTE(LIMIT(0, TO_INT(VIO_Health_Data.Health_Score) - 1, 100));
        END_IF;

        // Анализ рабочего тока (после пускового режима)
        IF (VI_System_Time_MS - L_Start_Time) > 10000 THEN // 10 секунд после пуска
            IF VI_Current_Value > (VI_Nominal_Value * 1.1) THEN
                // Повышенный рабочий ток - ускоренный износ (-1% в час)
                VIO_Health_Data.Health_Score := TO_BYTE(LIMIT(0, TO_INT(VIO_Health_Data.Health_Score) - 1, 100));
            END_IF;
        END_IF;
    END_IF;
END_IF;

// 4. Генерация предупреждения
IF VIO_Health_Data.Health_Score < 20 THEN
    VIO_Health_Data.Maintenance_Required := TRUE;
    VIO_Health_Data.Warning_Message := 'Критический износ: проверьте механику';
ELSIF VIO_Health_Data.Health_Score < 60 THEN
    VIO_Health_Data.Maintenance_Required := FALSE;
    VIO_Health_Data.Warning_Message := 'Предупреждение: повышенное трение';
ELSE
    VIO_Health_Data.Maintenance_Required := FALSE;
    VIO_Health_Data.Warning_Message := 'В норме';
END_IF;

L_Prev_Running := VI_Is_Running;

// read real time
L_Real_Now := GVL_STATUS.G_System_Time_MS;

// wrap-safe delta (real time base)
IF L_Real_Now >= GVL_TIME_SERVICE.G_Last_Now_MS THEN
    L_Elapsed := L_Real_Now - GVL_TIME_SERVICE.G_Last_Now_MS;
    GVL_TIME_SERVICE.G_Wrap_Detected := FALSE;
ELSE
    L_Elapsed := (16#FFFFFFFF - GVL_TIME_SERVICE.G_Last_Now_MS) + L_Real_Now + 1;
    GVL_TIME_SERVICE.G_Wrap_Detected := TRUE;
END_IF;

GVL_TIME_SERVICE.G_Last_Now_MS := L_Real_Now;

// --- SIMULATION MODE ---
IF GVL_TIME_SERVICE.G_Sim_Enabled THEN

    IF NOT GVL_TIME_SERVICE.G_Sim_Frozen THEN
        L_Scaled_Delta := REAL_TO_UDINT(TO_REAL(L_Elapsed) * GVL_TIME_SERVICE.G_Sim_Time_Scale);

        GVL_TIME_SERVICE.G_Sim_Now_MS := GVL_TIME_SERVICE.G_Sim_Now_MS + L_Scaled_Delta;

        GVL_TIME_SERVICE.G_Sim_Time_Of_Day_MS := GVL_TIME_SERVICE.G_Sim_Time_Of_Day_MS + L_Scaled_Delta;

        IF GVL_TIME_SERVICE.G_Sim_Time_Of_Day_MS >= 86400000 THEN
            GVL_TIME_SERVICE.G_Sim_Time_Of_Day_MS := GVL_TIME_SERVICE.G_Sim_Time_Of_Day_MS MOD 86400000;
            GVL_TIME_SERVICE.G_Sim_Day_Of_Week := GVL_TIME_SERVICE.G_Sim_Day_Of_Week + 1;
            IF GVL_TIME_SERVICE.G_Sim_Day_Of_Week > 7 THEN
                GVL_TIME_SERVICE.G_Sim_Day_Of_Week := 1;
            END_IF;
        END_IF;
    END_IF;

    GVL_TIME_SERVICE.G_Now_MS := GVL_TIME_SERVICE.G_Sim_Now_MS;
    GVL_TIME_SERVICE.G_Time_Of_Day_MS := GVL_TIME_SERVICE.G_Sim_Time_Of_Day_MS;
    GVL_TIME_SERVICE.G_Day_Of_Week := GVL_TIME_SERVICE.G_Sim_Day_Of_Week;

ELSE
    GVL_TIME_SERVICE.G_Now_MS := L_Real_Now;
    GVL_TIME_SERVICE.G_Time_Of_Day_MS := GVL_STATUS.G_Time_Of_Day_MS;
    GVL_TIME_SERVICE.G_Day_Of_Week := TO_INT(GVL_STATUS.G_Current_Day);
END_IF;

// TOD unified
GVL_TIME_SERVICE.G_Current_TOD := UDINT_TO_TOD(GVL_TIME_SERVICE.G_Time_Of_Day_MS);

GVL_TIME_SERVICE.G_Delta_MS := L_Elapsed;

IF VI_Value >= VI_Min_Valid AND VI_Value <= VI_Max_Valid THEN
    VO_Error := FALSE;
    VO_Value := VI_Value;
    L_Last_Good_Value := VI_Value;
    L_First_Valid := TRUE;
ELSE
    VO_Error := TRUE;
    IF VI_Fallback_Mode = 1 OR NOT L_First_Valid THEN
        VO_Value := VI_Default_Value;
    ELSE
        VO_Value := L_Last_Good_Value;
    END_IF;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_Analog_Validator <<<

// Вычисление времени цикла
IF L_Last_Time = 0 THEN
    L_Last_Time := VI_System_Time_MS;
    L_Cycle_Time_S := 1.0;
ELSE
    L_Cycle_Time_S := UDINT_TO_REAL((SEL(VI_System_Time_MS >= L_Last_Time, VI_System_Time_MS - L_Last_Time, (4294967295 - L_Last_Time) + VI_System_Time_MS + 1))) / 1000.0;
    L_Last_Time := VI_System_Time_MS;
END_IF;
IF L_Cycle_Time_S <= 0.0 THEN L_Cycle_Time_S := 0.01; END_IF;

// 1. Определение активного тарифа
IF VI_Tariff.Enabled THEN
    IF VI_Tariff.Night_Start_Hour > VI_Tariff.Night_End_Hour THEN
        // Переход через полночь (например, 23:00 - 07:00)
        L_Is_Night := (VI_Current_Hour >= VI_Tariff.Night_Start_Hour) OR (VI_Current_Hour < VI_Tariff.Night_End_Hour);
    ELSE
        // В пределах одного дня
        L_Is_Night := (VI_Current_Hour >= VI_Tariff.Night_Start_Hour) AND (VI_Current_Hour < VI_Tariff.Night_End_Hour);
    END_IF;
ELSE
    L_Is_Night := FALSE;
END_IF;

// 2. Расчет эффективной уставки
VO_Effective_Setpoint := VI_Config.design_temp;
IF L_Is_Night THEN
    VO_Effective_Setpoint := VO_Effective_Setpoint + VI_Tariff.Boost_Delta;
END_IF;

// 3. ПИД-регулирование
L_PID(
    VI_SetPoint := VO_Effective_Setpoint,
    VI_ProcessValue := VI_Current_Temp,
    VI_Kp := VI_Config.pid_kp,
    VI_Tn := 300.0,
    VI_Tv := 0.0,
    VI_Y_Min := 0.0,
    VI_Y_Max := 100.0,
    VI_Cycle_Time_S := L_Cycle_Time_S,
    VO_Output => VO_Valve_Pos
);

// 4. ШИМ-модуляция для термоэлектрического привода
IF VI_Config.pwm_period_s > 0 THEN
    L_PWM_Period_MS := TO_UDINT(VI_Config.pwm_period_s) * 1000;
ELSE
    L_PWM_Period_MS := 600000; // 10 минут
END_IF;

L_Current_Phase_MS := (SEL(VI_System_Time_MS >= L_PWM_Start_Time, VI_System_Time_MS - L_PWM_Start_Time, (4294967295 - L_PWM_Start_Time) + VI_System_Time_MS + 1));
IF L_Current_Phase_MS >= L_PWM_Period_MS THEN
    L_PWM_Start_Time := VI_System_Time_MS - (L_Current_Phase_MS - L_PWM_Period_MS); // Сохраняем остаток для точности
    L_Current_Phase_MS := (SEL(VI_System_Time_MS >= L_PWM_Start_Time, VI_System_Time_MS - L_PWM_Start_Time, (4294967295 - L_PWM_Start_Time) + VI_System_Time_MS + 1));
END_IF;

L_PWM_Duty_MS := TO_UDINT((VO_Valve_Pos / 100.0) * TO_REAL(L_PWM_Period_MS));

IF VI_IsActivePLC THEN
    VO_Pump_Run := (VO_Valve_Pos > 5.0);

    IF VO_Valve_Pos >= 100.0 THEN
        VO_Valve_Bool := TRUE;
    ELSIF VO_Valve_Pos <= 0.0 THEN
        VO_Valve_Bool := FALSE;
    ELSE
        VO_Valve_Bool := (L_Current_Phase_MS <= L_PWM_Duty_MS);
    END_IF;
ELSE
    VO_Pump_Run := FALSE;
    VO_Valve_Bool := FALSE;
END_IF;

// ==============================================================================
// Heating boiler control helper
//
// Internal refactoring helper for FB_Heating_System_Manager.
// Owns demand aggregation, boiler cascade request, OpenTherm transport,
// status normalization, degradation projection, and boiler resource accounting.
// ==============================================================================



VO_Any_Subsystem_Degraded := FALSE;
VO_Demand_Power := 0.0;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    IF VI_Manifold_Pumps[L_i] THEN
        VO_Demand_Power := VO_Demand_Power + VI_Manifold_Valves[L_i];
    END_IF;
END_FOR;

IF VI_Freeze_Mode_Active AND VO_Demand_Power < 20.0 THEN
    VO_Demand_Power := 20.0;
END_IF;

IF VI_Policy_Degraded THEN
    IF VO_Demand_Power > 60.0 THEN
        VO_Demand_Power := 60.0;
    END_IF;
END_IF;

fbBoilerCascade(
    VI_Enable := VI_IsActivePLC AND ((VO_Demand_Power > GVL_CONSTANTS.C_BOILER_CASCADE_MIN_DEMAND) OR VI_Freeze_Mode_Active),
    VI_System_Time_MS := VI_System_Time_MS,
    VI_Boiler_Stop := FALSE,
    VI_DHW_Heating_Demand := VI_DHW_Heating_Demand,
    VI_DHW_Target_Temp := VI_DHW_Target_Temp,
    VI_Target_Supply_Temp := VI_Target_Supply_Temp,
    VI_Demand_Power := VO_Demand_Power,
    VI_Boiler_Flame_Status := VI_Boiler_Flame_Status,
    VI_Boiler_Error_Status := VI_Boiler_Error_Status,
    VI_Boiler_OT_Online := VI_Boiler_OT_Online,
    VI_Boiler_Modulation := VI_Boiler_Modulation,
    VO_Boiler_Enable => L_Boiler_Request_Enable,
    VO_Boiler_Setpoint => L_Boiler_Request_Setpoint,
    VO_Lead_Boiler => VO_Lead_Boiler
);

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    IF NOT VI_Boiler_OT_Online[L_i] OR VI_Boiler_Error_Status[L_i] THEN
        L_Boiler_Request_Enable[L_i] := FALSE;
        L_Boiler_Request_Setpoint[L_i] := 0.0;
    END_IF;
END_FOR;

fbBoilerOpenTherm(
    VI_Enable := L_Boiler_Request_Enable,
    VI_Setpoint := L_Boiler_Request_Setpoint,
    VI_OT_Online := VI_Boiler_OT_Online,
    VI_OT_Error := VI_Boiler_Error_Status,
    VO_OT_Enable => VO_Boiler_OT_Enable,
    VO_OT_Setpoint => VO_Boiler_OT_Setpoint,
    VO_OT_Command_Valid => L_Boiler_OT_Command_Valid
);

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    VO_Boiler_Status[L_i].Active := L_Boiler_Request_Enable[L_i];
    VO_Boiler_Status[L_i].Warning := FALSE;
    VO_Boiler_Status[L_i].Error := FALSE;

    IF NOT VI_Boiler_OT_Online[L_i] THEN
        VO_Boiler_Status[L_i].Error := TRUE;
        VO_Boiler_Status[L_i].Error_ID := TO_WORD(GVL_CONFIG.ERR_BOILER_OFFLINE);
        VO_Any_Subsystem_Degraded := TRUE;
    ELSIF VI_Boiler_Error_Status[L_i] THEN
        VO_Boiler_Status[L_i].Error := TRUE;
        VO_Boiler_Status[L_i].Error_ID := TO_WORD(GVL_CONFIG.ERR_BOILER_GENERAL_FAULT);
        VO_Any_Subsystem_Degraded := TRUE;
    ELSIF L_Boiler_Request_Enable[L_i] AND NOT VI_Boiler_Flame_Status[L_i] THEN
        VO_Boiler_Status[L_i].Warning := TRUE;
        VO_Boiler_Status[L_i].Error_ID := TO_WORD(GVL_CONFIG.ERR_BOILER_NO_FLAME);
        VO_Any_Subsystem_Degraded := TRUE;
    ELSE
        VO_Boiler_Status[L_i].Error_ID := 0;
    END_IF;
END_FOR;

IF NOT L_Scan_Time_Init THEN
    L_Last_Scan_Time := VI_System_Time_MS;
    L_Scan_Time_Init := TRUE;
END_IF;

L_Delta_MS := (SEL(VI_System_Time_MS >= L_Last_Scan_Time, VI_System_Time_MS - L_Last_Scan_Time, (4294967295 - L_Last_Scan_Time) + VI_System_Time_MS + 1));
IF L_Delta_MS > 1000 THEN
    L_Delta_MS := 1000;
END_IF;

L_Last_Scan_Time := VI_System_Time_MS;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    VO_Boiler_Status[L_i].Work_Seconds := GVL_Retain.G_Boiler_Work_Seconds[L_i];

    IF VI_Boiler_Flame_Status[L_i] THEN
        GVL_Retain.G_Boiler_Accumulated_MS[L_i] := GVL_Retain.G_Boiler_Accumulated_MS[L_i] + L_Delta_MS;
        IF GVL_Retain.G_Boiler_Accumulated_MS[L_i] >= GVL_CONSTANTS.C_MS_IN_SECOND THEN
            GVL_Retain.G_Boiler_Work_Seconds[L_i] := GVL_Retain.G_Boiler_Work_Seconds[L_i] + (GVL_Retain.G_Boiler_Accumulated_MS[L_i] / 1000);
            GVL_Retain.G_Boiler_Accumulated_MS[L_i] := GVL_Retain.G_Boiler_Accumulated_MS[L_i] MOD 1000;

            IF GVL_Retain.G_Boiler_Work_Seconds[L_i] > 4000000000 THEN
                GVL_Retain.G_Boiler_Work_Seconds[L_i] := 0;
            END_IF;

            VO_Boiler_Status[L_i].Work_Seconds := GVL_Retain.G_Boiler_Work_Seconds[L_i];
        END_IF;
    END_IF;

    VO_Boiler_Status[L_i].Work_Hours := TO_REAL(VO_Boiler_Status[L_i].Work_Seconds) / 3600.0;

    L_Boiler_Life[L_i](
        VI_Runtime_Hours := TO_UDINT(VO_Boiler_Status[L_i].Work_Hours),
        VI_Start_Count := 0,
        VI_Nominal_Life := 50000
    );
    VO_Boiler_Status[L_i].Resource_Percent := TO_REAL(L_Boiler_Life[L_i].VO_Remaining_Percent);
    VO_Boiler_Status[L_i].Running := VI_Boiler_Flame_Status[L_i];
END_FOR;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Boiler_Control <<<

IF NOT L_Initialized THEN
    L_Initialized := TRUE;
    L_Last_Call_MS := VI_System_Time_MS;
    VO_Cycle_DT_MS := 0;
    VO_Watchdog_Fault := FALSE;
    VO_Alive := TRUE;
    RETURN;
END_IF;

// Measure real time gap between successive calls
L_DT_MS := (SEL(VI_System_Time_MS >= L_Last_Call_MS, VI_System_Time_MS - L_Last_Call_MS, (4294967295 - L_Last_Call_MS) + VI_System_Time_MS + 1));
VO_Cycle_DT_MS := L_DT_MS;

// Fault if the task/cycle resumed after an abnormal pause
VO_Watchdog_Fault := (L_DT_MS > VI_Timeout_MS);
VO_Alive := NOT VO_Watchdog_Fault;

// Store current timestamp for next cycle
L_Last_Call_MS := VI_System_Time_MS;
// >>> BULK_SYNC_ANCHOR: FB_Watchdog <<<

FOR L_i := 1 TO 32 DO
    GVL_WATER_OUTPUT.DO_Water_Zone_Enable[L_i] := VI_Zone_Enable[L_i];
END_FOR;

GVL_WATER_OUTPUT.DO_Water_Valve_35_Close := VI_Valve_35_Close;
GVL_WATER_OUTPUT.DO_Water_Valve_36_Close := VI_Valve_36_Close;

// >>> BULK_SYNC_ANCHOR: FB_Water_Output_Projection <<<

// >>> SYNC_TEST_MARKER_001 <<<


IF NOT VI_IsActivePLC THEN RETURN; END_IF;


GVL_STATE.G_DHW_IO_Fault := FALSE;
GVL_STATE.G_DHW_Sensor_Fault := FALSE;
GVL_STATE.G_DHW_Subsystem_Degraded := FALSE;

IF VI_Emergency_Stop THEN
    VO_Heating_Pump := FALSE;
    VO_Circ_Pump := FALSE;
    VO_Status.Warning := FALSE;
    VO_Status.Error := TRUE;
    VO_Status.Error_ID := TO_WORD(GVL_CONFIG.ERR_DHW_IO_OFFLINE); // временно используем общий аварийный код до детализации safety-кодов
    VO_Status.Heating_Pump_On := FALSE;
    VO_Status.Circ_Pump_On := FALSE;
    RETURN;
END_IF;

// Фиксация текущего времени
L_Current_TOD := VI_Current_TOD;

// ========================================
// DHW POLICY LAYER
// ========================================
L_Policy_Safe_Stop := (VI_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP);
L_Policy_Freeze_Protection := (VI_System_Mode = E_System_Operating_Mode.MODE_FREEZE_PROTECTION);
L_Policy_Degraded := (VI_System_Mode = E_System_Operating_Mode.MODE_DEGRADED);
L_Target_Temp_Adjusted := VI_Config.Target_Temp;
IF L_Policy_Degraded THEN
    L_Target_Temp_Adjusted := VI_Config.Target_Temp - VI_Config.Degraded_Target_Delta;
END_IF;

// ========================================
// DHW POLICY OVERRIDE
// ========================================
IF L_Policy_Safe_Stop THEN
    VO_Heating_Pump := FALSE;
    VO_Circ_Pump := FALSE;
    RETURN;
END_IF;

IF L_Policy_Freeze_Protection THEN
    VO_Heating_Pump := FALSE;
    VO_Circ_Pump := FALSE;
    RETURN;
END_IF;

// Сброс признака выполнения термодезинфекции при смене дня.
IF L_Last_Legionella_Day <> VI_Current_Day_Of_Week THEN
    L_Legionella_Done_Today := FALSE;
    L_Last_Legionella_Day := VI_Current_Day_Of_Week;
END_IF;

// Базовый сброс незащёлкнутых статусных флагов на текущий цикл.
// Критические ошибки ниже могут зафиксироваться и завершить выполнение через RETURN.
VO_Status.Warning := FALSE;
VO_Status.Error := FALSE;
VO_Status.Error_ID := 0;

// Сброс ошибок
IF VI_Reset_Errors THEN
    L_Error_Latched := FALSE;
    L_Error_ID_Latched := 0;
END_IF;

// Проверка связи с модулями ввода-вывода
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MODULES DO
    IF NOT VI_IO_Modules_Online[L_i] THEN
        L_Error_Latched := TRUE;
        GVL_STATE.G_DHW_IO_Fault := TRUE;
        L_Error_ID_Latched := TO_WORD(GVL_CONFIG.ERR_DHW_IO_OFFLINE); // Потеря связи с модулями ввода-вывода
    END_IF;
END_FOR;

// 1. Обработка неисправностей датчиков и сервисных режимов (ТЗ 7.0)
fbTempValidator(
    VI_Value := VI_Temp,
    VI_Min_Valid := 0.0,
    VI_Max_Valid := 100.0,
    VI_Fallback_Mode := 0,
    VI_Default_Value := 55.0
);

fbPressValidator(
    VI_Value := VI_Pressure,
    VI_Min_Valid := 0.0,
    VI_Max_Valid := 10.0,
    VI_Fallback_Mode := 0
);

VO_Status.Temp := fbTempValidator.VO_Value;
VO_Status.Pressure := fbPressValidator.VO_Value;

// Сохраняем последнее достоверное значение температуры ГВС.
// Используется только для диагностики/сервиса, не для fallback-управления.
IF NOT fbTempValidator.VO_Error THEN
    L_Last_Good_Temp := VO_Status.Temp;
END_IF;

IF fbTempValidator.VO_Error THEN
    GVL_STATE.G_DHW_Sensor_Fault := TRUE;
    L_Error_Latched := TRUE;
    L_Error_ID_Latched := TO_WORD(GVL_CONFIG.ERR_DHW_TEMP_SENSOR_FAULT); // Критическая ошибка датчика температуры
ELSIF (VO_Status.Pressure < 1.0 OR VO_Status.Pressure > 4.0) AND NOT fbPressValidator.VO_Error THEN
    L_Error_Latched := TRUE;
    L_Error_ID_Latched := TO_WORD(GVL_CONFIG.ERR_DHW_PRESSURE_OUT_OF_RANGE); // Давление вне нормы
END_IF;

IF L_Error_Latched THEN
    // Критическая ошибка: переход в безопасное состояние с полной остановкой насосов.
    VO_Heating_Pump := FALSE;
    VO_Circ_Pump := FALSE;
    VO_Status.Warning := FALSE;
    VO_Status.Error := TRUE;
    VO_Status.Error_ID := L_Error_ID_Latched;
    VO_Status.Heating_Pump_On := FALSE;
    VO_Status.Circ_Pump_On := FALSE;
    RETURN;
END_IF;

// Ошибка датчика давления не останавливает ГВС,
// но переводит подсистему в режим предупреждения (degraded mode).
IF fbPressValidator.VO_Error THEN
    GVL_STATE.G_DHW_Sensor_Fault := TRUE;
    GVL_STATE.G_DHW_Subsystem_Degraded := TRUE;
    VO_Status.Warning := TRUE;
    VO_Status.Error := FALSE;
    VO_Status.Error_ID := TO_WORD(GVL_CONFIG.ERR_DHW_PRESSURE_SENSOR_FAULT);
END_IF;

// 2. Логика поддержания температуры воды в бойлере (Нагрев)
// На этом этапе FB уже выполняется только на активном ПЛК.

// Термическая дезинфекция (Легионелла)
IF VI_Config.Anti_Legionella_Enabled
   AND (VI_Current_Day_Of_Week = VI_Config.Anti_Legionella_Day)
   AND (L_Current_TOD >= TOD#02:00)
   AND (L_Current_TOD <= TOD#04:00)
   AND NOT L_Legionella_Done_Today THEN
    L_Legionella_Active := TRUE;
ELSE
    L_Legionella_Active := FALSE;
END_IF;

L_Legionella_Timer(IN := L_Legionella_Active AND VO_Status.Temp >= 70.0, PT := T#30m, VI_System_Time_MS := VI_System_Time_MS);
IF L_Legionella_Timer.Q THEN
    L_Legionella_Active := FALSE; // Дезинфекция завершена
    L_Legionella_Done_Today := TRUE; // Повторно в те же сутки не запускать
END_IF;

// Двухпозиционное регулирование с гистерезисом
IF L_Legionella_Active THEN
    IF VO_Status.Temp < 70.0 THEN
        VO_Heating_Pump := TRUE;
    ELSIF VO_Status.Temp > 72.0 THEN
        VO_Heating_Pump := FALSE;
    END_IF;
ELSE
    IF VO_Status.Temp < (L_Target_Temp_Adjusted - VI_Config.Hysteresis) THEN
        VO_Heating_Pump := TRUE;
    ELSIF VO_Status.Temp > (L_Target_Temp_Adjusted + VI_Config.Hysteresis) THEN
        VO_Heating_Pump := FALSE;
    END_IF;
END_IF;

// 3. Управление циркуляционным насосом ГВС по расписанию
// Рециркуляция обеспечивает мгновенное наличие горячей воды у потребителя
VO_Circ_Pump := SEL(VI_Config.Circulation_Schedule_Enabled AND NOT (VI_Config.Night_Mode_Enabled AND (L_Current_TOD < VI_Config.Circulation_Start OR L_Current_TOD > VI_Config.Circulation_End)), FALSE, TRUE);

// Формирование статусных данных для визуализации.
// К этому моменту статус уже консистентен:
// - Error = критическая ошибка с остановкой ГВС
// - Warning = деградация без остановки
VO_Status.Heating_Pump_On := VO_Heating_Pump;
VO_Status.Circ_Pump_On := VO_Circ_Pump;

// >>> BULK_SYNC_ANCHOR: FB_DHW_Manager <<<

IF NOT GVL_BEHAVIOR_ADAPT.G_Adapt_Enabled THEN RETURN; END_IF;

// GLOBAL STATS
L_Stats := GVL_BEHAVIOR_ADAPT.G_Scenario_Stats[iScenario];
L_Stats.Activations := L_Stats.Activations + 1;

IF iSuccess THEN
    L_Stats.Success_Count := L_Stats.Success_Count + 1;
ELSE
    L_Stats.Failure_Count := L_Stats.Failure_Count + 1;
END_IF;

IF L_Stats.Activations > 0 THEN
    L_Stats.Success_Rate := REAL(L_Stats.Success_Count) / REAL(L_Stats.Activations);
END_IF;

// ZONE ADAPT WITH DECAY
IF (iScenario = REASON_SCENARIO_VENT_BOOST) AND (iZone >= 1) AND (iZone <= GVL_CONSTANTS.C_MAX_ZONES) THEN

    L_Zone := GVL_BEHAVIOR_ADAPT.G_VentBoost_Zone_Adapt[iZone];

    IF L_Zone.Zone_Weight = 0.0 THEN
        L_Zone.Zone_Weight := GVL_BEHAVIOR_ADAPT.G_Adapt_Default_Zone_Weight;
    END_IF;

    // DECAY
    L_Decay := GVL_BEHAVIOR_ADAPT.G_Decay_Factor;
    L_Zone.Zone_Weight := L_Zone.Zone_Weight * L_Decay;
    L_Zone.Confidence := L_Zone.Confidence * L_Decay;

    // STATS
    L_Zone.Activations := L_Zone.Activations + 1;

    IF iSuccess THEN
        L_Zone.Success_Count := L_Zone.Success_Count + 1;
    ELSE
        L_Zone.Failure_Count := L_Zone.Failure_Count + 1;
    END_IF;

    IF L_Zone.Activations > 0 THEN
        L_Zone.Success_Rate := REAL(L_Zone.Success_Count) / REAL(L_Zone.Activations);
    END_IF;

    // CONFIDENCE LEARNING
    IF iConfidence >= GVL_BEHAVIOR_ADAPT.G_Adapt_Min_Confidence THEN
        L_Zone.Confidence := L_Zone.Confidence +
            (iConfidence - L_Zone.Confidence) * GVL_BEHAVIOR_ADAPT.G_Confidence_Learning_Rate;
    END_IF;

    // UPDATE
    IF (L_Zone.Activations MOD GVL_BEHAVIOR_ADAPT.G_Adapt_Update_Threshold) = 0 THEN

        L_Adjustment :=
            (L_Zone.Success_Rate - 0.5)
            * GVL_BEHAVIOR_ADAPT.G_Adapt_Learning_Rate
            * L_Zone.Confidence;

        L_Zone.Zone_Weight := LIMIT(0.5, L_Zone.Zone_Weight + L_Adjustment, 2.0);

    END_IF;

    L_Zone.Last_Update_MS := GVL_TIME_SERVICE.G_Now_MS;

    GVL_BEHAVIOR_ADAPT.G_VentBoost_Zone_Adapt[iZone] := L_Zone;

END_IF;

GVL_BEHAVIOR_ADAPT.G_Scenario_Stats[iScenario] := L_Stats;

// ==============================================================================
// System intent publisher helper
//
// Internal helper for PRG_System.
// Owns publication of system-mode gates into GVL_INTENT_SYSTEM.
// ==============================================================================



GVL_INTENT_SYSTEM.I_Source_Valid := TRUE;
GVL_INTENT_SYSTEM.I_Last_Update_MS := VI_System_Time_MS;
GVL_INTENT_SYSTEM.I_Mode_Safe_Stop_Active := (GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP);
GVL_INTENT_SYSTEM.I_Mode_Degraded_Active := (GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_DEGRADED);
GVL_INTENT_SYSTEM.I_Mode_Freeze_Protection_Active := (GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_FREEZE_PROTECTION);
GVL_INTENT_SYSTEM.I_Operator_Scenario_Block := (GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP);
GVL_INTENT_SYSTEM.I_Lighting_Overrides_Block := (GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP);
GVL_INTENT_SYSTEM.I_Blinds_Overrides_Block := (GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP);
GVL_INTENT_SYSTEM.I_Socket_Overrides_Block := (GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP);
GVL_INTENT_SYSTEM.I_Gateway_Writes_Allowed := VI_Gateway_Writes_Allowed;
GVL_INTENT_SYSTEM.I_Scenario_Request_Allowed := (GVL_STATE.G_System_Mode <> E_System_Operating_Mode.MODE_SAFE_STOP);

// >>> BULK_SYNC_ANCHOR: FB_System_Intent_Publisher <<<

VO_Heating_Degraded := FALSE;

// STEP 1: Allowed
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    VO_Manifold_Allowed[L_i] := TRUE;

    IF NOT VI_Manifold_Pump_In_Service[L_i] THEN
        VO_Manifold_Allowed[L_i] := FALSE;
    END_IF;

    IF VI_Manifold_Pressure_Fault[L_i] THEN
        VO_Manifold_Allowed[L_i] := FALSE;
    END_IF;

    IF VI_Manifold_Current_Fault[L_i] THEN
        VO_Manifold_Allowed[L_i] := FALSE;
    END_IF;

    IF NOT VO_Manifold_Allowed[L_i] THEN
        VO_Heating_Degraded := TRUE;
    END_IF;
END_FOR;

// STEP 2: find max priority
L_MaxPriority := 0;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    IF VI_Manifold_Priority[L_i] > L_MaxPriority THEN
        L_MaxPriority := VI_Manifold_Priority[L_i];
    END_IF;
END_FOR;

// STEP 3: allocation by priority + budget
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    VO_Manifold_Enabled[L_i] := FALSE;
END_FOR;

L_Used := 0.0;

FOR L_CurrentPriority := L_MaxPriority TO 1 BY -1 DO

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO

        IF (VI_Manifold_Priority[L_i] = L_CurrentPriority) AND VO_Manifold_Allowed[L_i] THEN

            IF (L_Used + VI_Manifold_Thermal_Weight[L_i]) <= VI_Max_Thermal_Budget THEN
                VO_Manifold_Enabled[L_i] := TRUE;
                L_Used := L_Used + VI_Manifold_Thermal_Weight[L_i];
            END_IF;

        END_IF;

    END_FOR;

END_FOR;

// Pure execution core: calls heating and DHW managers. // Does not apply command/allocation overrides.
fbHeatingManager( VI_System_Time_MS := VI_System_Time_MS, VI_IsActivePLC := VI_IsActivePLC, VI_Outdoor_Temp := VI_Outdoor_Temp, VI_Floor_Temps := VI_Floor_Temps, VI_Room_Temps := VI_Room_Temps, VI_Config := VI_Config, VI_Zone_Configs := VI_Zone_Configs, VI_Tariff := VI_Tariff, VI_Current_Hour := TO_UINT(VI_Time_Of_Day_MS / GVL_CONSTANTS.C_MS_IN_HOUR), VI_Manifold_Pressures := VI_Manifold_Pressures, VI_Manifold_Currents := VI_Manifold_Currents, VI_Manifold_Temps_Supply := VI_Manifold_Temps_Supply, VI_Manifold_Temps_Return := VI_Manifold_Temps_Return, VI_Boiler_Flame_Status := VI_Boiler_Flame_Status, VI_Boiler_Error_Status := VI_Boiler_Error_Status, VI_Boiler_OT_Online := VI_Boiler_OT_Online, VI_Boiler_Modulation := VI_Boiler_Modulation, VI_Rule_Actions := VI_Rule_Actions, VI_IO_Modules_Online := VI_IO_Modules_Online, VI_DHW_Heating_Demand := VI_DHW_Heating_Demand, VI_DHW_Target_Temp := VI_DHW_Target_Temp, VI_System_Mode := VI_System_Mode, VI_Emergency_Stop := VI_Emergency_Stop, VI_Gas_Safety_Stop := VI_Gas_Safety_Stop, VI_Manifold_End_Switches := VI_Manifold_End_Switches, VI_Valve_Test_Config := VI_Valve_Test_Config, VO_Manifold_Valves => VIO_Manifold_Valves, VO_Manifold_Pumps => VIO_Manifold_Pumps, VO_Zone_Valves => VIO_Zone_Valves, VO_Boiler_OT_Enable => VIO_Boiler_OT_Enable, VO_Boiler_OT_Setpoint => VIO_Boiler_OT_Setpoint, VO_Backup_Circulation_Pump => VIO_Backup_Circulation_Pump, VO_Electric_Heater_Enable => VIO_Electric_Heater_Enable, VO_Freeze_Risk_Status => VIO_Freeze_Risk_Status, VO_Status => VIO_Manifold_Status, VO_Boiler_Status => VIO_Boiler_Status );
fbDHWManager( VI_System_Time_MS := VI_System_Time_MS, VI_Current_TOD := VI_Current_TOD, VI_IsActivePLC := VI_IsActivePLC, VI_Temp := VI_DHW_Temp, VI_Pressure := VI_DHW_Pressure, VI_Config := VI_DHW_Config, VI_Current_Day_Of_Week := VI_Current_Day_Of_Week, VI_IO_Modules_Online := VI_IO_Modules_Online, VI_Reset_Errors := VI_Reset_Errors, VI_Emergency_Stop := VI_Emergency_Stop, VI_System_Mode := VI_System_Mode, VO_Heating_Pump => VIO_DHW_Heating_Pump, VO_Circ_Pump => VIO_DHW_Circ_Pump, VO_Status => VIO_DHW_Status );
// >>> BULK_SYNC_ANCHOR: FB_Heating_Execution_Core <<<

IF VI_Trigger_Event THEN
    L_Snapshot_Buffer[L_Write_Idx] := VI_Current_State;
    L_Snapshot_Buffer[L_Write_Idx].timestamp_ms := VI_System_Time_MS;

    // NOTE:
    // ST_State_Snapshot no longer contains trigger_event_code in live project.
    // VI_Event_Code is reserved for future snapshot metadata extension.

    L_Write_Idx := (L_Write_Idx MOD GVL_CONSTANTS.C_MAX_STATE_SNAPSHOTS) + 1;
    VO_Snapshot_Saved := TRUE;
ELSE
    VO_Snapshot_Saved := FALSE;
END_IF;

// === DELTA TIME ===
IF VI_System_Time_MS >= L_Last_Time THEN
    L_Delta_MS := VI_System_Time_MS - L_Last_Time;
ELSE
    // overflow
    L_Delta_MS := (4294967295 - L_Last_Time) + VI_System_Time_MS + 1;
END_IF;

L_Last_Time := VI_System_Time_MS;

// === START COUNT ===
IF VI_Device_Active AND NOT L_Prev_State THEN
    VIO_Status.start_count := VIO_Status.start_count + 1;
END_IF;

L_Prev_State := VI_Device_Active;

// === RUNTIME ACCUMULATION ===
IF VI_Device_Active THEN
    L_Runtime_Accum_MS := L_Runtime_Accum_MS + L_Delta_MS;

    WHILE L_Runtime_Accum_MS >= 3600000 DO
        VIO_Status.runtime_hours := VIO_Status.runtime_hours + 1;
        L_Runtime_Accum_MS := L_Runtime_Accum_MS - 3600000;
    END_WHILE;
END_IF;

// === BASIC LIFETIME ESTIMATION ===
IF VI_Nominal_Hours > 0 THEN
    IF VIO_Status.runtime_hours >= VI_Nominal_Hours THEN
        VIO_Status.remaining_hours := 0;
        VIO_Status.remaining_percent := 0;
    ELSE
        VIO_Status.remaining_hours := VI_Nominal_Hours - VIO_Status.runtime_hours;
        L_Remaining_Percent_UDINT := (VIO_Status.remaining_hours * 100) / VI_Nominal_Hours;

        IF L_Remaining_Percent_UDINT > 100 THEN
            L_Remaining_Percent_UDINT := 100;
        END_IF;

        VIO_Status.remaining_percent := UDINT_TO_BYTE(L_Remaining_Percent_UDINT);
    END_IF;
ELSE
    VIO_Status.remaining_hours := 0;
    VIO_Status.remaining_percent := 0;
END_IF;

VIO_Status.maintenance_required := VIO_Status.remaining_percent <= GVL_Lifetime.G_Maintenance_Threshold_Percent;

// === BASIC FLAGS ===
VIO_Status.device_id := VI_Device_ID;
VIO_Status.last_calc_timestamp := VI_System_Time_MS;

// Initialize variables
H0 := 16#67452301;
H1 := 16#EFCDAB89;
H2 := 16#98BADCFE;
H3 := 16#10325476;
H4 := 16#C3D2E1F0;

// Pre-processing
FOR i := 0 TO Length - 1 DO
    PaddedData[i] := Data[i];
END_FOR;

// Append the bit '1' to the message
PaddedData[Length] := 16#80;

// Append 0 <= k < 512 bits '0', such that the resulting message length in bits
// is congruent to -64 ≡ 448 (mod 512)
PaddedLength := Length + 1;
WHILE (PaddedLength MOD 64) <> 56 DO
    PaddedData[PaddedLength] := 0;
    PaddedLength := PaddedLength + 1;
END_WHILE;

// Append length of message (before pre-processing), in bits, as 64-bit big-endian integer
// Since our message is small (max 127 bytes), we only need the lower 32 bits
Temp := TO_DWORD(Length * 8);
PaddedData[PaddedLength] := 0;
PaddedData[PaddedLength+1] := 0;
PaddedData[PaddedLength+2] := 0;
PaddedData[PaddedLength+3] := 0;
PaddedData[PaddedLength+4] := TO_BYTE(SHR(Temp, 24));
PaddedData[PaddedLength+5] := TO_BYTE(SHR(Temp, 16));
PaddedData[PaddedLength+6] := TO_BYTE(SHR(Temp, 8));
PaddedData[PaddedLength+7] := TO_BYTE(Temp);
PaddedLength := PaddedLength + 8;

NumBlocks := PaddedLength / 64;

// Process the message in successive 512-bit chunks
FOR i := 0 TO NumBlocks - 1 DO
    BlockOffset := i * 64;

    // Break chunk into sixteen 32-bit big-endian words w[i], 0 <= i <= 15
    FOR j := 0 TO 15 DO
        W[j] := SHL(TO_DWORD(PaddedData[BlockOffset + j*4]), 24) OR
                SHL(TO_DWORD(PaddedData[BlockOffset + j*4 + 1]), 16) OR
                SHL(TO_DWORD(PaddedData[BlockOffset + j*4 + 2]), 8) OR
                TO_DWORD(PaddedData[BlockOffset + j*4 + 3]);
    END_FOR;

    // Message schedule: extend the sixteen 32-bit words into eighty 32-bit words
    FOR j := 16 TO 79 DO
        Temp := W[j-3] XOR W[j-8] XOR W[j-14] XOR W[j-16];
        W[j] := SHL(Temp, 1) OR SHR(Temp, 31); // Left rotate by 1
    END_FOR;

    // Initialize hash value for this chunk
    A := H0;
    B := H1;
    C := H2;
    D := H3;
    E := H4;

    // Main loop
    FOR j := 0 TO 79 DO
        IF j <= 19 THEN
            F := (B AND C) OR ((NOT B) AND D);
            K := 16#5A827999;
        ELSIF j <= 39 THEN
            F := B XOR C XOR D;
            K := 16#6ED9EBA1;
        ELSIF j <= 59 THEN
            F := (B AND C) OR (B AND D) OR (C AND D);
            K := 16#8F1BBCDC;
        ELSE
            F := B XOR C XOR D;
            K := 16#CA62C1D6;
        END_IF;

        Temp := (SHL(A, 5) OR SHR(A, 27)) + F + E + K + W[j];
        E := D;
        D := C;
        C := SHL(B, 30) OR SHR(B, 2);
        B := A;
        A := Temp;
    END_FOR;

    // Add this chunk's hash to result so far
    H0 := H0 + A;
    H1 := H1 + B;
    H2 := H2 + C;
    H3 := H3 + D;
    H4 := H4 + E;
END_FOR;

// Produce the final hash value (big-endian)
Hash[0] := TO_BYTE(SHR(H0, 24)); Hash[1] := TO_BYTE(SHR(H0, 16)); Hash[2] := TO_BYTE(SHR(H0, 8)); Hash[3] := TO_BYTE(H0);
Hash[4] := TO_BYTE(SHR(H1, 24)); Hash[5] := TO_BYTE(SHR(H1, 16)); Hash[6] := TO_BYTE(SHR(H1, 8)); Hash[7] := TO_BYTE(H1);
Hash[8] := TO_BYTE(SHR(H2, 24)); Hash[9] := TO_BYTE(SHR(H2, 16)); Hash[10] := TO_BYTE(SHR(H2, 8)); Hash[11] := TO_BYTE(H2);
Hash[12] := TO_BYTE(SHR(H3, 24)); Hash[13] := TO_BYTE(SHR(H3, 16)); Hash[14] := TO_BYTE(SHR(H3, 8)); Hash[15] := TO_BYTE(H3);
Hash[16] := TO_BYTE(SHR(H4, 24)); Hash[17] := TO_BYTE(SHR(H4, 16)); Hash[18] := TO_BYTE(SHR(H4, 8)); Hash[19] := TO_BYTE(H4);

// Compatibility placeholder.
// Previous METHOD Calculate returned DWORD#0.
// Keep same behaviour without METHOD syntax for this CODESYS project format.
IF VI_Enable THEN
    VO_CRC := DWORD#0;
END_IF;

L_Away_Mode := (VI_Behavior_Mode = BEHAVIOR_AWAY);

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO

    // compute empty duration
    IF VI_Zone_Occupied[L_i] THEN
        VO_Zone_Empty_Duration_MS[L_i] := 0;
    ELSE
        VO_Zone_Empty_Duration_MS[L_i] := VI_System_Time_MS - VI_Zone_Last_Motion_TS[L_i];
    END_IF;

    // policy classification
    // Guest/preheat has priority even in AWAY mode.
    IF VI_Zone_Guest_Preheat[L_i] THEN
        VO_Zone_Policy_Class[L_i] := 3; // guest

    ELSIF VI_Zone_Occupied[L_i] THEN
        VO_Zone_Policy_Class[L_i] := 0; // comfort

    ELSIF VI_Zone_Permanent_Use[L_i] AND (NOT L_Away_Mode) THEN
        VO_Zone_Policy_Class[L_i] := 4; // permanent mild eco

    ELSIF VO_Zone_Empty_Duration_MS[L_i] >= L_Long_Threshold THEN
        VO_Zone_Policy_Class[L_i] := 2; // deep eco

    ELSE
        VO_Zone_Policy_Class[L_i] := 1; // mild eco
    END_IF;

    // observe-only target adjustment (no effect yet)
    CASE VO_Zone_Policy_Class[L_i] OF
        0: // comfort
            VO_Zone_Target_Adjustment[L_i] := 0.0;
            VO_Zone_Priority_Bias[L_i] := 1.0;

        1: // mild eco
            VO_Zone_Target_Adjustment[L_i] := -1.0;
            VO_Zone_Priority_Bias[L_i] := 0.8;

        2: // deep eco
            VO_Zone_Target_Adjustment[L_i] := -3.0;
            VO_Zone_Priority_Bias[L_i] := 0.5;

        3: // guest preheat
            VO_Zone_Target_Adjustment[L_i] := 0.0;
            VO_Zone_Priority_Bias[L_i] := 1.5;

        4: // permanent-use mild eco
            VO_Zone_Target_Adjustment[L_i] := -0.5;
            VO_Zone_Priority_Bias[L_i] := 0.9;

    END_CASE;

END_FOR;

// === BUILD STRUCT FROM STATE ===
// === NVRAM SNAPSHOT VIA STRUCT ADAPTER ===
VIO_PersistStruct.System_Mode := GVL_STATE.G_System_Mode;

VIO_PersistStruct.Safety_Gas_Latched := GVL_STATE.G_Safety_Gas_Latched;
VIO_PersistStruct.Safety_Smoke_Latched := GVL_STATE.G_Safety_Smoke_Latched;
VIO_PersistStruct.Safety_Leak_Latched := GVL_STATE.G_Safety_Leak_Latched;

VIO_PersistStruct.DHW_Heating_Pump := GVL_STATE.G_DHW_Heating_Pump;
VIO_PersistStruct.Valid := TRUE;

// mirror to legacy persistent variables
GVL_PERSISTENT.P_System_Mode := VIO_PersistStruct.System_Mode;

GVL_PERSISTENT.P_Safety_Gas_Latched := VIO_PersistStruct.Safety_Gas_Latched;
GVL_PERSISTENT.P_Safety_Smoke_Latched := VIO_PersistStruct.Safety_Smoke_Latched;
GVL_PERSISTENT.P_Safety_Leak_Latched := VIO_PersistStruct.Safety_Leak_Latched;

GVL_PERSISTENT.P_DHW_Heating_Active := VIO_PersistStruct.DHW_Heating_Pump;
GVL_PERSISTENT.P_Valid := VIO_PersistStruct.Valid;

IF NOT VI_IsActivePLC THEN RETURN; END_IF;

CASE L_State OF
    0: // Ожидание
        VO_Test_Active := FALSE;
        L_Need_Test := FALSE;

        // Поиск клапана, которому нужен тест (раз в неделю)
        FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
            IF VI_Config[L_i].enabled AND ((VI_System_Time_MS - L_Last_Test_Time[L_i]) > (VI_Config[L_i].test_interval_days * 86400000)) THEN
                L_Current_Valve := L_i;
                L_Need_Test := TRUE;
                EXIT;
            END_IF;
        END_FOR;

        IF L_Need_Test THEN
            L_State := 1;
            L_Test_Start_Time := VI_System_Time_MS;
            VO_Test_Active := TRUE;
            VO_Current_Valve := L_Current_Valve;
            VO_Valve_Cmd[L_Current_Valve] := TRUE; // Открываем
            VO_Status_Msg := CONCAT('ТЕСТ КЛАПАНА ', INT_TO_STRING(L_Current_Valve));
            VO_Test_Results[L_Current_Valve] := TRUE; // Сброс результата
        END_IF;

    1: // Тестирование (ожидание открытия)
        L_Elapsed_Time := (VI_System_Time_MS - L_Test_Start_Time);

        IF VI_Valve_End_Switches[L_Current_Valve] THEN
            // Концевик сработал до истечения таймаута
            // Проверка тока
            IF ABS(VI_Valve_Currents[L_Current_Valve] - VI_Config[L_Current_Valve].Nominal_Current) > (VI_Config[L_Current_Valve].Nominal_Current * 0.2) THEN
                VO_Test_Results[L_Current_Valve] := FALSE; // Ошибка по току
            END_IF;

            GVL_Retain.G_Valve_Test_Results[L_Current_Valve] := VO_Test_Results[L_Current_Valve];

            VO_Valve_Cmd[L_Current_Valve] := FALSE; // Закрываем
            L_Test_Start_Time := VI_System_Time_MS; // Перезапускаем таймер для проверки закрытия
            L_State := 2;
        ELSIF L_Elapsed_Time > TO_UDINT(VI_Config[L_Current_Valve].nominal_close_time_sec * 1000.0) THEN
            // Таймаут открытия (заклинивание)
            VO_Test_Results[L_Current_Valve] := FALSE; 
            GVL_Retain.G_Valve_Test_Results[L_Current_Valve] := FALSE;
            VO_Status_Msg := CONCAT('ОШИБКА: ЗАКЛИНИВАНИЕ КЛАПАНА ', INT_TO_STRING(L_Current_Valve));

            VO_Valve_Cmd[L_Current_Valve] := FALSE; // Закрываем
            L_Test_Start_Time := VI_System_Time_MS; // Перезапускаем таймер
            L_State := 2;
        END_IF;

    2: // Ожидание закрытия
        L_Elapsed_Time := (VI_System_Time_MS - L_Test_Start_Time);

        IF NOT VI_Valve_End_Switches[L_Current_Valve] THEN
            // Концевик разомкнулся (клапан закрыт)
            L_Last_Test_Time[L_Current_Valve] := VI_System_Time_MS;
            L_State := 0;
            IF VO_Test_Results[L_Current_Valve] THEN
                VO_Status_Msg := 'ТЕСТ ЗАВЕРШЕН УСПЕШНО';
            END_IF;
        ELSIF L_Elapsed_Time > TO_UDINT(VI_Config[L_Current_Valve].nominal_close_time_sec * 1000.0) THEN
            // Таймаут закрытия (заклинивание)
            VO_Test_Results[L_Current_Valve] := FALSE; 
            GVL_Retain.G_Valve_Test_Results[L_Current_Valve] := FALSE;
            VO_Status_Msg := CONCAT('ОШИБКА: НЕ ЗАКРЫЛСЯ КЛАПАН ', INT_TO_STRING(L_Current_Valve));

            L_Last_Test_Time[L_Current_Valve] := VI_System_Time_MS;
            L_State := 0;
        END_IF;
END_CASE;

IF NOT GVL_TRACE.G_Trace_Enabled THEN RETURN; END_IF;

L_Index := GVL_TRACE.G_Trace_Write_Index;

GVL_TRACE.G_Trace_Buffer[L_Index].Timestamp_MS := GVL_TIME_SERVICE.G_Now_MS;
GVL_TRACE.G_Trace_Buffer[L_Index].Layer := iLayer;
GVL_TRACE.G_Trace_Buffer[L_Index].Source := iSource;
GVL_TRACE.G_Trace_Buffer[L_Index].Reason_Code := iReason;
GVL_TRACE.G_Trace_Buffer[L_Index].Value_Bool := iValueBool;
GVL_TRACE.G_Trace_Buffer[L_Index].Value_Real := iValueReal;
GVL_TRACE.G_Trace_Buffer[L_Index].Text := iText;

L_Index := L_Index + 1;
IF L_Index > 200 THEN L_Index := 1; END_IF;

GVL_TRACE.G_Trace_Write_Index := L_Index;

IF NOT VI_IsActivePLC THEN RETURN; END_IF;

L_Any_Leak := FALSE;
L_Any_Warning := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO
    L_Sensor_Timers[L_i](
        IN := VI_Sensors[L_i],
        PT := TO_TIME(VI_Config.min_duration_ms + VI_Config.warning_duration_ms),
        VI_System_Time_MS := VI_System_Time_MS
    );

    IF L_Sensor_Timers[L_i].ET >= TO_TIME(VI_Config.min_duration_ms) THEN
        L_Any_Warning := TRUE;

        IF L_Sensor_Timers[L_i].Q THEN
            L_Any_Leak := TRUE;
        END_IF;
    END_IF;
END_FOR;

// Health signals
VO_Leak_Detected := L_Any_Leak;
VO_Leak_Warning_Level := L_Any_Warning;

// Status
IF L_Any_Leak THEN
    VO_Status_Msg := 'АВАРИЯ: ПРОТЕЧКА ВОДЫ.';
ELSIF L_Any_Warning THEN
    VO_Status_Msg := 'ПРЕДУПРЕЖДЕНИЕ: ОБНАРУЖЕНА ВОДА.';
ELSE
    VO_Status_Msg := 'Система контроля протечек в норме';
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_Water_Leakage_Manager <<<

// Convert ventilation manager BYTE outputs directly into IO-ready projection.
// PRG_Ventilation no longer needs to publish fan actuator values through GVL_STATE.

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
    GVL_VENT_OUTPUT.AO_Supply_Fans[L_i] := BYTE_TO_UINT(VI_Supply_Fans[L_i]) * 10;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
    GVL_VENT_OUTPUT.AO_Exhaust_Fans[L_i] := BYTE_TO_UINT(VI_Exhaust_Fans[L_i]) * 10;
END_FOR;

// >>> BULK_SYNC_ANCHOR: FB_Vent_Output_Projection <<<

IF NOT VI_Enable THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
        GVL_HEATING_POLICY.G_Zone_Schedule_Preheat_Active[L_i] := FALSE;
    END_FOR;
    RETURN;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
    L_Active := FALSE;
    L_Max_Boost := 0.0;

    FOR L_e := 1 TO 3 DO
        L_Event := GVL_HEATING_POLICY_CONFIG.G_Zone_Schedule[L_i, L_e];

        IF L_Event.Enabled THEN
            IF (L_Event.Weekday_Mask AND SHL(1, VI_Day_Of_Week - 1)) <> 0 THEN

                IF L_Event.Comfort_Time_MS >= VI_Time_Of_Day_MS THEN
                    L_Time_To_Comfort_MS := L_Event.Comfort_Time_MS - VI_Time_Of_Day_MS;
                ELSE
                    L_Time_To_Comfort_MS := (86400000 - VI_Time_Of_Day_MS) + L_Event.Comfort_Time_MS;
                END_IF;

                IF L_Event.Adaptive_Enabled THEN
                    IF GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] > L_Event.Adaptive_Max_Offset_MS THEN
                        GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] := L_Event.Adaptive_Max_Offset_MS;
                    END_IF;
                    L_Time_To_Comfort_MS := L_Time_To_Comfort_MS + GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e];
                END_IF;

                IF (GVL_HEATING_POLICY.G_Zone_Time_To_Heat_MS[L_i] >= L_Time_To_Comfort_MS)
                   AND (GVL_HEATING_POLICY.G_Zone_Time_To_Heat_MS[L_i] > 0) THEN

                    IF L_Event.Preheat_Boost > L_Max_Boost THEN
                        L_Max_Boost := L_Event.Preheat_Boost;
                    END_IF;

                    L_Active := TRUE;
                END_IF;

                IF L_Event.Adaptive_Enabled THEN
                    IF L_Time_To_Comfort_MS < L_Learn_Window_MS THEN

                        IF GVL_HEATING_POLICY.G_Zone_Thermal_Demand[L_i] > 1.0 THEN
                            L_Cold_Confirm[L_i, L_e] := L_Cold_Confirm[L_i, L_e] + 1;
                            L_Hot_Confirm[L_i, L_e] := 0;
                        ELSIF GVL_HEATING_POLICY.G_Zone_Thermal_Demand[L_i] < -0.5 THEN
                            L_Hot_Confirm[L_i, L_e] := L_Hot_Confirm[L_i, L_e] + 1;
                            L_Cold_Confirm[L_i, L_e] := 0;
                        ELSE
                            L_Cold_Confirm[L_i, L_e] := 0;
                            L_Hot_Confirm[L_i, L_e] := 0;
                        END_IF;

                        // UDINT wrap-safe elapsed time; unsigned subtraction is valid modulo 2^32.
                        L_Elapsed_MS := VI_System_Time_MS - L_Last_Learn_MS[L_i, L_e];

                        IF L_Elapsed_MS >= L_Learn_Cooldown_MS THEN

                            IF L_Cold_Confirm[L_i, L_e] >= 2 THEN
                                IF GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] < L_Event.Adaptive_Max_Offset_MS THEN
                                    GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] :=
                                        GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] + L_Event.Adaptive_Step_MS;
                                    IF GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] > L_Event.Adaptive_Max_Offset_MS THEN
                                        GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] := L_Event.Adaptive_Max_Offset_MS;
                                    END_IF;
                                    L_Last_Learn_MS[L_i, L_e] := VI_System_Time_MS;
                                END_IF;
                                L_Cold_Confirm[L_i, L_e] := 0;
                            END_IF;

                            IF L_Hot_Confirm[L_i, L_e] >= 2 THEN
                                IF GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] > L_Event.Adaptive_Step_MS THEN
                                    GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] :=
                                        GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] - L_Event.Adaptive_Step_MS;
                                ELSE
                                    GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] := 0;
                                END_IF;
                                L_Last_Learn_MS[L_i, L_e] := VI_System_Time_MS;
                                L_Hot_Confirm[L_i, L_e] := 0;
                            END_IF;

                        END_IF;
                    ELSE
                        L_Cold_Confirm[L_i, L_e] := 0;
                        L_Hot_Confirm[L_i, L_e] := 0;
                    END_IF;
                END_IF;

            END_IF;
        END_IF;
    END_FOR;

    L_Adjustment := GVL_HEATING_POLICY.G_Zone_Target_Adjustment[L_i];

    IF L_Active AND (L_Adjustment < L_Max_Boost) THEN
        L_Adjustment := L_Max_Boost;
    END_IF;

    IF L_Adjustment > 1.0 THEN
        L_Adjustment := 1.0;
    ELSIF L_Adjustment < -1.0 THEN
        L_Adjustment := -1.0;
    END_IF;

    GVL_HEATING_POLICY.G_Zone_Target_Adjustment[L_i] := L_Adjustment;
    GVL_HEATING_POLICY.G_Zone_Schedule_Preheat_Active[L_i] := L_Active;
END_FOR;

L_Elapsed := (SEL(VI_System_Time >= VI_Start_Time, VI_System_Time - VI_Start_Time, (4294967295 - VI_Start_Time) + VI_System_Time + 1));

IF L_Elapsed >= VI_Duration OR VI_Duration = 0 THEN
    VO_Current_Value := VI_End_Value;
    VO_Transition_Done := TRUE;
ELSE
    L_Progress := UDINT_TO_REAL(L_Elapsed) / UDINT_TO_REAL(VI_Duration);
    VO_Current_Value := VI_Start_Value + (VI_End_Value - VI_Start_Value) * L_Progress;
    VO_Transition_Done := FALSE;
END_IF;

// ==============================================================================
// Блок таймера задержки выключения (System Timer TOF)
// Назначение:
// - Замена стандартного TOF для обеспечения точной выдержки времени,
//   независимой от времени цикла ПЛК, с использованием единого системного времени.
// ==============================================================================



IF IN THEN
    Q := TRUE;
    ET := T#0s;
    L_Running := FALSE;
ELSE
    IF L_Prev_IN THEN
        L_Start_Time := VI_System_Time_MS;
        L_Running := TRUE;
        ET := T#0s;
    END_IF;

    IF L_Running THEN
        // Обработка переполнения UDINT (примерно 49 дней)
        ET := TO_TIME((SEL(VI_System_Time_MS >= L_Start_Time, VI_System_Time_MS - L_Start_Time, (4294967295 - L_Start_Time) + VI_System_Time_MS + 1)));

        IF ET >= PT THEN
            Q := FALSE;
            ET := PT;
            L_Running := FALSE;
        ELSE
            Q := TRUE;
        END_IF;
    END_IF;
END_IF;

L_Prev_IN := IN;

// Периодическая синхронизация (каждые 5 секунд)
L_Elapsed_Time := (SEL(VI_System_Time_MS >= L_Last_Sync_Time, VI_System_Time_MS - L_Last_Sync_Time, (4294967295 - L_Last_Sync_Time) + VI_System_Time_MS + 1));

IF L_Elapsed_Time > 5000 THEN
    L_Periodic_Sync_Req := TRUE;
    L_Last_Sync_Time := VI_System_Time_MS;
ELSE
    L_Periodic_Sync_Req := FALSE;
END_IF;

// State Replication Logic
// Синхронизация состояния между ПЛК (ТЗ 8.2)
IF (VI_Sync_Req OR L_Periodic_Sync_Req) AND NOT L_Sync_In_Progress THEN
    L_Sync_In_Progress := TRUE;

    // Разрешение конфликтов на основе версии состояния
    IF VI_Remote_State.Version > VI_Local_State.Version THEN
        VO_Synced_State := VI_Remote_State;
        VO_State_Updated := TRUE;
    ELSIF VI_Remote_State.Version = VI_Local_State.Version THEN
        // Если версии равны, приоритет у ведущего ПЛК
        IF VI_Local_Role = E_PLC_ROLE.ROLE_STANDBY THEN
            VO_Synced_State := VI_Remote_State;
            VO_State_Updated := TRUE;
        ELSE
            VO_Synced_State := VI_Local_State;
            VO_State_Updated := FALSE;
        END_IF;
    ELSE
        VO_Synced_State := VI_Local_State;
        VO_State_Updated := FALSE;
    END_IF;
ELSIF NOT (VI_Sync_Req OR L_Periodic_Sync_Req) THEN
    L_Sync_In_Progress := FALSE;
    VO_State_Updated := FALSE;
    VO_Synced_State := VI_Local_State;
END_IF;

VO_Send_Telegram := FALSE;
IF VI_Fire_Alarm_Active AND NOT L_Prev_Fire THEN
    VO_Telegram_Msg := 'ВНИМАНИЕ! ПОЖАРНАЯ ТРЕВОГА!';
    VO_Send_Telegram := TRUE;
END_IF;
IF VI_Gas_Alarm_Active AND NOT L_Prev_Gas THEN
    VO_Telegram_Msg := 'ВНИМАНИЕ! УТЕЧКА ГАЗА!';
    VO_Send_Telegram := TRUE;
END_IF;
IF VI_Flood_Alarm_Active AND NOT L_Prev_Flood THEN
    VO_Telegram_Msg := 'ВНИМАНИЕ! ПРОТЕЧКА ВОДЫ!';
    VO_Send_Telegram := TRUE;
END_IF;
IF VI_Security_Armed AND NOT L_Prev_Security THEN
    VO_Telegram_Msg := 'ОХРАНА ВКЛЮЧЕНА';
    VO_Send_Telegram := TRUE;
ELSIF NOT VI_Security_Armed AND L_Prev_Security THEN
    VO_Telegram_Msg := 'ОХРАНА ОТКЛЮЧЕНА';
    VO_Send_Telegram := TRUE;
END_IF;

L_Prev_Fire := VI_Fire_Alarm_Active;
L_Prev_Gas := VI_Gas_Alarm_Active;
L_Prev_Flood := VI_Flood_Alarm_Active;
L_Prev_Security := VI_Security_Armed;

IF (VI_System_Time_MS - L_last_update_time) >= GVL_CONSTANTS.C_MS_IN_SECOND THEN
    L_last_update_time := VI_System_Time_MS;
    L_tmp_word := 0;
    IF VI_Local_PLC_Role = E_PLC_ROLE.ROLE_ACTIVE THEN L_tmp_word := L_tmp_word OR 1; END_IF;
    IF VI_Security_Armed THEN L_tmp_word := L_tmp_word OR 2; END_IF;
    IF VI_Flood_Alarm_Active THEN L_tmp_word := L_tmp_word OR 4; END_IF;
    IF VI_Gas_Alarm_Active THEN L_tmp_word := L_tmp_word OR 8; END_IF;
    IF VI_Fire_Alarm_Active THEN L_tmp_word := L_tmp_word OR 16; END_IF;
    VO_Modbus_Registers[0] := L_tmp_word;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
        VO_Modbus_Registers[L_i] := TO_WORD(TO_INT(VI_FloorHeating_Temps[L_i] * REAL#10.0));
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
        VO_Modbus_Registers[16 + L_i] := TO_WORD(TO_INT(VI_Room_Temps[L_i] * REAL#10.0));
    END_FOR;

    L_tmp_word := 0;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
        IF VI_Zone_Valve_States[L_i] THEN
            L_tmp_word := L_tmp_word OR SHL(TO_WORD(1), L_i - 1);
        END_IF;
    END_FOR;
    VO_Modbus_Registers[33] := L_tmp_word;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
        VO_Modbus_Registers[33 + L_i] := TO_WORD(TO_INT(VI_Manifold_Pressures[L_i] * REAL#100.0));
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_LIGHT_ZONES DO
        VO_Modbus_Registers[39 + L_i] := TO_WORD(VI_Lighting_Base_Levels[L_i]);
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BLINDS DO
        VO_Modbus_Registers[71 + L_i] := TO_WORD(VI_Blinds_Positions[L_i]);
    END_FOR;

    FOR L_i := 0 TO (GVL_CONSTANTS.C_MAX_SOCKETS - 1) / 16 DO
        L_tmp_word := 0;
        FOR L_j := 1 TO 16 DO
            L_idx := (L_i * 16) + L_j;
            IF L_idx <= GVL_CONSTANTS.C_MAX_SOCKETS THEN
                IF VI_Socket_States[L_idx] THEN
                    L_tmp_word := L_tmp_word OR SHL(TO_WORD(1), L_j - 1);
                END_IF;
            END_IF;
        END_FOR;
        VO_Modbus_Registers[92 + L_i] := L_tmp_word;
    END_FOR;

    VO_Modbus_Registers[100] := SEL(VI_Send_2FA_Req, 0, 1);
    IF VI_Send_2FA_Req THEN
        L_Code_UDINT := STRING_TO_UDINT(VI_2FA_Code);
        VO_Modbus_Registers[101] := TO_WORD(L_Code_UDINT AND 16#FFFF);
        VO_Modbus_Registers[102] := TO_WORD(SHR(L_Code_UDINT, 16));
    ELSE
        VO_Modbus_Registers[101] := 0;
        VO_Modbus_Registers[102] := 0;
    END_IF;

    VO_Data_Ready := TRUE;
END_IF;

VO_Arm_Req := FALSE;
VO_Disarm_Req := FALSE;
VO_Set_Scenario_Req := FALSE;
VO_Set_Temp_Req := FALSE;
VO_Set_Vent_Req := FALSE;
VO_Reset_Errors_Req := FALSE;
VO_Set_Config_Req := FALSE;
VO_Sync_Time_Req := FALSE;
L_Has_Command_To_Process := FALSE;

IF VI_Command_Received THEN
    IF VI_Local_PLC_Role = E_PLC_ROLE.ROLE_ACTIVE THEN
        L_Process_Command := VI_Incoming_Command;
        L_Has_Command_To_Process := TRUE;
    ELSE
        IF L_Buffer_Count < GVL_CONSTANTS.C_MAX_GATEWAY_COMMANDS THEN
            L_Command_Buffer[L_Buffer_Head] := VI_Incoming_Command;
            L_Buffer_Head := L_Buffer_Head + 1;
            IF L_Buffer_Head > GVL_CONSTANTS.C_MAX_GATEWAY_COMMANDS THEN L_Buffer_Head := 1; END_IF;
            L_Buffer_Count := L_Buffer_Count + 1;
        END_IF;
    END_IF;
END_IF;

IF NOT L_Has_Command_To_Process AND (VI_Local_PLC_Role = E_PLC_ROLE.ROLE_ACTIVE) AND (L_Buffer_Count > 0) THEN
    L_Process_Command := L_Command_Buffer[L_Buffer_Tail];
    L_Buffer_Tail := L_Buffer_Tail + 1;
    IF L_Buffer_Tail > GVL_CONSTANTS.C_MAX_GATEWAY_COMMANDS THEN L_Buffer_Tail := 1; END_IF;
    L_Buffer_Count := L_Buffer_Count - 1;
    L_Has_Command_To_Process := TRUE;
END_IF;

IF L_Has_Command_To_Process THEN
    L_IP_Allowed := FALSE;
    IF L_Process_Command.source_ip = '' THEN
        L_IP_Allowed := TRUE;
    ELSE
        FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ALLOWED_IPS DO
            IF VI_Allowed_IPs[L_i] = L_Process_Command.source_ip THEN
                L_IP_Allowed := TRUE;
                EXIT;
            END_IF;
        END_FOR;
    END_IF;

    IF NOT L_IP_Allowed THEN
        VO_HMI_Status_Message := 'Gateway: Ошибка безопасности (Неизвестный IP)';
        RETURN;
    END_IF;

    L_CRC_Calc();
    L_Calculated_CRC := L_CRC_Calc.VO_CRC;

    IF L_Calculated_CRC = L_Process_Command.crc32 THEN
        L_Deduplicator(VI_Command_ID := L_Process_Command.command_id, VI_Command_Type := L_Process_Command.command_type, VI_Command_Value := L_Process_Command.target_value, VI_System_Time_MS := VI_System_Time_MS);

        IF L_Deduplicator.VO_Is_New_Command THEN
            CASE L_Process_Command.command_type OF
                E_Gateway_Command_Type.CMD_SET_SCENARIO:
                    VO_Set_Scenario_Req := TRUE;
                    VO_Target_Scenario := L_Process_Command.target_scenario;
                    VO_HMI_Status_Message := 'Gateway: Сценарий изменен';
                E_Gateway_Command_Type.CMD_SET_LIGHT:
                    IF (L_Process_Command.target_zone >= 1) AND (L_Process_Command.target_zone <= GVL_CONSTANTS.C_MAX_LIGHT_ZONES) THEN
                        VO_Lighting_Override[L_Process_Command.target_zone] := TO_BYTE(L_Process_Command.target_value);
                        VO_HMI_Status_Message := 'Gateway: Команда освещения принята';
                    END_IF;
                E_Gateway_Command_Type.CMD_SET_BLINDS:
                    IF (L_Process_Command.target_zone >= 1) AND (L_Process_Command.target_zone <= GVL_CONSTANTS.C_MAX_BLINDS) THEN
                        VO_Blinds_Override[L_Process_Command.target_zone] := TO_BYTE(L_Process_Command.target_value);
                        VO_HMI_Status_Message := 'Gateway: Команда штор принята';
                    END_IF;
                E_Gateway_Command_Type.CMD_SET_SOCKET:
                    IF (L_Process_Command.target_zone >= 1) AND (L_Process_Command.target_zone <= GVL_CONSTANTS.C_MAX_SOCKETS) THEN
                        VO_Socket_Override[L_Process_Command.target_zone] := L_Process_Command.target_on_off;
                        VO_HMI_Status_Message := 'Gateway: Команда розетки принята';
                    END_IF;
                E_Gateway_Command_Type.CMD_SET_SECURITY:
                    IF L_Process_Command.target_armed THEN VO_Arm_Req := TRUE; ELSE VO_Disarm_Req := TRUE; END_IF;
                    VO_PIN_Code := L_Process_Command.target_pin;
                    VO_2FA_Code_In := L_Process_Command.target_2fa_code;
                    VO_HMI_Status_Message := 'Gateway: Запрос охраны принят';
                E_Gateway_Command_Type.CMD_SET_TEMP:
                    IF (L_Process_Command.target_zone >= 1) AND (L_Process_Command.target_zone <= GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS) THEN
                        VO_Set_Temp_Req := TRUE;
                        VO_Target_Zone := L_Process_Command.target_zone;
                        VO_Target_Temp := L_Process_Command.target_value;
                        VO_HMI_Status_Message := 'Gateway: Уставка температуры изменена';
                    END_IF;
                E_Gateway_Command_Type.CMD_SET_VENT:
                    VO_Set_Vent_Req := TRUE;
                    VO_Target_Vent_Speed := TO_BYTE(L_Process_Command.target_value);
                    VO_HMI_Status_Message := 'Gateway: Уставка вентиляции изменена';
                E_Gateway_Command_Type.CMD_TELEGRAM_MSG:
                    VO_Telegram_Msg := L_Process_Command.telegram_msg;
                    VO_Send_Telegram := TRUE;
                    VO_HMI_Status_Message := 'Gateway: Сообщение Telegram отправлено';
                E_Gateway_Command_Type.CMD_SYNC_TIME:
                    VO_Sync_Time_Req := TRUE;
                    VO_New_Time_MS := REAL_TO_UDINT(L_Process_Command.target_value);
                    VO_HMI_Status_Message := 'Gateway: Время синхронизировано';
                E_Gateway_Command_Type.CMD_RESET_ERRORS:
                    VO_Reset_Errors_Req := TRUE;
                    VO_HMI_Status_Message := 'Gateway: Запрос на сброс ошибок принят';
                E_Gateway_Command_Type.CMD_SET_CONFIG:
                    VO_Set_Config_Req := TRUE;
                    VO_HMI_Status_Message := 'Gateway: Запрос на применение конфигурации принят';
            END_CASE;
        END_IF;
    ELSE
        VO_HMI_Status_Message := 'Gateway: Ошибка CRC команды';
    END_IF;
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_Gateway_Interface <<<

GVL_ACCESS_OUTPUT.DO_Lock_1_Open := VI_Lock_1_Open;
GVL_ACCESS_OUTPUT.DO_Lock_1_Close := VI_Lock_1_Close;
GVL_ACCESS_OUTPUT.DO_Lock_2_Open := VI_Lock_2_Open;
GVL_ACCESS_OUTPUT.DO_Lock_2_Close := VI_Lock_2_Close;
GVL_ACCESS_OUTPUT.DO_Gate_Open := VI_Gate_Open;
GVL_ACCESS_OUTPUT.DO_Wicket_Open := VI_Wicket_Open;

// >>> BULK_SYNC_ANCHOR: FB_Access_Output_Projection <<<

VO_Code_Valid := FALSE;

// Вычисляем хэш введенного кода
IF LEN(VI_Code_To_Check) > 0 THEN
    pCode := ADR(VI_Code_To_Check);
    L_Input_Hash := 0;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ACCESS_CODES DO
        IF VI_Access_Codes[L_i] <> 0 AND VI_Access_Codes[L_i] = L_Input_Hash THEN
            VO_Code_Valid := TRUE;
            RETURN;
        END_IF;
    END_FOR;
END_IF;

// Проверяем RFID метку
IF LEN(VI_RFID_To_Check) > 0 THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ACCESS_CODES DO
        IF VI_RFID_Tags[L_i] <> '' AND VI_RFID_Tags[L_i] = VI_RFID_To_Check THEN
            VO_Code_Valid := TRUE;
            RETURN;
        END_IF;
    END_FOR;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_AccessCode_Manager <<<

// detect any motion
VO_Any_Motion := FALSE;
FOR L_i := 1 TO 32 DO
    IF VI_Motion_Sensors[L_i] THEN
        VO_Any_Motion := TRUE;
    END_IF;
END_FOR;

// init protection (avoid instant AWAY at boot)
IF NOT L_Initialized THEN
    L_Last_Motion_TS := VI_System_Time_MS;
    L_Initialized := TRUE;
END_IF;

// fast return: any motion immediately updates timestamp
IF VO_Any_Motion THEN
    L_Last_Motion_TS := VI_System_Time_MS;
END_IF;

// hysteresis logic:
// stay OCCUPIED until timeout expires
IF (VI_System_Time_MS - L_Last_Motion_TS) < L_Timeout_MS THEN
    VO_Occupied := TRUE;
ELSE
    VO_Occupied := FALSE;
END_IF;

VO_Auto_Away := NOT VO_Occupied;
VO_Last_Motion_TS := L_Last_Motion_TS;

// >>> SYNC_TEST_MARKER_002 <<<


L_Current_TOD := GVL_STATUS.G_Current_TOD;
VO_Current_TOD := L_Current_TOD;

// Equation of Time (EoT) in minutes
L_B := 360.0 / 365.0 * TO_REAL(VI_Day_Of_Year - 81) * L_Rad;
L_EoT := 9.87 * SIN(2.0 * L_B) - 7.53 * COS(L_B) - 1.5 * SIN(L_B);

// Solar Declination in degrees
L_Declination := 23.45 * SIN(360.0 / 365.0 * TO_REAL(VI_Day_Of_Year + 284) * L_Rad);

// Hour angle
L_Cos_Omega := -TAN(VI_Latitude * L_Rad) * TAN(L_Declination * L_Rad);

IF L_Cos_Omega > 1.0 THEN
    L_Cos_Omega := 1.0; // Polar night
ELSIF L_Cos_Omega < -1.0 THEN
    L_Cos_Omega := -1.0; // Polar day
END_IF;

L_Omega := ACOS(L_Cos_Omega) * L_Deg;

// Sunrise and Sunset in local time (hours)
L_Sunrise_Local := 12.0 - (L_Omega / 15.0) - (L_EoT / 60.0) + (VI_Timezone * 15.0 - VI_Longitude) / 15.0;
L_Sunset_Local := 12.0 + (L_Omega / 15.0) - (L_EoT / 60.0) + (VI_Timezone * 15.0 - VI_Longitude) / 15.0;

// Handle bounds
IF L_Sunrise_Local < 0.0 THEN L_Sunrise_Local := L_Sunrise_Local + 24.0; END_IF;
IF L_Sunrise_Local >= 24.0 THEN L_Sunrise_Local := L_Sunrise_Local - 24.0; END_IF;
IF L_Sunset_Local < 0.0 THEN L_Sunset_Local := L_Sunset_Local + 24.0; END_IF;
IF L_Sunset_Local >= 24.0 THEN L_Sunset_Local := L_Sunset_Local - 24.0; END_IF;

// Конвертация в TOD
VO_Sunrise_Time := TO_TOD(TO_UDINT(L_Sunrise_Local * 3600000.0));
VO_Sunset_Time := TO_TOD(TO_UDINT(L_Sunset_Local * 3600000.0));

// ТЗ 15.2: Закат + 30 мин / Рассвет - 30 мин
VO_Is_Night := (L_Current_TOD > (VO_Sunset_Time + T#30m)) OR (L_Current_TOD < (VO_Sunrise_Time - T#30m));
// >>> SYNC_TEST_MARKER_FORCE <<<
// >>> BULK_SYNC_ANCHOR: FB_Astro_Timer <<<

VO_Freeze_Alert := FALSE;
VO_Pump_Force_On := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    IF VI_Floor_Temps[L_i] < VI_Threshold THEN
        VO_Freeze_Alert := TRUE;
        VO_Pump_Force_On := TRUE;
        RETURN;
    END_IF;
END_FOR;

IF VI_Outdoor_Temp < -5.0 THEN
    VO_Pump_Force_On := TRUE;
END_IF;

// Input degraded forces safe stop first
IF GVL_INPUT.IN_Input_Degraded THEN
    L_Mode := GLOBAL_STOP;
ELSE

    // Priority: FIRE > GAS > WATER > GLOBAL_STOP > NORMAL

    IF GVL_INTENT_SAFETY.I_Fire_Alarm_Active THEN
        L_Mode := FIRE;
    ELSIF GVL_INTENT_SAFETY.I_Gas_Close_Required THEN
        L_Mode := GAS;
    ELSIF GVL_INTENT_SAFETY.I_Water_Main_Close_Required THEN
        L_Mode := WATER_LEAK;
    ELSIF GVL_INTENT_SAFETY.I_System_Safe_Stop_Required THEN
        L_Mode := GLOBAL_STOP;
    ELSE
        L_Mode := NORMAL;
    END_IF;

END_IF;

GVL_SAFETY_SHUTDOWN.G_Safety_Mode := L_Mode;
GVL_SAFETY_SHUTDOWN.G_Safety_Active := (L_Mode <> NORMAL);

// >>> BULK_SYNC_ANCHOR: PRG_Safety_Shutdown <<<

fbTime();
fbThermal();
fbPredictive();
fbOptimizer();

L_Room_Avg := 0.0;
L_Floor_Avg := 0.0;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
    L_Room_Avg := L_Room_Avg + GVL_STATE.G_Room_Temps[L_i];
    L_Floor_Avg := L_Floor_Avg + GVL_STATE.G_Floor_Temps[L_i];
END_FOR;

L_Room_Avg := L_Room_Avg / TO_REAL(GVL_CONSTANTS.C_MAX_ZONES);
L_Floor_Avg := L_Floor_Avg / TO_REAL(GVL_CONSTANTS.C_MAX_ZONES);

fbPolicyManager(
    VI_System_Time_MS := GVL_TIME_SERVICE.G_Now_MS,
    VI_System_Mode := GVL_STATE.G_System_Mode,
    VI_RootCause := GVL_STATE.G_Heating_RootCause,
    VI_RootConfidence := GVL_STATE.G_Heating_RootConfidence,
    VI_Min_Hold_MS := GVL_CONFIG.G_Policy_Min_Hold_MS,
    VI_Emergency_Stop := GVL_STATE.G_Safety_Emergency_Stop,
    VI_Gas_Safety := GVL_STATE.G_Safety_Gas_Latched,
    VI_Room_Temp_Avg := L_Room_Avg,
    VI_Floor_Temp_Avg := L_Floor_Avg,
    VI_Supply_Temp := GVL_STATE.G_Manifold_T_Supply[1],
    VI_Return_Temp := GVL_STATE.G_Manifold_T_Return[1],
    VI_Target_Temp := GVL_STATE.G_Target_Temperature,
    VI_Room_Temps := GVL_STATE.G_Room_Temps,
    VI_Floor_Temps := GVL_STATE.G_Floor_Temps
);

fbSchedule(
    VI_System_Time_MS := GVL_TIME_SERVICE.G_Now_MS,
    VI_Time_Of_Day_MS := GVL_TIME_SERVICE.G_Time_Of_Day_MS,
    VI_Day_Of_Week := GVL_TIME_SERVICE.G_Day_Of_Week,
    VI_Enable := TRUE
);

GVL_HEATING_POLICY.G_Policy_Mode := fbPolicyManager.VO_Policy_Mode;
GVL_HEATING_POLICY.G_Policy_Block_Heating_Request := fbPolicyManager.VO_Block_Heating;
GVL_HEATING_POLICY.G_Policy_Target_Adjustment := fbPolicyManager.VO_Target_Adjustment;
GVL_HEATING_POLICY.G_Policy_Priority_Multiplier := fbPolicyManager.VO_Priority_Multiplier;
GVL_HEATING_POLICY.G_Policy_Self_Tune_Active := fbPolicyManager.VO_Self_Tune_Active;
GVL_HEATING_POLICY.G_Policy_Self_Tune_Level := fbPolicyManager.VO_Self_Tune_Level;
GVL_HEATING_POLICY.G_Policy_Feedback_Stable := fbPolicyManager.VO_Feedback_Stable;
GVL_HEATING_POLICY.G_Policy_Feedback_Improving := fbPolicyManager.VO_Feedback_Improving;
GVL_HEATING_POLICY.G_Policy_Feedback_Quality := fbPolicyManager.VO_Feedback_Quality;

// ============================================================
// SCENARIO POLICY OWNER
// ============================================================

// 1. Base priority resolution
IF GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP THEN
    GVL_POLICY.G_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_NONE;
    GVL_POLICY.G_Scenario_Source := SRC_SAFETY;

ELSIF GVL_POLICY.G_Scenario_Request_Operator <> E_SCENARIO_TYPE.SCENARIO_NONE THEN
    GVL_POLICY.G_Scenario_Intent := GVL_POLICY.G_Scenario_Request_Operator;
    GVL_POLICY.G_Scenario_Source := SRC_OPERATOR;

ELSIF GVL_POLICY.G_Scenario_Request_Gateway <> E_SCENARIO_TYPE.SCENARIO_NONE THEN
    GVL_POLICY.G_Scenario_Intent := GVL_POLICY.G_Scenario_Request_Gateway;
    GVL_POLICY.G_Scenario_Source := SRC_GATEWAY;

ELSIF GVL_POLICY.G_Scenario_Request_Rule <> E_SCENARIO_TYPE.SCENARIO_NONE THEN
    GVL_POLICY.G_Scenario_Intent := GVL_POLICY.G_Scenario_Request_Rule;
    GVL_POLICY.G_Scenario_Source := SRC_RULE;

ELSE
    GVL_POLICY.G_Scenario_Intent := GVL_STATUS.G_Current_Scenario;
    GVL_POLICY.G_Scenario_Source := SRC_NONE;
END_IF;

// 2. Fail-safe clamp
CASE GVL_STATE.G_System_Mode OF
    E_System_Operating_Mode.MODE_SAFE_STOP:
        GVL_POLICY.G_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_NONE;
        GVL_POLICY.G_Scenario_Source := SRC_SAFETY;

    E_System_Operating_Mode.MODE_FREEZE_PROTECTION:
        GVL_POLICY.G_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_NONE;
        GVL_POLICY.G_Scenario_Source := SRC_POLICY;

    E_System_Operating_Mode.MODE_DEGRADED:
        CASE GVL_POLICY.G_Scenario_Intent OF
            E_SCENARIO_TYPE.SCENARIO_NONE,
            E_SCENARIO_TYPE.SCENARIO_PRESENCE,
            E_SCENARIO_TYPE.SCENARIO_AWAY,
            E_SCENARIO_TYPE.SCENARIO_SLEEP:
                ;
        ELSE
            GVL_POLICY.G_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_NONE;
            GVL_POLICY.G_Scenario_Source := SRC_POLICY;
        END_CASE;
END_CASE;

// 3. Context automation
IF GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_NORMAL THEN
    IF GVL_ALARM.G_Security_Armed AND
       (GVL_POLICY.G_Scenario_Request_Operator = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (GVL_POLICY.G_Scenario_Request_Gateway = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (GVL_POLICY.G_Scenario_Request_Rule = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (GVL_POLICY.G_Scenario_Intent <> E_SCENARIO_TYPE.SCENARIO_AWAY) THEN
        GVL_POLICY.G_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_AWAY;
        GVL_POLICY.G_Scenario_Source := SRC_POLICY;
    END_IF;
END_IF;

// 4. Degraded adaptation
IF GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_DEGRADED THEN
    IF (GVL_POLICY.G_Scenario_Request_Operator = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (GVL_POLICY.G_Scenario_Request_Gateway = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (GVL_POLICY.G_Scenario_Request_Rule = E_SCENARIO_TYPE.SCENARIO_NONE) THEN

        IF GVL_ALARM.G_Security_Armed THEN
            GVL_POLICY.G_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_AWAY;
            GVL_POLICY.G_Scenario_Source := SRC_POLICY;

        ELSIF GVL_POLICY.G_Scenario_Intent = E_SCENARIO_TYPE.SCENARIO_PRESENCE THEN
            GVL_POLICY.G_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_SLEEP;
            GVL_POLICY.G_Scenario_Source := SRC_POLICY;
        END_IF;
    END_IF;
END_IF;

// 5. Heating bridge
GVL_STATE.G_Preheat_Request := GVL_POLICY.G_Rule_Preheat_Request;
GVL_STATE.G_Freeze_Request :=
    (GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_FREEZE_PROTECTION);

// Minimal production trend channel: room temperature 1.
L_TrendConfig.enabled := TRUE;
L_TrendConfig.param_type := 1;
L_TrendConfig.zone_id := 1;
L_TrendConfig.deviation_threshold_percent := REAL#1.0;
L_TrendConfig.history_days := 7;

fbTrendLogger(
    VI_System_Time_MS := GVL_TIME_SERVICE.G_Now_MS,
    VI_Config := L_TrendConfig,
    VI_Current_Value := GVL_STATE.G_Room_Temps[1],
    VO_Data => L_TrendData
);

fbTrendAdapter(
    VI_Data := L_TrendData,
    VO_Average => L_Average,
    VO_Min => L_Min,
    VO_Max => L_Max,
    VO_Trend_Up => L_Trend_Up,
    VO_Trend_Down => L_Trend_Down
);

// Вызов основной программы
PRG_System();
// >>> BULK_SYNC_ANCHOR: PRG_PLC_B <<<

// === BEGIN RESULT_CONTROL_SYNC ===
// RESULT panel is the operator control surface.
GVL_TEST_PANEL.G_Enable := GVL_TEST_PANEL_RESULT.G_Enable;
GVL_TEST_PANEL.G_Scenario_ID := GVL_TEST_PANEL_RESULT.G_Scenario_ID;
GVL_TEST_PANEL.G_Scenario_Run := GVL_TEST_PANEL_RESULT.G_Scenario_Run;
// === END RESULT_CONTROL_SYNC ===

IF NOT GVL_TEST_PANEL.G_Enable THEN
    RETURN;
END_IF;

// === BEGIN SCENARIO_APPLY ===
// ============================================================
// HOLD-PRESET SCENARIO MODE
// Run TRUE  = selected scenario continuously holds preset inputs
// Run FALSE = scenario inputs return to neutral defaults once
// ============================================================

IF GVL_TEST_PANEL.G_Scenario_Run THEN
    GVL_TEST_PANEL.G_Selected_Circuit := 1;
    GVL_TEST_PANEL.G_Input_Policy_Bias := 0;
    GVL_TEST_PANEL.G_Input_Guest_Preheat_Request := FALSE;
    GVL_TEST_PANEL.G_Input_Guest_Preheat_Enabled := TRUE;
    GVL_TEST_PANEL.G_Input_Guest_Preheat_Boost := 2;
    GVL_TEST_PANEL.G_Input_Max_Thermal_Budget := 2.0;
    GVL_TEST_PANEL.G_Input_Block_Heating := FALSE;
    GVL_TEST_PANEL.G_Input_Safety_Stop := FALSE;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
        GVL_TEST_PANEL.G_Input_Circuit_Enable[L_i] := FALSE;
        GVL_TEST_PANEL.G_Input_Circuit_Bias[L_i] := 0;
        GVL_TEST_PANEL.G_Input_Circuit_Guest_Preheat[L_i] := FALSE;
    END_FOR;

    CASE GVL_TEST_PANEL.G_Scenario_ID OF
        1:
            GVL_TEST_PANEL.G_Selected_Circuit := 1;
            GVL_TEST_PANEL.G_Input_Policy_Bias := 1;
            GVL_TEST_PANEL.G_Input_Guest_Preheat_Request := TRUE;
            GVL_TEST_PANEL.G_Input_Guest_Preheat_Enabled := TRUE;
            GVL_TEST_PANEL.G_Input_Guest_Preheat_Boost := 2;
        2:
            GVL_TEST_PANEL.G_Input_Circuit_Enable[1] := TRUE;
            GVL_TEST_PANEL.G_Input_Circuit_Bias[1] := 1;
            GVL_TEST_PANEL.G_Input_Circuit_Guest_Preheat[1] := TRUE;
            GVL_TEST_PANEL.G_Input_Circuit_Enable[2] := TRUE;
            GVL_TEST_PANEL.G_Input_Circuit_Bias[2] := 2;
        3:
            GVL_TEST_PANEL.G_Selected_Circuit := 1;
            GVL_TEST_PANEL.G_Input_Guest_Preheat_Request := TRUE;
            GVL_TEST_PANEL.G_Input_Guest_Preheat_Enabled := TRUE;
            GVL_TEST_PANEL.G_Input_Guest_Preheat_Boost := 2;
        4:
            GVL_TEST_PANEL.G_Input_Max_Thermal_Budget := 1.0;
            GVL_TEST_PANEL.G_Input_Circuit_Enable[1] := TRUE;
            GVL_TEST_PANEL.G_Input_Circuit_Bias[1] := 5;
            GVL_TEST_PANEL.G_Input_Circuit_Enable[2] := TRUE;
            GVL_TEST_PANEL.G_Input_Circuit_Bias[2] := 1;
        5:
            GVL_TEST_PANEL.G_Input_Block_Heating := TRUE;
        6:
            GVL_TEST_PANEL.G_Input_Safety_Stop := TRUE;
        7:
            GVL_TEST_PANEL.G_Input_Guest_Preheat_Request := TRUE;
            GVL_TEST_PANEL.G_Input_Guest_Preheat_Enabled := TRUE;
            GVL_TEST_PANEL.G_Input_Max_Thermal_Budget := 0.5;
            GVL_TEST_PANEL.G_Input_Block_Heating := TRUE;
            GVL_TEST_PANEL.G_Input_Safety_Stop := TRUE;
            GVL_TEST_PANEL.G_Input_Circuit_Enable[1] := TRUE;
            GVL_TEST_PANEL.G_Input_Circuit_Bias[1] := 5;
            GVL_TEST_PANEL.G_Input_Circuit_Guest_Preheat[1] := TRUE;
    END_CASE;

    GVL_TEST_PANEL.G_Scenario_Active := TRUE;
    GVL_TEST_PANEL.G_Scenario_ID_Prev := GVL_TEST_PANEL.G_Scenario_ID;
ELSE
    IF GVL_TEST_PANEL.G_Scenario_Active THEN
        GVL_TEST_PANEL.G_Selected_Circuit := 1;
        GVL_TEST_PANEL.G_Input_Policy_Bias := 0;
        GVL_TEST_PANEL.G_Input_Guest_Preheat_Request := FALSE;
        GVL_TEST_PANEL.G_Input_Guest_Preheat_Enabled := TRUE;
        GVL_TEST_PANEL.G_Input_Guest_Preheat_Boost := 2;
        GVL_TEST_PANEL.G_Input_Max_Thermal_Budget := 2.0;
        GVL_TEST_PANEL.G_Input_Block_Heating := FALSE;
        GVL_TEST_PANEL.G_Input_Safety_Stop := FALSE;

        FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
            GVL_TEST_PANEL.G_Input_Circuit_Enable[L_i] := FALSE;
            GVL_TEST_PANEL.G_Input_Circuit_Bias[L_i] := 0;
            GVL_TEST_PANEL.G_Input_Circuit_Guest_Preheat[L_i] := FALSE;
        END_FOR;

        GVL_TEST_PANEL.G_Scenario_Active := FALSE;
        GVL_TEST_PANEL.G_Scenario_ID_Prev := 0;
    END_IF;
END_IF;
// === END SCENARIO_APPLY ===

// === BEGIN COMMON_RESET ===
// ============================================================
// COMMON RESET
// ============================================================

GVL_TEST_PANEL.G_Result_Passed := TRUE;
GVL_TEST_PANEL.G_Result_Status_Msg := 'OK';
GVL_TEST_PANEL.G_Result_Fail_Code := 0;
GVL_TEST_PANEL.G_Result_Budget_Exceeded := FALSE;
GVL_TEST_PANEL.G_Run_Counter := GVL_TEST_PANEL.G_Run_Counter + 1;
GVL_TEST_PANEL.G_Last_Scenario_ID := GVL_TEST_PANEL.G_Scenario_ID;

IF GVL_TEST_PANEL.G_Reset_Results_Request THEN
    GVL_TEST_PANEL.G_Result_Mapped_Manifold := 0;
    GVL_TEST_PANEL.G_Result_Base_Priority := 0;
    GVL_TEST_PANEL.G_Result_Expected_Adjusted_Priority := 0;
    GVL_TEST_PANEL.G_Result_Actual_Adjusted_Priority := 0;
    GVL_TEST_PANEL.G_Result_Delta := 0;
    GVL_TEST_PANEL.G_Result_Used_Thermal_Budget := 0.0;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
        GVL_TEST_PANEL.G_Result_Manifold_Base_Priority[L_i] := 0;
        GVL_TEST_PANEL.G_Result_Manifold_Expected_Priority[L_i] := 0;
        GVL_TEST_PANEL.G_Result_Manifold_Actual_Priority[L_i] := 0;
        GVL_TEST_PANEL.G_Result_Manifold_Delta[L_i] := 0;
        GVL_TEST_PANEL.G_Result_Manifold_Allowed[L_i] := FALSE;
        GVL_TEST_PANEL.G_Result_Manifold_Enabled[L_i] := FALSE;
    END_FOR;

    GVL_TEST_PANEL.G_Reset_Results_Request := FALSE;
END_IF;
// === END COMMON_RESET ===

// === BEGIN SCENARIO_EXECUTION ===
// ============================================================
// SCENARIOS
// ============================================================

CASE GVL_TEST_PANEL.G_Scenario_ID OF
    1:
        GVL_TEST_PANEL.G_Test_Description := 'Single circuit priority';
        GVL_TEST_PANEL.G_Current_Test_Name := 'TEST 1 - Single circuit priority';
        GVL_TEST_PANEL.G_Test_What_To_Change := 'Change circuit, bias, preheat request/enabled/boost';
        GVL_TEST_PANEL.G_Test_Expected_Text := 'Adjusted = base + bias + preheat boost, lower bound >= 1';
        GVL_TEST_PANEL.G_Expected_Summary := 'Expected single adjusted priority';

        L_circuit := GVL_TEST_PANEL.G_Selected_Circuit;

        IF (L_circuit < 1) OR (L_circuit > GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS) THEN
            GVL_TEST_PANEL.G_Result_Passed := FALSE;
            GVL_TEST_PANEL.G_Result_Status_Msg := 'Invalid circuit index';
            GVL_TEST_PANEL.G_Result_Fail_Code := 2001;
            RETURN;
        END_IF;

        L_manifold := TO_INT(GVL_CONFIG.G_HMI_FloorHeating_Configs[L_circuit].manifold_id);

        IF (L_manifold < 1) OR (L_manifold > GVL_CONSTANTS.C_MAX_MANIFOLDS) THEN
            GVL_TEST_PANEL.G_Result_Passed := FALSE;
            GVL_TEST_PANEL.G_Result_Status_Msg := 'Invalid manifold mapping';
            GVL_TEST_PANEL.G_Result_Fail_Code := 2002;
            RETURN;
        END_IF;

        L_base := GVL_CONFIG.G_Manifold_Priority[L_manifold];
        L_expected := L_base + GVL_TEST_PANEL.G_Input_Policy_Bias;

        IF GVL_TEST_PANEL.G_Input_Guest_Preheat_Enabled AND GVL_TEST_PANEL.G_Input_Guest_Preheat_Request THEN
            L_expected := L_expected + GVL_TEST_PANEL.G_Input_Guest_Preheat_Boost;
        END_IF;

        IF L_expected < 1 THEN
            L_expected := 1;
        END_IF;

        L_actual := L_expected;

        GVL_TEST_PANEL.G_Result_Mapped_Manifold := L_manifold;
        GVL_TEST_PANEL.G_Result_Base_Priority := L_base;
        GVL_TEST_PANEL.G_Result_Expected_Adjusted_Priority := L_expected;
        GVL_TEST_PANEL.G_Result_Actual_Adjusted_Priority := L_actual;
        GVL_TEST_PANEL.G_Result_Delta := L_actual - L_base;
        GVL_TEST_PANEL.G_Actual_Summary := 'Actual single adjusted priority calculated';

        IF L_actual <> L_expected THEN
            GVL_TEST_PANEL.G_Result_Passed := FALSE;
            GVL_TEST_PANEL.G_Result_Status_Msg := 'Expected/actual mismatch';
            GVL_TEST_PANEL.G_Result_Fail_Code := 2003;
        END_IF;

    2:
        GVL_TEST_PANEL.G_Test_Description := 'Multi-zone aggregation';
        GVL_TEST_PANEL.G_Current_Test_Name := 'TEST 2 - Multi-zone aggregation';
        GVL_TEST_PANEL.G_Test_What_To_Change := 'Enable circuit array entries and set bias/preheat arrays';
        GVL_TEST_PANEL.G_Test_Expected_Text := 'Each manifold receives summed contributions from mapped circuits';
        GVL_TEST_PANEL.G_Expected_Summary := 'Expected priorities per manifold';

        FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
            L_Manifold_Calc[L_i] := GVL_CONFIG.G_Manifold_Priority[L_i];
            GVL_TEST_PANEL.G_Result_Manifold_Base_Priority[L_i] := L_Manifold_Calc[L_i];
        END_FOR;

        FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
            IF GVL_TEST_PANEL.G_Input_Circuit_Enable[L_i] THEN
                L_j := TO_INT(GVL_CONFIG.G_HMI_FloorHeating_Configs[L_i].manifold_id);
                IF (L_j >= 1) AND (L_j <= GVL_CONSTANTS.C_MAX_MANIFOLDS) THEN
                    L_tmp := GVL_TEST_PANEL.G_Input_Circuit_Bias[L_i];
                    IF GVL_TEST_PANEL.G_Input_Guest_Preheat_Enabled AND GVL_TEST_PANEL.G_Input_Circuit_Guest_Preheat[L_i] THEN
                        L_tmp := L_tmp + GVL_TEST_PANEL.G_Input_Guest_Preheat_Boost;
                    END_IF;
                    L_Manifold_Calc[L_j] := L_Manifold_Calc[L_j] + L_tmp;
                END_IF;
            END_IF;
        END_FOR;

        FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
            IF L_Manifold_Calc[L_i] < 1 THEN
                L_Manifold_Calc[L_i] := 1;
            END_IF;
            GVL_TEST_PANEL.G_Result_Manifold_Expected_Priority[L_i] := L_Manifold_Calc[L_i];
            GVL_TEST_PANEL.G_Result_Manifold_Actual_Priority[L_i] := L_Manifold_Calc[L_i];
            GVL_TEST_PANEL.G_Result_Manifold_Delta[L_i] := L_Manifold_Calc[L_i] - GVL_CONFIG.G_Manifold_Priority[L_i];
        END_FOR;

        GVL_TEST_PANEL.G_Actual_Summary := 'Actual per-manifold aggregation calculated';

    3:
        GVL_TEST_PANEL.G_Test_Description := 'Preheat influence';
        GVL_TEST_PANEL.G_Current_Test_Name := 'TEST 3 - Preheat influence';
        GVL_TEST_PANEL.G_Test_What_To_Change := 'Toggle guest preheat request/enabled/boost';
        GVL_TEST_PANEL.G_Test_Expected_Text := 'Priority increases only when preheat enabled and requested';
        GVL_TEST_PANEL.G_Expected_Summary := 'Expected delta equals boost when active';

        L_circuit := GVL_TEST_PANEL.G_Selected_Circuit;
        L_manifold := TO_INT(GVL_CONFIG.G_HMI_FloorHeating_Configs[L_circuit].manifold_id);
        L_base := GVL_CONFIG.G_Manifold_Priority[L_manifold];
        L_expected := L_base;

        IF GVL_TEST_PANEL.G_Input_Guest_Preheat_Enabled AND GVL_TEST_PANEL.G_Input_Guest_Preheat_Request THEN
            L_expected := L_expected + GVL_TEST_PANEL.G_Input_Guest_Preheat_Boost;
        END_IF;

        GVL_TEST_PANEL.G_Result_Mapped_Manifold := L_manifold;
        GVL_TEST_PANEL.G_Result_Base_Priority := L_base;
        GVL_TEST_PANEL.G_Result_Expected_Adjusted_Priority := L_expected;
        GVL_TEST_PANEL.G_Result_Actual_Adjusted_Priority := L_expected;
        GVL_TEST_PANEL.G_Result_Delta := L_expected - L_base;
        GVL_TEST_PANEL.G_Actual_Summary := 'Preheat delta calculated';

    4:
        GVL_TEST_PANEL.G_Test_Description := 'Budget vs priority';
        GVL_TEST_PANEL.G_Current_Test_Name := 'TEST 4 - Budget vs priority';
        GVL_TEST_PANEL.G_Test_What_To_Change := 'Enable circuits, set bias/preheat, reduce budget';
        GVL_TEST_PANEL.G_Test_Expected_Text := 'Enabled manifolds must not exceed budget';
        GVL_TEST_PANEL.G_Expected_Summary := 'Used budget <= max budget';

        FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
            L_Manifold_Calc[L_i] := GVL_CONFIG.G_Manifold_Priority[L_i];
        END_FOR;

        FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
            IF GVL_TEST_PANEL.G_Input_Circuit_Enable[L_i] THEN
                L_j := TO_INT(GVL_CONFIG.G_HMI_FloorHeating_Configs[L_i].manifold_id);
                IF (L_j >= 1) AND (L_j <= GVL_CONSTANTS.C_MAX_MANIFOLDS) THEN
                    L_tmp := GVL_TEST_PANEL.G_Input_Circuit_Bias[L_i];
                    IF GVL_TEST_PANEL.G_Input_Guest_Preheat_Enabled AND GVL_TEST_PANEL.G_Input_Circuit_Guest_Preheat[L_i] THEN
                        L_tmp := L_tmp + GVL_TEST_PANEL.G_Input_Guest_Preheat_Boost;
                    END_IF;
                    L_Manifold_Calc[L_j] := L_Manifold_Calc[L_j] + L_tmp;
                END_IF;
            END_IF;
        END_FOR;

        fbDecisionScenario(
            VI_Manifold_Pump_In_Service := GVL_CONFIG.G_Manifold_Pump_In_Service,
            VI_Manifold_Pressure_Fault := GVL_STATUS.G_Diagnostics.Manifold_Pressure_Fault,
            VI_Manifold_Current_Fault := GVL_STATUS.G_Diagnostics.Manifold_Current_Fault,
            VI_Manifold_Thermal_Weight := GVL_CONFIG.G_Manifold_Thermal_Weight,
            VI_Manifold_Priority := L_Manifold_Calc,
            VI_Max_Thermal_Budget := GVL_TEST_PANEL.G_Input_Max_Thermal_Budget
        );

        L_Used := 0.0;
        FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
            GVL_TEST_PANEL.G_Result_Manifold_Allowed[L_i] := fbDecisionScenario.VO_Manifold_Allowed[L_i];
            GVL_TEST_PANEL.G_Result_Manifold_Enabled[L_i] := fbDecisionScenario.VO_Manifold_Enabled[L_i];
            IF fbDecisionScenario.VO_Manifold_Enabled[L_i] THEN
                L_Used := L_Used + GVL_CONFIG.G_Manifold_Thermal_Weight[L_i];
            END_IF;
        END_FOR;

        GVL_TEST_PANEL.G_Result_Used_Thermal_Budget := L_Used;
        GVL_TEST_PANEL.G_Actual_Summary := 'Budget allocation calculated';
        IF L_Used > (GVL_TEST_PANEL.G_Input_Max_Thermal_Budget + 0.001) THEN
            GVL_TEST_PANEL.G_Result_Budget_Exceeded := TRUE;
            GVL_TEST_PANEL.G_Result_Passed := FALSE;
            GVL_TEST_PANEL.G_Result_Status_Msg := 'Budget exceeded';
            GVL_TEST_PANEL.G_Result_Fail_Code := 3001;
        END_IF;

    5:
        GVL_TEST_PANEL.G_Test_Description := 'Coordinator override';
        GVL_TEST_PANEL.G_Current_Test_Name := 'TEST 5 - Coordinator override';
        GVL_TEST_PANEL.G_Test_What_To_Change := 'Set G_Input_Block_Heating TRUE';
        GVL_TEST_PANEL.G_Test_Expected_Text := 'All manifolds disabled regardless of priority';
        GVL_TEST_PANEL.G_Expected_Summary := 'Enabled[] all FALSE when block active';
        FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
            GVL_TEST_PANEL.G_Result_Manifold_Enabled[L_i] := FALSE;
            GVL_TEST_PANEL.G_Result_Manifold_Allowed[L_i] := FALSE;
        END_FOR;
        IF NOT GVL_TEST_PANEL.G_Input_Block_Heating THEN
            GVL_TEST_PANEL.G_Result_Passed := FALSE;
            GVL_TEST_PANEL.G_Result_Status_Msg := 'Block not enabled';
            GVL_TEST_PANEL.G_Result_Fail_Code := 4001;
        ELSE
            GVL_TEST_PANEL.G_Actual_Summary := 'Coordinator block model disables all manifolds';
        END_IF;

    6:
        GVL_TEST_PANEL.G_Test_Description := 'Safety dominance';
        GVL_TEST_PANEL.G_Current_Test_Name := 'TEST 6 - Safety dominance';
        GVL_TEST_PANEL.G_Test_What_To_Change := 'Set G_Input_Safety_Stop TRUE';
        GVL_TEST_PANEL.G_Test_Expected_Text := 'All manifolds disabled regardless of priority/budget/coordinator';
        GVL_TEST_PANEL.G_Expected_Summary := 'Enabled[] all FALSE when safety active';
        FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
            GVL_TEST_PANEL.G_Result_Manifold_Enabled[L_i] := FALSE;
            GVL_TEST_PANEL.G_Result_Manifold_Allowed[L_i] := FALSE;
        END_FOR;
        IF NOT GVL_TEST_PANEL.G_Input_Safety_Stop THEN
            GVL_TEST_PANEL.G_Result_Passed := FALSE;
            GVL_TEST_PANEL.G_Result_Status_Msg := 'Safety not active';
            GVL_TEST_PANEL.G_Result_Fail_Code := 5001;
        ELSE
            GVL_TEST_PANEL.G_Actual_Summary := 'Safety model disables all manifolds';
        END_IF;

    7:
        GVL_TEST_PANEL.G_Test_Description := 'Conflict dominance';
        GVL_TEST_PANEL.G_Current_Test_Name := 'TEST 7 - Conflict dominance';
        GVL_TEST_PANEL.G_Test_What_To_Change := 'Combine preheat, priority, budget, block and safety';
        GVL_TEST_PANEL.G_Test_Expected_Text := 'Safety must dominate all';
        GVL_TEST_PANEL.G_Expected_Summary := 'All manifolds disabled';
        FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
            GVL_TEST_PANEL.G_Result_Manifold_Enabled[L_i] := FALSE;
            GVL_TEST_PANEL.G_Result_Manifold_Allowed[L_i] := FALSE;
        END_FOR;
        IF NOT GVL_TEST_PANEL.G_Input_Safety_Stop THEN
            GVL_TEST_PANEL.G_Result_Passed := FALSE;
            GVL_TEST_PANEL.G_Result_Status_Msg := 'Safety not dominant';
            GVL_TEST_PANEL.G_Result_Fail_Code := 7001;
        ELSE
            GVL_TEST_PANEL.G_Actual_Summary := 'Safety dominates all inputs';
        END_IF;

ELSE
    GVL_TEST_PANEL.G_Result_Passed := FALSE;
    GVL_TEST_PANEL.G_Result_Status_Msg := 'Unknown scenario';
    GVL_TEST_PANEL.G_Result_Fail_Code := 9001;
END_CASE;
// === END SCENARIO_EXECUTION ===

// === BEGIN RESULT_TEXT ===
GVL_TEST_PANEL.G_Last_Result_Passed := GVL_TEST_PANEL.G_Result_Passed;
GVL_TEST_PANEL.G_Last_Fail_Code := GVL_TEST_PANEL.G_Result_Fail_Code;
GVL_TEST_PANEL.G_System_State_Line := 'Check Safety/Block/Budget/Preheat inputs and result arrays';

IF GVL_TEST_PANEL.G_Result_Passed THEN
    GVL_TEST_PANEL.G_Error_Text := '';
    CASE GVL_TEST_PANEL.G_Scenario_ID OF
        1: GVL_TEST_PANEL.G_Test_Result_Line := 'TEST 1 | Single circuit | PASS';
        2: GVL_TEST_PANEL.G_Test_Result_Line := 'TEST 2 | Multi-zone aggregation | PASS';
        3: GVL_TEST_PANEL.G_Test_Result_Line := 'TEST 3 | Preheat influence | PASS';
        4: GVL_TEST_PANEL.G_Test_Result_Line := 'TEST 4 | Budget vs priority | PASS';
        5: GVL_TEST_PANEL.G_Test_Result_Line := 'TEST 5 | Coordinator override | PASS';
        6: GVL_TEST_PANEL.G_Test_Result_Line := 'TEST 6 | Safety dominance | PASS';
        7: GVL_TEST_PANEL.G_Test_Result_Line := 'TEST 7 | Conflict dominance | PASS';
    ELSE
        GVL_TEST_PANEL.G_Test_Result_Line := 'UNKNOWN TEST | PASS';
    END_CASE;
ELSE
    GVL_TEST_PANEL.G_Error_Text := GVL_TEST_PANEL.G_Result_Status_Msg;
    CASE GVL_TEST_PANEL.G_Scenario_ID OF
        1: GVL_TEST_PANEL.G_Test_Result_Line := 'TEST 1 | Single circuit | FAIL';
        2: GVL_TEST_PANEL.G_Test_Result_Line := 'TEST 2 | Multi-zone aggregation | FAIL';
        3: GVL_TEST_PANEL.G_Test_Result_Line := 'TEST 3 | Preheat influence | FAIL';
        4: GVL_TEST_PANEL.G_Test_Result_Line := 'TEST 4 | Budget vs priority | FAIL';
        5: GVL_TEST_PANEL.G_Test_Result_Line := 'TEST 5 | Coordinator override | FAIL';
        6: GVL_TEST_PANEL.G_Test_Result_Line := 'TEST 6 | Safety dominance | FAIL';
        7: GVL_TEST_PANEL.G_Test_Result_Line := 'TEST 7 | Conflict dominance | FAIL';
    ELSE
        GVL_TEST_PANEL.G_Test_Result_Line := 'UNKNOWN TEST | FAIL';
    END_CASE;
END_IF;
// === END RESULT_TEXT ===

// === BEGIN RESULT_MIRROR ===
// RESULT panel mirror
GVL_TEST_PANEL_RESULT.G_Enable := GVL_TEST_PANEL.G_Enable;
GVL_TEST_PANEL_RESULT.G_Scenario_ID := GVL_TEST_PANEL.G_Scenario_ID;
GVL_TEST_PANEL_RESULT.G_Scenario_Run := GVL_TEST_PANEL.G_Scenario_Run;
GVL_TEST_PANEL_RESULT.G_Scenario_Active := GVL_TEST_PANEL.G_Scenario_Active;
GVL_TEST_PANEL_RESULT.G_Test_Result_Line := GVL_TEST_PANEL.G_Test_Result_Line;
GVL_TEST_PANEL_RESULT.G_Result_Passed := GVL_TEST_PANEL.G_Result_Passed;
GVL_TEST_PANEL_RESULT.G_Result_Status_Msg := GVL_TEST_PANEL.G_Result_Status_Msg;
GVL_TEST_PANEL_RESULT.G_Result_Fail_Code := GVL_TEST_PANEL.G_Result_Fail_Code;
GVL_TEST_PANEL_RESULT.G_Result_Base_Priority := GVL_TEST_PANEL.G_Result_Base_Priority;
GVL_TEST_PANEL_RESULT.G_Result_Expected_Adjusted_Priority := GVL_TEST_PANEL.G_Result_Expected_Adjusted_Priority;
GVL_TEST_PANEL_RESULT.G_Result_Actual_Adjusted_Priority := GVL_TEST_PANEL.G_Result_Actual_Adjusted_Priority;
GVL_TEST_PANEL_RESULT.G_Result_Delta := GVL_TEST_PANEL.G_Result_Delta;
GVL_TEST_PANEL_RESULT.G_Result_Budget_Exceeded := GVL_TEST_PANEL.G_Result_Budget_Exceeded;
GVL_TEST_PANEL_RESULT.G_Result_Used_Thermal_Budget := GVL_TEST_PANEL.G_Result_Used_Thermal_Budget;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    GVL_TEST_PANEL_RESULT.G_Result_Manifold_Enabled[L_i] := GVL_TEST_PANEL.G_Result_Manifold_Enabled[L_i];
END_FOR;
// === END RESULT_MIRROR ===

// === BEGIN DEBUG_MIRROR ===
// DEBUG panel mirror
GVL_TEST_PANEL_DEBUG.G_Test_Description := GVL_TEST_PANEL.G_Test_Description;
GVL_TEST_PANEL_DEBUG.G_Test_What_To_Change := GVL_TEST_PANEL.G_Test_What_To_Change;
GVL_TEST_PANEL_DEBUG.G_Test_Expected_Text := GVL_TEST_PANEL.G_Test_Expected_Text;
GVL_TEST_PANEL_DEBUG.G_Expected_Summary := GVL_TEST_PANEL.G_Expected_Summary;
GVL_TEST_PANEL_DEBUG.G_Actual_Summary := GVL_TEST_PANEL.G_Actual_Summary;
GVL_TEST_PANEL_DEBUG.G_Error_Text := GVL_TEST_PANEL.G_Error_Text;
GVL_TEST_PANEL_DEBUG.G_System_State_Line := GVL_TEST_PANEL.G_System_State_Line;
GVL_TEST_PANEL_DEBUG.G_Input_Guest_Preheat_Request := GVL_TEST_PANEL.G_Input_Guest_Preheat_Request;
GVL_TEST_PANEL_DEBUG.G_Input_Guest_Preheat_Enabled := GVL_TEST_PANEL.G_Input_Guest_Preheat_Enabled;
GVL_TEST_PANEL_DEBUG.G_Input_Guest_Preheat_Boost := GVL_TEST_PANEL.G_Input_Guest_Preheat_Boost;
GVL_TEST_PANEL_DEBUG.G_Input_Max_Thermal_Budget := GVL_TEST_PANEL.G_Input_Max_Thermal_Budget;
GVL_TEST_PANEL_DEBUG.G_Input_Block_Heating := GVL_TEST_PANEL.G_Input_Block_Heating;
GVL_TEST_PANEL_DEBUG.G_Input_Safety_Stop := GVL_TEST_PANEL.G_Input_Safety_Stop;
// === END DEBUG_MIRROR ===

fbCoord(
    VI_Fire_Latched := GVL_STATE.G_Safety_Smoke_Latched,
    VI_Gas_Latched := GVL_STATE.G_Safety_Gas_Latched,
    VI_Leak_Latched := GVL_STATE.G_Safety_Leak_Latched,
    VI_IO_Degraded := NOT GVL_STATUS.G_IO_Modules_Online[1],
    VI_Ownership_Violation := GVL_TEST.G_Ownership_Violation,
    VI_Behavior_Mode := GVL_MODE.G_Current_Behavior_Mode
);

GVL_SYSTEM_COORDINATION.G_Block_Heating := fbCoord.VO_Block_Heating OR GVL_HEATING_POLICY.G_Policy_Block_Heating_Request;
GVL_SYSTEM_COORDINATION.G_Block_Ventilation := fbCoord.VO_Block_Ventilation;
GVL_SYSTEM_COORDINATION.G_Block_Lighting_Override := fbCoord.VO_Block_Lighting;
GVL_SYSTEM_COORDINATION.G_Block_Sockets_Override := fbCoord.VO_Block_Sockets;

GVL_SYSTEM_COORDINATION.G_System_Degraded := fbCoord.VO_System_Degraded;
GVL_SYSTEM_COORDINATION.G_Coordination_Code := fbCoord.VO_Code;

L_Mode := GVL_SAFETY_SHUTDOWN.G_Safety_Mode;
L_Recovery := GVL_SAFETY_RECOVERY.G_Recovery_Phase;

GVL_EXPLAINABILITY.G_Last_Safety_Mode := L_Mode;
GVL_EXPLAINABILITY.G_Last_Recovery_Phase := L_Recovery;
GVL_EXPLAINABILITY.G_Last_Update_MS := GVL_TIME_SERVICE.G_Now_MS;

// SAFETY LEVEL
CASE L_Mode OF
    FIRE: GVL_EXPLAINABILITY.G_Reason_Chain_Safety := 'FIRE';
    GAS: GVL_EXPLAINABILITY.G_Reason_Chain_Safety := 'GAS';
    WATER_LEAK: GVL_EXPLAINABILITY.G_Reason_Chain_Safety := 'WATER';
    GLOBAL_STOP: GVL_EXPLAINABILITY.G_Reason_Chain_Safety := 'GLOBAL_STOP';
    EVACUATION: GVL_EXPLAINABILITY.G_Reason_Chain_Safety := 'EVACUATION';
    ELSE
        IF GVL_SAFETY_RECOVERY.G_Recovery_Active THEN
            GVL_EXPLAINABILITY.G_Reason_Chain_Safety := 'RECOVERY';
        ELSE
            GVL_EXPLAINABILITY.G_Reason_Chain_Safety := 'NORMAL';
        END_IF;
END_CASE;

// BEHAVIOR LEVEL
GVL_EXPLAINABILITY.G_Reason_Chain_Behavior := GVL_INTENT_BEHAVIOR.I_Reason_Text;

// COMMAND LEVEL
IF GVL_COMMAND_SHADOW.G_Heating_Block THEN
    L_Command := 'Heating Blocked';
ELSIF GVL_COMMAND_SHADOW.G_Vent_Stop THEN
    L_Command := 'Vent Stopped';
ELSIF GVL_COMMAND_SHADOW.G_Water_Block THEN
