// Current-cycle mismatch count between legacy and shadow command layers
L_Mismatch_Count := 0;

IF GVL_COMMAND.G_Gas_Valve_Close <> GVL_COMMAND_SHADOW.G_Gas_Valve_Close THEN
    L_Mismatch_Count := L_Mismatch_Count + 1;
END_IF;

IF GVL_COMMAND.G_Boiler_Stop <> GVL_COMMAND_SHADOW.G_Boiler_Stop THEN
    L_Mismatch_Count := L_Mismatch_Count + 1;
END_IF;

IF GVL_COMMAND.G_Vent_Stop <> GVL_COMMAND_SHADOW.G_Vent_Stop THEN
    L_Mismatch_Count := L_Mismatch_Count + 1;
END_IF;

IF GVL_COMMAND.G_Supply_100_Req <> GVL_COMMAND_SHADOW.G_Supply_100_Req THEN
    L_Mismatch_Count := L_Mismatch_Count + 1;
END_IF;

IF GVL_COMMAND.G_Supply_80_Req <> GVL_COMMAND_SHADOW.G_Supply_80_Req THEN
    L_Mismatch_Count := L_Mismatch_Count + 1;
END_IF;

IF GVL_COMMAND.G_Vent_PV3_Boost <> GVL_COMMAND_SHADOW.G_Vent_PV3_Boost THEN
    L_Mismatch_Count := L_Mismatch_Count + 1;
END_IF;

IF GVL_COMMAND.G_Close_Valve_35 <> GVL_COMMAND_SHADOW.G_Close_Valve_35 THEN
    L_Mismatch_Count := L_Mismatch_Count + 1;
END_IF;

IF GVL_COMMAND.G_Close_Valve_36 <> GVL_COMMAND_SHADOW.G_Close_Valve_36 THEN
    L_Mismatch_Count := L_Mismatch_Count + 1;
END_IF;

IF GVL_COMMAND.G_Lock_1_Open <> GVL_COMMAND_SHADOW.G_Lock_1_Open THEN
    L_Mismatch_Count := L_Mismatch_Count + 1;
END_IF;

IF GVL_COMMAND.G_Lock_1_Close <> GVL_COMMAND_SHADOW.G_Lock_1_Close THEN
    L_Mismatch_Count := L_Mismatch_Count + 1;
END_IF;

IF GVL_COMMAND.G_Lock_2_Open <> GVL_COMMAND_SHADOW.G_Lock_2_Open THEN
    L_Mismatch_Count := L_Mismatch_Count + 1;
END_IF;

IF GVL_COMMAND.G_Lock_2_Close <> GVL_COMMAND_SHADOW.G_Lock_2_Close THEN
    L_Mismatch_Count := L_Mismatch_Count + 1;
END_IF;

// Gate and wicket comparison
IF GVL_COMMAND.G_Gate_Open <> GVL_COMMAND_SHADOW.G_Gate_Open THEN
    L_Mismatch_Count := L_Mismatch_Count + 1;
END_IF;

IF GVL_COMMAND.G_Wicket_Open <> GVL_COMMAND_SHADOW.G_Wicket_Open THEN
    L_Mismatch_Count := L_Mismatch_Count + 1;
END_IF;

GVL_COMMAND_VERIFY.Command_Mismatch_Count := L_Mismatch_Count;
GVL_COMMAND_VERIFY.Command_Match_OK := (L_Mismatch_Count = 0);
GVL_COMMAND_VERIFY.Command_Mismatch_Active := (L_Mismatch_Count > 0);

IF GVL_INTENT_USER.I_Set_Adapt_Profile_Req THEN

    // block if safety active
    IF (GVL_SAFETY_SHUTDOWN.G_Safety_Mode <> NORMAL) OR GVL_SAFETY_RECOVERY.G_Recovery_Active THEN

        fbTrace(
            iLayer := TRACE_USER,
            iSource := SRC_USER,
            iReason := REASON_SAFETY,
            iValueBool := FALSE,
            iValueReal := 0.0,
            iText := 'Profile change blocked: SAFETY ACTIVE'
        );

    ELSE

        IF (GVL_INTENT_USER.I_Set_Adapt_Profile_Confirm)
           AND (GVL_INTENT_USER.I_User_Access_Level >= 2) THEN

            GVL_BEHAVIOR_ADAPT.G_Adapt_Profile :=
                GVL_INTENT_USER.I_Adapt_Profile_Value;

            IF GVL_INTENT_USER.I_Adapt_Profile_Value = ADAPT_PROFILE_STABLE THEN
                L_Text := 'Adapt profile: STABLE';
            ELSIF GVL_INTENT_USER.I_Adapt_Profile_Value = ADAPT_PROFILE_BALANCED THEN
                L_Text := 'Adapt profile: BALANCED';
            ELSE
                L_Text := 'Adapt profile: AGGRESSIVE';
            END_IF;

            fbTrace(
                iLayer := TRACE_USER,
                iSource := SRC_USER,
                iReason := REASON_USER_REQUEST,
                iValueBool := TRUE,
                iValueReal := TO_REAL(GVL_INTENT_USER.I_User_Access_Level),
                iText := L_Text
            );

        END_IF;

    END_IF;

    GVL_INTENT_USER.I_Set_Adapt_Profile_Req := FALSE;
    GVL_INTENT_USER.I_Set_Adapt_Profile_Confirm := FALSE;

END_IF;

fbPolicy(
